export const bmtnSentences: Sentence[] = [
  {"id":"s_work_bmtn_1_1","chapterId":"ch_work_bmtn_1","text":"●關於《北夢琐言》","sortOrder":1},
  {"id":"s_work_bmtn_1_2","chapterId":"ch_work_bmtn_1","text":"北夢琐言二十卷五代孫光憲撰","sortOrder":2},
  {"id":"s_work_bmtn_1_3","chapterId":"ch_work_bmtn_1","text":"孫光憲，字孟文，自號葆光子。唐末為陵州判官，後唐時避地江陵。歷仕荆南三世，入宋為黃州刺史。此書撰於江陵，記唐武宗以後事，大體前16卷記唐，後4卷記五代，涉及政治軼聞、士大夫言行和社會風俗民情，保存史料極為丰富，雖間及怪異，仍是治晚唐五代社會政治史的重要文獻。後世不少典籍多征引此書，如《太平廣記》引文達247條，《資治通鑒》亦多次引用此書，《舊五代史》援引此書33條，彭元瑞所撰《五代史註》直接征引則多至137條，可見此書的社會价值。","sortOrder":3},
  {"id":"s_work_bmtn_1_4","chapterId":"ch_work_bmtn_1","text":"此書流傳版本也很多，主要有《稗海》本、《雅雨堂丛書》本以及上海圖書馆藏吳氏拜經樓舊抄本等。1960年中華書局據缪荃孫《雲自在龛丛書》，斷句、校勘出版。1981年上海古籍出版社校點本，较善於中華書局1960年本。","sortOrder":4},
  {"id":"s_work_bmtn_2_2","chapterId":"ch_work_bmtn_2","text":"唐自廣明亂離，秘籍亡散。武宗已後，寂寞無聞，朝野遺芳，莫得傳播。仆生自岷峨，官於荆郢。鹹京故事，每愧面牆，遊處之間，专於博訪。頃逢故鳳翔楊玭少尹，多話秦中平時舊說，常記於心。他日渚宮見元澄中允，款狎笑語，多符其說。元公謂舊族一二子弟曰：\"諸賢生在長安，聞事不迨富春。此則存好問之所宏益也。\"厥後每聆一事，未敢孤信，三复參校，然始濡毫。非但垂之空言，亦欲因事勸戒。三紀收拾筐箧，爰因公退，鹹取編連。先以唐朝達賢一言一行列於談次，其有事類相近，自唐至後唐、梁、蜀、江南諸國所得聞知者皆附其末，凡纂得事成三十卷。《禹貢》雲：\"雲土夢作乂。\"《傳》有\"畋於江南之夢\"。鄙從事於荆江之北，題曰《北夢琐言》，琐細形言，大即可知也。雖非經緯之作，庶勉後進子孫，俾希仰前事，亦絲麻中菅蒯也。通方者幸勿多誚焉。","sortOrder":2},
  {"id":"s_work_bmtn_3_1","chapterId":"ch_work_bmtn_3","text":"●卷一","sortOrder":1},
  {"id":"s_work_bmtn_3_2","chapterId":"ch_work_bmtn_3","text":"唐宣宗皇帝好儒雅，每直殿學士從容，未嘗不論前代興亡。頗留心貢舉，嘗於殿柱上自題曰\"乡貢進士李某\"。或宰臣出镇，賦詩以赠之，詞皆清麗。凡對宰臣言政事，即終日忘倦。洎僖宗皇帝好蹴球、斗雞為樂，自以能於步打，謂俳優石野猪曰：\"聯若作步打進士，亦合得一状元。\"野猪對曰：\"或遇尧舜禹湯作禮部侍郎，陛下不免且落第。\"帝笑而已。原其所好優劣，即聖政可知也。","sortOrder":2},
  {"id":"s_work_bmtn_3_3","chapterId":"ch_work_bmtn_3","text":"太尉李德裕幼神俊，憲宗賞之，坐於膝上，父吉甫每以敏辯夸於同列。武相元衡召之，謂曰：\"吾子在家所嗜何書\"意欲探其志也。德裕不應。翌日，元衡具告吉甫，因戲曰：\"公誠涉大癡耳。\"吉甫歸以责之，德裕曰：\"武公身為帝弼，不問理國調陰陽，而問所嗜書。書者，成均禮部之職也。其言不當，所以不應。\"吉甫复告，元衡大慚，由是振名。","sortOrder":3},
  {"id":"s_work_bmtn_3_4","chapterId":"ch_work_bmtn_3","text":"宣宗舅鄭光敕賜雲陽、鄠縣兩莊，皆令免稅。宰臣奏恐非宜，詔曰：\"朕以光元舅，欲優異之，初不細思，是免其賦。爾等每於匡救，必盡公忠。親戚之間，人所難議。苟非愛我，豈盡嘉言。庶事能如斯，天下何忧不治有始有卒，當共守之。\"尋罢。葆光子同僚嘗買一莊，喜其無稅，乃謂曰：\"天下莊產，未有不征。\"同僚以私券見拒。爾後子孫為縣宰定稅，求祈不暇。國舅尚爾，庶僚胡為。","sortOrder":4},
  {"id":"s_work_bmtn_3_5","chapterId":"ch_work_bmtn_3","text":"武宗嗣位，宣宗居皇叔之行，密遊外方。或止江南名山，多識高道僧人。初聽政，謂宰相曰：\"佛者，雖異方之教，深助理本，所可存而勿論，不欲過毀，以傷令德。\"乃遣下詔。會昌中，靈山古跡招提弃废之地，併令复之，委長吏擇僧之高行者居之，唯出家者不得忘度也。懿宗即位，唯以崇佛為事。相國萧仿、裴坦時為常侍諫議，上疏極諫，其略雲：\"臣等聞玄祖之道，用慈俭為先；素王之風，以仁義是首。相沿百世，作則千年。至聖至明，不可易也。如佛者，生於天竺，去彼王宮。割愛中之至難，取滅後之殊勝。名歸象外，理出尘中，非為帝王所能慕也。\"廣引無益有損之義，文多不錄，文理婉順，與韓愈元和中上《請除佛骨表》不異也。懿皇雖聽覽稱奖，竟不能止。末年迎佛骨，才至京師，俄而晏駕。識者謂大丧之兆也。","sortOrder":5},
  {"id":"s_work_bmtn_3_6","chapterId":"ch_work_bmtn_3","text":"唐大中年，兖州奏：\"先差赴慶州行營押官鄭神佐陣没，其室女年二十四，先亡父未行營已前許嫁右驍雄軍健李玄慶，未受财禮。阿鄭知父神佐陣没，遂與李玄慶休親，截發，往慶州北懷安镇收亡父遺骸，到兖州瑕丘縣進賢乡與亡母合葬訖，便於塋內筑庐。\"識者曰：\"女子適邊，取父遺骸合葬。烈而且孝，誠可嘉也。庐墓習於近俗，國不能禁，非也。\"廣引《禮經》而證之。","sortOrder":6},
  {"id":"s_work_bmtn_3_7","chapterId":"ch_work_bmtn_3","text":"唐宣宗朝，日本國王子入貢，善围棋。帝令待詔顧師言與之對手。王子出本國如楸玉局、冷暖玉棋子。蓋玉之蒼者如楸玉色，其冷暖者言冬暖夏涼。人或過說，非也。王子至三十三下，師言懼辱君命，汗手死心始敢落指。王子亦凝目縮臂數四，竟伏不勝，回謂禮賓曰：\"此第幾手\"答曰：\"其第三手也。\"王子願見第一手，禮賓曰：\"勝第三可見第二，勝第二可見第一。\"王子撫局叹曰：\"小國之一不及大國之三。此夷人也，猶不可輕，况中國之士乎。\"葆光子曰：\"蜀簡州刺史安重霸黷货無厭。部民有油客子者，姓邓，能棋，其力粗贍。安辄召與對敵。只令立侍，每落一子，俾其退立於西北牖下，俟我算路然後進之，終日不下十數子而已。邓生倦立且飢，殆不可堪。次日又召，或有諷邓生曰：'此侯好賂，本不為棋，何不獻效而自求退'邓生然之，以中金十鋌獲免，良可笑也。\"","sortOrder":7},
  {"id":"s_work_bmtn_3_8","chapterId":"ch_work_bmtn_3","text":"大中時，工部尚書陳商《立漢文帝废丧議》、《立春秋左傳學議》，以\"孔聖修經，褒貶善惡，類例分明，法家流也。左丘明為魯史，載述時政。惜忠賢之泯滅，恐善惡之失墜。以日系月，修其職官。本非扶助聖言，緣飾經旨，蓋太史氏之流也。舉其《春秋》則明白而有實，合之《左氏》則丛雜而無征。杜元凯曾不思夫子所以為經當與《詩》《書》《周易》等列，丘明所以為史當與司馬遷、班固等列，取二義乖剌不侔之語參而貫之，故微旨有所未周，琬章有所未一。\"文多不載。又睹吳郡陆龟蒙亦引啖助、趙匡為證，正與陳工部義同。葆光子同僚王公貞范精於《春秋》，有驳正元凯之谬，條緒甚多，人鹹訝之。獨鄙夫嘗以陳、陆、啖、趙之論竊然之，非苟合也，唯義所在。","sortOrder":8},
  {"id":"s_work_bmtn_3_9","chapterId":"ch_work_bmtn_3","text":"白少傅居易文章冠世，不跻大位。先是劉禹錫大和中為賓客時，李太尉德裕同分司東都。禹錫謁於德裕曰：\"近曾得《白居易文集》否\"德裕曰：\"累有相示，別令收貯，然未一披。今日為吾子覽之。\"及取看，盈其箱笥，没於尘坌。既啟之而复卷之，謂禹錫曰：\"吾於此人不足久矣。其文章精絕，何必覽焉。但恐回吾之心，所以不欲觀覽。\"其見抑也如此。衣冠之士併皆忌之，鹹曰：\"有學士才，非宰臣器。\"識者於其答製中見經纶之用，為時所排，比贾誼在漢文之朝不為卿相知。人皆惜之。葆光子曰：\"李衛公之抑忌白少傅，舉類而知也。初文宗命德裕論朝中朋党，首以楊虞卿、牛僧孺為言。楊、牛即白公密友也。其不引翼，義在於斯，非抑文章也，慮其朋比而製掣也。\"","sortOrder":9},
  {"id":"s_work_bmtn_3_10","chapterId":"ch_work_bmtn_3","text":"相國牛僧孺，字思黯，或言牛仙客之後，居宛葉之間。少单貧，力學，有倜傥之志。唐永貞中，擢進士第，時與同辈過政事堂。宰相謂曰：\"扫廳奉候。\"僧孺獨出曰：\"不敢。\"眾耸異之。元和初登製科，歷省郎、中書舍人、御史、中書門下平章事、扬州、建州兩镇、東都留守、左仆射。先是，撰《周秦行記》，李德裕切言短之。大中初卒，未賜謚。後白敏中入相，乃奏定謚曰\"簡\"，白居易曰\"文\"。葆光子曰\"僧孺登庸在德裕之先，又非忌才所能掩抑。今以牛之才術比李之功勋，自然知其臧否也。且《周秦行記》非所宜言，德裕著論而罪之，正人覽記而駭之。勿謂衛公掩賢妒善，牛相不罹大禍，亦幸而免。\"","sortOrder":10},
  {"id":"s_work_bmtn_3_11","chapterId":"ch_work_bmtn_3","text":"唐大中末，相國令狐綯罢相，其子滈應進士舉在父未罢相前，預拔文解及第。諫議大夫崔瑄上疏，述滈弄父權，势傾天下，以\"舉人文卷須十月前送納，豈可父身尚居於枢務，男私拔其解名，幹撓主司，侮弄文法恐奸欺得路，孤直杜門\"雲雲，請下御史台推勘。疏留中不出。葆光子曰：\"令孤公在大中之初，傾陷李太尉，唯以附會李紳而殺吳湘。又擅改元和史，又言賂遺閹宦，殊不似德裕立功於國，自俭立身。掎其小瑕，忘其大美。洎身居巖廟，別無所長，諫官上章可見之矣。與朱崖之終始殆難比焉。\"","sortOrder":11},
  {"id":"s_work_bmtn_3_12","chapterId":"ch_work_bmtn_3","text":"唐大和中，李德裕镇浙西。有劉三复者，少貧苦學，有才思。時中人赍御書至以賜德裕，德裕试其所為，謂曰：\"子可為我草表，能立就或歸以創之。\"三复曰：\"文理貴中不貴其速。\"德裕以為當言。三复又請曰：\"漁歌樵唱皆傳公述作，願以文集見示。\"德裕出數軸與之。三复乃體而為表，德裕嘉之，因遣詣闕求试，果登第，歷任台閣。三复能記三生事，雲曾為馬。馬常患渴，望驿而嘶，傷其蹄則心連痛。後三复乘馬過硗確之地必為缓辔，轍有石必去之。其家不施門限，慮傷馬蹄也。其子鄴敕賜及第，登廊廟，上表雪德裕以朱崖神榇歸葬洛中，報先恩也。士大夫美之。","sortOrder":12},
  {"id":"s_work_bmtn_3_13","chapterId":"ch_work_bmtn_3","text":"杜邠公悰，司徒佑之孫，父曰從鬱，歷遺補畿令。悰尚憲宗岐陽公主，累居大镇，复居廊廟。無他才，未嘗延接寒素，甘食竊位而已。有朝士貽書於悰曰：\"公以硕大敦庞之德，生於文明之運。矢厥謨猷，出入隆顯。\"極言譏之，文多不錄。時人號為禿角犀。凡莅藩镇，未嘗斷獄，系囚死而不問，宜其责之。呜呼！處高位而妨賢，享厚祿以丰已。無功於國，無德於民。富貴而終，斯又何人也！子孫不享，何莫由斯。","sortOrder":13},
  {"id":"s_work_bmtn_3_14","chapterId":"ch_work_bmtn_3","text":"唐文宗皇帝謂宰相曰：\"太宗得魏征采拾闕遺，弼成聖政。今我得魏謨，於疑似之間必極匡諫。雖不敢希及正觀之政，庶幾處無過之地。今授謨右補闕，委舍人善為之詞。又問謨曰：\"卿家有何圖書\"謨曰：\"家書悉無，唯有文貞公笏在。\"文宗令進來。鄭覃在侧，曰：\"在人不在笏。\"文宗曰：\"卿浑未晓。但'甘棠'之義，非要笏也。\"","sortOrder":14},
  {"id":"s_work_bmtn_4_1","chapterId":"ch_work_bmtn_4","text":"●卷二","sortOrder":1},
  {"id":"s_work_bmtn_4_2","chapterId":"ch_work_bmtn_4","text":"鹹通中，進士皮日休進書兩通。其一請以孟子為學科，其略雲\"臣聞聖人之道不過乎經，經之降者不過乎史，史之降者不過乎子。子不異道者，孟子也。舍是而諸子者必斥乎經史，為聖人之賊也\"雲雲。文多不載。請废莊列之書，以孟子為主。有能通其義者，其科選請同明經也。其二請以韓文公愈配饗太學，其略曰\"臣聞聖人之道不過乎求用。用於生前則一時可知也，用於死後則萬世可知也\"雲雲。又雲：\"孟子、荀卿翼辅孔道，以至於文中子。文中之道曠矣，其幾乎室授者唯韓愈焉。蹴及楊墨，蹂踐釋老，故得孔道，炳然如日星焉。吾唐以來，一人而已。苟不得在二十一賢之數列，則典禮未為備也。\"日休先字逸少，後字袭美，襄陽竟陵人也。業文隱鹿門山，號醉吟先生。竊比大聖，榜未及第。禮部侍郎鄭愚以其貌不扬，戲之曰：\"子之才學甚富，如一目何\"休對曰：\"侍郎不可以一目废二目。\"謂不以人废言也。舉子鹹推伏之。官至國子博士。寓蘇州，與陆龟蒙為文友。著《文藪》十卷，《皮子》三卷，人多傳之。黃寇中遇害，其子為錢尚父吳越相。","sortOrder":2},
  {"id":"s_work_bmtn_4_3","chapterId":"ch_work_bmtn_4","text":"宣宗時，相國令狐綯最受恩遇而怙權，尤忌勝己。以其子滈不解而第，為張雲、劉蜕、崔瑄叠上疏疏之。宣宗優容，綯出镇維扬，上表訴之冤，其略雲：\"一從先帝久次中書，得臣恩者謂臣好，不得臣恩者謂臣弱。臣非美酒美肉，安能啖眾人之口！\"時以執己之短，取誚於人。或雲曾以故事訪於溫岐，對以其\"事出《南華》\"，且曰：\"非僻書也，或冀相公燮理之暇時宜覽古。\"綯益怒之，乃奏岐有才無行，不宜與第。會宣宗私行為溫岐所忤，乃授方城尉。所以岐詩雲：\"因知此恨人多積，悔讀《南華》第二篇。\"又李商隱，綯父楚之故吏也，殊不展分，商隱憾之，因題廳閣，落句雲：\"郎君官重施行馬，東閣無因許再窥。\"亦怒之。官止使下員外也。江東羅隱亦受知於綯，畢竟無成，有詩《哭相國》雲：\"深恩無以報，底事是柴荆。\"以三才子怨望，即知綯之遺賢也。","sortOrder":3},
  {"id":"s_work_bmtn_4_4","chapterId":"ch_work_bmtn_4","text":"唐田弘正之領镇州，三軍殺之而立王庭凑，即王武俊支屬也。庭凑生於別墅，嘗有鳩數十只朝集庭树，幕集簷下。有里人骆德播異之。及長，骈胁，善陰符鬼穀之書。歷軍職，得士心。曾使河陽回，在中路以酒困寢於路隅，忽有一人荷策而過，熟视之，曰：\"貴當列土，非常人也。\"仆者寤以告庭凑，庭凑馳數里及之，致敬而問，自雲\"濟源骆山人也。向見君鼻中之氣，左如龍而右如虎。龍虎氣交王在今秋，子孫相繼滿一百年。\"又雲：\"家之庭合有大树，树及於堂，是其兆也。\"是年果為三軍扶立為留後，歸別墅而庭树婆娑，暗庇舍矣。墅西飛龍山神，庭凑往祭之。將及祠百步，有人具冠冕折腰於庭凑。及入廟，神乃侧坐。至今面東，廟宇尚存焉。庭凑清俭公正，忠於朝廷，勤於軍民，子孫世嗣為镇帥。至朱梁時，王鎔封趙王，為部將張文禮滅之。","sortOrder":4},
  {"id":"s_work_bmtn_4_5","chapterId":"ch_work_bmtn_4","text":"唐馬植相公曾镇安南，安撫軍民，懷柔蠻獠，废珠池，尚俭素。李琢後镇是邦，用法大酷，軍城遠出而屬南蠻，六七年間，勞動兵役。鹹通七年，高骈收复之。先是，荆、徐間征役拒蠻，人甚苦之。有舉子聞許卒二千没於蠻乡，有詩刺曰：\"南荒不擇吏，致我交趾覆。聯綿三四年，致我交趾辱。懦者斗則退，武者兵益黷。軍容滿天下，戰將多金玉，刮得齊民瘡，分為猛士祿。雄雄許昌師，忠武冠其族。去為萬騎風，住為一川肉。時有踐卒回，千門萬戶哭。哀聲動闾里，怨氣成山穀。誰能聽鼓聲，不忍看金鏃。念此堪淚流，悠悠潁川绿。\"吟此詩有以見失於授任，為國家生事。大東之苦，斯其類乎。","sortOrder":5},
  {"id":"s_work_bmtn_4_6","chapterId":"ch_work_bmtn_4","text":"安南高骈奏开本州海路。初交趾以北距南海，有水路，多覆巨舟。骈往视之，乃有橫石隱隱然在水中，因奏請开凿以通南海之利。其表略雲：\"人牵利楫，石限橫津。才登一去之舟，便作九泉之計。\"時有詔聽之，乃召工者啖以厚利，竟削其石。交廣之利民至今賴之以濟焉。或言骈以術假雷電以开之，未知其詳。葆光子嘗聞閩王王審知患海畔石碕奇為舟楫之梗，一夜夢吳安王許以开导，乃命判官劉山甫躬往祈祭。三奠才畢，風雷勃興。山甫凭高觀焉，見海中有黃物，可長千百丈，奋躍攻击。凡三日，晴霁，見石港通畅，便於泛涉。於時錄奏，賜名甘棠港。即渤海假神之力又何怪焉亦號此地為天威路，實神功也。","sortOrder":6},
  {"id":"s_work_bmtn_4_7","chapterId":"ch_work_bmtn_4","text":"鹹通中，禮部侍郎高湜知舉，榜內孤貧者公乘亿賦詩三百首，人多書於屋壁。許棠有《洞庭詩》尤工，詩人謂之\"許洞庭\"。最奇者有聂夷中，河南中都人，少貧苦，精於古體，有《公子家》詩雲：\"种花於西園，花發青樓道。花下一禾生，去之為惡草。\"又《詠田家》詩雲：\"父耕原上田，子斫山下荒。六月禾未秀，官家已修仓。\"又雲：\"鋤禾日當午，汗滴禾下土。誰念盤中餐，粒粒皆辛苦。\"又雲：\"二月賣新絲，五月粜新穀。医得眼前瘡，剜却心頭肉。我願君王心，化為光明燭。不照綺羅筵，只照逃亡屋。\"所謂言近意遠，合《三百篇》之旨也。盛得三人，見湜之公道也。葆光子嘗有同僚示我調舉時詩卷，內一句雲\"科松為荫花\"，因譏之曰：\"贾浪仙雲：'空庭唯有竹，閒地擬栽松。'吾子與贾生，春蘭秋菊也。\"他日赴達官牡丹宴，欄中有兩松對植，立命斧斫之，以其荫花。此侯席上於愚有得色，默不敢答，亦可知也。","sortOrder":7},
  {"id":"s_work_bmtn_4_8","chapterId":"ch_work_bmtn_4","text":"王文懿公起三任節镇，扬歷省寺，赠守太尉。文宗頗重之，曾為詩寫於太子之笏以扬之，又畫儀形於便殿，師友目之曰\"當代仲尼\"。雖歷外镇，家無餘财。知其甚貧，詔以仙韶院樂官逐月俸錢五百貫給之。起昧於理家，俸入其家，盡為仆妾所有，耄年寒餒，故加給焉。於時識者以起不能陳遜而與伶人分俸，利其苟得，此為短也。葆光子曰：\"士人之家唯恥货殖，至於荷畚執耒，灌園鬻蔬，未有祿以代耕，豈空器而為養安可忘甘苦不迨晨昏今之世祿嚣薄，不能撙節，稍丰則飫其狗彘，少歉則困彼妻孥，而雲安貧，吾無所取。唯衣與食，所謂切身。傥德望名品未若王相國者，得不思俭而足用乎。\"","sortOrder":8},
  {"id":"s_work_bmtn_5_1","chapterId":"ch_work_bmtn_5","text":"●卷三","sortOrder":1},
  {"id":"s_work_bmtn_5_2","chapterId":"ch_work_bmtn_5","text":"唐相國李太尉德裕抑退浮薄，奖拔孤寒。於時朝貴朋党，掌武破之，由是結怨。而絕於附會，門無賓客。唯進士盧肇，宜春人，有奇才，每謁見，許脱衫從容。舊例禮部放榜，先禀朝廷，恐有親屬言荐。會昌三年，王相國起知舉，先白掌武。乃曰：\"某不荐人，然奉贺今年榜中得一状元也。\"起未喻其旨，复進親吏於相門侦問，吏曰：\"相公於舉子中獨有盧肇久接從容。\"起相曰：\"果在此也。\"其年盧肇為状頭及第。時論曰：盧雖受知於掌武，無妨主司之公道也。","sortOrder":2},
  {"id":"s_work_bmtn_5_3","chapterId":"ch_work_bmtn_5","text":"唐相畢諴，吳乡人，詞學器度冠於儕流。擢進士，未遂其志，嘗謁一受知朝士者，希為改名，以期亨達。此朝士譏其鹾贾之子。請改為字相國，忻然受而謝之。竟以此名登第，致位台辅。前之朝士漸悔交集也。","sortOrder":3},
  {"id":"s_work_bmtn_5_4","chapterId":"ch_work_bmtn_5","text":"唐段相文昌家寓江陵。少以貧窭修進，常患口食不給，每聽曾口寺斋鐘動辄詣謁餐，為寺僧所厭。自此乃斋後扣鐘，冀其晚屆而不逮食也。後入登台座，連出大镇，拜荆南節度，有詩《題曾口寺》雲\"曾遇闍黎飯後鐘\"，蓋為此也。富貴後打金莲花盆盛水濯足，徐相商致書規之，邹平曰：\"人生幾何，要酬平生不足也。\"夏侯孜相國未偶，伶俜風尘，蹇驢無故墜井。每及朝士之門，舍逆旅之馆，多有齟齬，時人號曰\"不利市秀才\"。後登將相。何先塞而後通也。","sortOrder":4},
  {"id":"s_work_bmtn_5_5","chapterId":"ch_work_bmtn_5","text":"唐李固言生於鳳翔莊墅，雅性長厚，未習參謁。始應進士舉，舍於親表柳氏京第。諸柳崑仲率多戲謔，以相國不谙人事，俾習趨揖之儀。俟其磬折，密於鳥巾上帖文字雲\"此處有屋僦賃\"。相國不覺，及出，朝士見而笑之。許孟容守常侍，朝中鄙此官，號曰\"貂郤\"，固不能為人延譽也。相國始以所業求知謀於諸柳，諸柳與导行卷去處，先令投謁許常侍。相國果詣騎省，高陽公慚謝曰：\"某官緒極閒冷，不足發君子聲采。\"雖然，已藏之於心。又睹乌巾上文字，知其朴质無何。來年許公知禮闈，李相國居状頭及第。是知柳氏之戲侮，足致隴西之速遇也。","sortOrder":5},
  {"id":"s_work_bmtn_5_6","chapterId":"ch_work_bmtn_5","text":"杜邠公悰位極人臣，富貴無比。嘗與同列言平生不稱意有三：其一為澧州刺史，其二貶司農卿，其三自西川移镇廣陵，舟次瞿塘，左右為駭浪所驚，呼唤不暇，渴甚，自泼湯茶吃也。镇荆州日，諸院姊妹多在渚宮寄寓，貧困尤甚，相國未嘗拯濟。至於節腊，一無沾遺。有乘肩舆至衙門詬骂者，亦不省問之。凡莅方镇，不理獄訟。在鳳翔洎西川，系囚畢政，無輕無重，任其殍殕。人有從劍門拾得裹漆器文書，乃成都具獄案牍。略不垂愍，斯又何心載！","sortOrder":6},
  {"id":"s_work_bmtn_5_7","chapterId":"ch_work_bmtn_5","text":"李太師光顏以大勋康國，品位穹崇。愛女未聘，幕僚謂其必選佳婿，因從容語次，盛譽一鄭秀才詞學門閥人韻風流異常，冀太師以子妻之。他日又言之，太師謝幕僚曰：\"李光顏一健兒也，遭遇多難，偶立微功，豈可妄求名族，以掇流言乎某已選得一佳婿，諸賢未見。\"乃召一客司小將指之曰：\"此即某女之匹也。\"超三五階軍職，厚與金帛而已。從事許當曰：\"李太師建定難之勋，懷弓藏之慮。武寧保境，止務圖存。而欲結援名家，非其志也。與夫必娶高國，求婚王謝，何其遠哉！\"","sortOrder":7},
  {"id":"s_work_bmtn_5_8","chapterId":"ch_work_bmtn_5","text":"王文公凝清修重德，冠絕當時。每就寢息，必叉手而臥，慮夢寐中見先靈也。食?飥面，不過十八片。曾典絳州，於時司空圖侍郎方應進士舉，自別墅到郡謁見，後更不訪，親知閽吏遽申司空秀才出郭矣。或入郭訪親知，即不造郡斋。琅琊知之，謂其专敬，愈重之。及知舉日，司空一捷列第四人登科，同年訝其名姓甚暗，成事太速，有鄙薄者號為\"司徒空\"。琅琊知有此說，因召一榜門生。开筵宣言於眾曰：\"某叨忝文柄，今年榜帖全為司空先辈一人而已。\"由是聲采益振。爾後為御史分司。舊相盧公携訪之，乃留詩曰：\"氏族司空貴，官班御史雄。老夫如且在，未可叹途窮。\"其為名德所重也如此。","sortOrder":8},
  {"id":"s_work_bmtn_5_9","chapterId":"ch_work_bmtn_5","text":"唐相國劉公瞻，其先人讳景，本連州人。少為漢南鄭司徒掌箋劄，因題商山驿侧泉石，滎陽奇之，勉以進修，俾前驿換麻衣執贽之。後致解荐，擢進士第，歷台省。瞻相孤貧有藝，雖登科第不預急流。任大理評事日饘粥不給，嘗於安國寺相識僧處謁餐，留所業文數軸置在僧幾。致仕劉軍容玄冀遊寺，見此文卷，甚奇之。怜其貧窭，厚有濟恤。又知其連州人，朝無強援，謂僧曰：\"某雖閒废，能為此人致宰相。\"爾後授河中少尹，幕僚有貴族浮薄者蔑视之。一旦有命征入，蒲尹張筵而祖之。浮薄幕客呼相國為尹公，曰：\"歸朝作何官職\"相國對曰：\"得路即作宰相。\"此郎大笑之，在席亦有異其言者。自是以水部員外知製誥，相次入翰林，以至大拜也。","sortOrder":9},
  {"id":"s_work_bmtn_5_10","chapterId":"ch_work_bmtn_5","text":"唐相國李公福河中永樂有宅，庭槐一本抽三枝，直過當舍屋脊，一枝不及。相國同堂崑弟三人，曰石、曰程，皆登宰執，唯福一人歷镇使相而已。近者石晉朝趙令公瑩家庭有檽棗树，婆娑異常，四遠俱見。有望氣者詣其鄰里，問人雲：\"此家合有登宰辅者？\"里叟曰：\"無之。然趙令先德小字相之兒，得非此應乎？\"術士曰：\"王氣方盛，不在身，當其子孫。\"爾後中令由太原判官大拜，出將入相，則前言果效矣。凡士之宦達非止一途，或以才升，或以命遇，則盛衰之氣亦隨人而效之。向者槐棗異常，豈非王氣先集耶？不然，何榮茂挺特拔耸之如是也！","sortOrder":10},
  {"id":"s_work_bmtn_5_11","chapterId":"ch_work_bmtn_5","text":"唐渤海王太尉高公骈镇蜀日，因巡邊至資中郡，舍於刺史衙。對郡山顶有开元佛寺，是夜黃昏，僧徒禮贊螺呗間作。渤海命軍候悉擒械之，來晨笞背斥逐，召將吏而謂之曰：\"僧徒禮念亦無罪過，但以此寺十年後當有禿丁數千作亂，我故以是厭之。\"其後土人皆髡發執兵號大髡小髡，據此寺為寨，陵胁州將。果葉渤海之言。時稱骈好妖術，斯亦或然之验與。","sortOrder":11},
  {"id":"s_work_bmtn_5_12","chapterId":"ch_work_bmtn_5","text":"唐王中令铎重德名家，位望崇顯，率由文雅，然非定亂之才。镇渚宮為都統，以御黃巢寇兵漸近。先是，赴镇以姬妾自隨，其內未行，本以妒忌。忽報夫人離京在道，中令謂從事曰：\"黃巢，漸以南來，夫人又自北至。旦夕情味，何以安處\"幕僚戲曰：\"不如降黃巢。\"公亦大笑之。洎荆州失守，复把潼關。黃巢差人傳語雲：\"令公儒生，非是我敵。請自退避，無辱鋒刃。\"於是弃關隨僖皇播遷於蜀。再授都統，收复京都，大勋成，竟罹非命。時議曰：\"黃巢過江，高太尉不能拒捍，豈王中令儒懦所能應变乎？\"落都統後有詩，其要雲：\"敕詔已聞來闕下，檄書猶未遍軍前。\"亦志在其中也。","sortOrder":12},
  {"id":"s_work_bmtn_5_13","chapterId":"ch_work_bmtn_5","text":"唐路侍中嚴，風貌之美為世所聞。镇成都日，委執政於孔目吏邊鹹，日以妓樂自隨，宴於江津。都人士女懷掷果之羨，雖衛玠、潘嶽不足為比。善巾裹，蜀人見必效之。後乃翦紗巾之腳以異於眾也。闾巷有袨服修容者，人必譏之曰：\"爾非路侍中耶\"嘗過鬻豚之肆，見儈豕者謂屠者曰：\"此豚端正，路侍中不如。\"用之比方，良可笑也。以官妓行雲等十人侍宴。移镇渚宮日，於合江亭離筵赠行雲等《感恩多》詞，有\"離魂何處斷，煙雨江南岸\"，至今播於倡樓也。","sortOrder":13},
  {"id":"s_work_bmtn_5_14","chapterId":"ch_work_bmtn_5","text":"薛能尚書镇鄆州，見舉進士者必加異禮。李勋尚書先德為衙前將校，八座方為客司小子弟，亦負文藻，潛慕進修，因舍歸田里。未逾歲，服麻衣，執所業於元戎。左右具白其行止，不請引見。元戎曰：\"此子慕善，才與不才，安可拒之某今自見其人质清秀，复覽其文卷，深器重之。\"乃出郵巡職牒一通與八座先德，俾罢職司閒居，恐妨令子脩進爾。後果策名第，扬歷清顯，出為鄆州節度也。","sortOrder":14},
  {"id":"s_work_bmtn_5_15","chapterId":"ch_work_bmtn_5","text":"唐鄭愚尚書，廣州人，雄才奧學，擢進士第，扬歷清顯，聲稱烜然。而性本好華，以錦為半臂。崔魏公铉镇荆南，滎陽除廣南節製，經過，魏公以常禮延遇。滎陽舉進士時未嘗以文章及魏公門，此日於客次換麻衣，先贽所業。魏公覽其卷首，尋已賞叹至三四，不覺曰：\"真銷得錦半臂也。\"又以魏公故相，合具軍儀廷參，不得已而受之。魏公曰：\"文武之道備見之矣。\"其钦服形於辭色也。或曰滎陽因醉眠，左右見一白猪。蓋杜征南蛇吐之類。","sortOrder":15},
  {"id":"s_work_bmtn_5_16","chapterId":"ch_work_bmtn_5","text":"唐相國韦公宙善治生，江陵府東有別業，良田美產，最號膏腴，而積稻如坻，皆為滯穗。鹹通初，除廣州節度使。懿宗以番禺珠翠之地，垂貪泉之戒。京兆從容奏對曰：\"江陵莊積穀尚有七千堆，固無所貪。\"懿皇曰：\"此可謂之足穀翁也。\"","sortOrder":16},
  {"id":"s_work_bmtn_5_17","chapterId":"ch_work_bmtn_5","text":"唐李當尚書镇南梁日，境內多有朝士莊產，子孫侨寓其間，而不肖者相效為非。前政以其各有階緣，弗克禁止，闾巷苦之。八座嚴明有斷，處分宽織蔑籠，召其尤者，詰其家世譜第，在朝姻親。乃曰：\"郎君籍如是地望，作如此行止，無乃辱於存亡乎今日所懲，賢親眷聞之，必賞老夫勉旃。\"遽命盛以竹籠沉於漢江。由是其儕惕息，各務戢斂也。崔珏侍御家寄荆州，二子凶惡。節度使劉都尉判之曰：\"崔氏二男，荆南三害，不免行刑也。\"","sortOrder":17},
  {"id":"s_work_bmtn_5_18","chapterId":"ch_work_bmtn_5","text":"唐吳行魯尚書，彭州人。少年事內官西門軍容，小心畏慎，每夜常溫溺器以奉之，深得中尉之意。或一日為洗足，中尉以腳下文理示之曰：\"如此文理，爭教不作十軍容使。\"行魯拜曰：\"此亦無凭，某亦有之，何為常執厮仆之役。\"乃脱屦呈之。中尉嗟叹謂曰：\"汝但忠孝，我終為汝成之。\"爾後假以軍職除彭州刺史，盧耽相公表為西川行軍司馬御蠻有功，歷東、西川、山南三镇節旄。《除西川製》雲：\"為命代之英雄，作人中之祥瑞。\"譏之也。歷圖南為西川副使，隨府罢職，行魯欲延辟之。圖南素薄行魯，聞之大笑曰：\"不能翦頭刺面而趨侍健兒乎。\"自使院乘馬不歸私第，直出北郭，家人遽結束而追之。張雲起居為成都少尹，常出輕言，為行魯酖殺之。","sortOrder":18},
  {"id":"s_work_bmtn_5_19","chapterId":"ch_work_bmtn_5","text":"唐崔侍中安潛崇奉釋氏，鮮茹葷血。唯於刑辟常自躬親，雖僧人犯罪未嘗屈法。於廳事前慮囚必溫顏恤惻以盡其情，有大辟者俾先示以判語，賜以酒食，而付於法。镇西川三年，唯多蔬食。宴諸司，以面及蒟蒻之類染作顏色，用象豚肩羊臑脍炙之屬，皆逼真也，時人比於梁武。而頻於宅使堂前弄傀儡子，軍人百姓穿宅觀看，一無禁止。而中壶預政，以玷盛德，惜哉！","sortOrder":19},
  {"id":"s_work_bmtn_5_20","chapterId":"ch_work_bmtn_5","text":"唐劉舍人蜕，桐庐人。早以文學應進士舉，其先德戒之曰：\"任汝進取，窮之與達，不望於汝。吾若没後，慎勿祭祀。\"乃乘扁舟以漁釣自娱，竟不知其所適。紫微歷登華貫，出典商於，霜露之思，於是乎止。臨終亦戒其子，如先考之命。蜀禮部尚書纂即其息也，嘗與同列言之。君子曰：名教之家重於丧祭。劉氏先德是何人斯苟同隱逸之流，何傷菽水之禮。紫微以儒而進，爵比通侯，遵乃父之緒言，紊先王之舊製，以時之敬能便废乎大彭通人，抑有其說，時未喻也。","sortOrder":20},
  {"id":"s_work_bmtn_5_21","chapterId":"ch_work_bmtn_5","text":"大中四年，進士冯涓登第，榜中文譽最高。是歲，新羅國起樓，厚赍金帛，奏請撰記，時人榮之。初除京兆府參軍，恩地即杜相審權也。杜有江西之拜，製書未行，先召長樂公密話，垂延辟之命，欲以南昌箋奏任之，戒令勿泄。長樂公拜謝辭出宅，速鞭而歸於通衢。遇友人鄭賨，見其喜形於色，駐馬恳詰。長樂遽以恩地之辟告之，滎陽尋捧刺詣京兆門謁贺，具言得於冯先辈也。京兆嗟憤而鄙其淺露。洎製下开幕，冯不預焉。心緒忧疑，莫知所以。廉車發日，自霸桥乘肩舆，門生鹹在。長樂拜別，京兆公長揖冯曰：\"勉旃。\"由是嚣浮之譽遍於搢紳，竟不通顯。中間有涉交通中貴，愈招清議，官止祠部郎中、眉州刺史，仕蜀至御史大夫。","sortOrder":21},
  {"id":"s_work_bmtn_5_22","chapterId":"ch_work_bmtn_5","text":"唐鹹通中，荆州有書生號唐五經者，學識精博，實曰鸿儒。旨趣甚高，人所師仰，聚徒五百辈，以束脩自給，優遊卒歲，有西河濟南之風，幕寮多與之遊。常謂人曰：\"不肖子弟有三变：第一变為蝗虫，謂鬻莊而食也；第二变為蠹魚，謂鬻書而食也；第三变為大虫，謂賣奴婢而食也。三食之辈，何代無之\"","sortOrder":22},
  {"id":"s_work_bmtn_5_23","chapterId":"ch_work_bmtn_5","text":"薛保遜，名家子，恃才與地，凡所評品，士子以之升降，時號為\"浮薄相國\"。夏侯孜尤惡之。其堂弟因名保厚以異之，由是不睦。內子盧氏與其良人操尚略同，因季父薛監來省，盧新婦出參。俟其去後，命水涤門閾。薛監知而大怒，經宰相疏之。保遜因謫授澧州司馬，凡七年不代。夏侯孜出镇，魏相謨登庸，方有征拜而殒於郡。愚曾睹薛文數幅，其一雲：\"餞交親於灞上，止逆旅氏，見數物象人。詰之，口辄動，皆雲江淮嶺表州縣官也。呜呼，天之生民，為此辈笞撻。\"又《觀優》雲：\"緋胡折窣。莽轉而出。眾人皆笑，唯保遜不會。\"其輕物皆此類也。盧虔灌罢夔州，以其為姊妹夫，径至澧州慰省，回至郵亭，回望而笑曰：\"豈意薛保遜一旦接軍事李判官，打《楊柳枝》乎！\"","sortOrder":23},
  {"id":"s_work_bmtn_5_24","chapterId":"ch_work_bmtn_5","text":"蜀之士子莫不酤酒，慕相如涤器之風也。陳會郎中家以當爐為業，為不扫街，官吏殴之。其母甚賢，勉以修進，不許歸乡，以成名為期。每歲糇糧紙筆衣服仆馬皆自成都赍致。郎中業八韻，唯《螳螂賦》大行。大和元年及第，李相固言覽報状，處分厢界，收下酒旆，阖其戶，家人猶拒之。逡巡贺登第，乃聖善奖訓之力也。後為白中令子婿，西川副使，連典彭、漢兩郡而終。","sortOrder":24},
  {"id":"s_work_bmtn_5_25","chapterId":"ch_work_bmtn_5","text":"唐劉仆射崇龟以清俭自居，甚招物論。嘗召同列餐苦荬饆饠，朝士有知其矯，乃潛問小蒼頭曰：\"仆射晨餐何物\"蒼頭曰：\"泼生吃了也。\"朝士聞而哂之。及镇番禺，效吳隱之為人。京國親知貧乏者顒俟濡救，但畫荔枝圖，自作賦以遺之。後薨於嶺表。扶護靈榇經渚宮，家人鬻海珍珠翠於市，時人譏之。","sortOrder":25},
  {"id":"s_work_bmtn_5_26","chapterId":"ch_work_bmtn_5","text":"唐趙大夫崇凝重清介，門無雜賓，慕王濛、劉真長之風也。標格清峻不為文章，號曰無字碑。每遇轉官，舊例各舉一人自代，亚台未嘗舉人，雲：\"朝中無可代己也。\"世亦以此少之。梁相張策嘗為僧，返俗應舉。亚台鄙之。或曰：\"劉軻、蔡京得非僧乎？\"亚台曰：\"劉、蔡辈雖作僧，未為人知，翻然貢藝，有何不可張策衣冠子弟，無故出家，不能參禪訪道，抗跡尘外，乃於御帘前進詩，希望恩泽。如此行止，豈掩人口。某十度知舉，十度斥之。\"清河公乃東依梁主而求际會，蓋為天水拒弃，竟為梁相也。","sortOrder":26},
  {"id":"s_work_bmtn_6_1","chapterId":"ch_work_bmtn_6","text":"●卷四","sortOrder":1},
  {"id":"s_work_bmtn_6_2","chapterId":"ch_work_bmtn_6","text":"唐襄州趙康凝令公世勋嗣袭，人质甚伟，酷好修容，前後垂鏡以整冠櫛，往往以家讳刑人。相國崔公胤出镇湖南，由峴首。趙令逢迎开宴，崔相從容而規之曰：\"聞令公以文字刑人，甚無謂也。聞名心矍，但有顰蹙，豈可笞责及人耶\"俄而近侍以紅拂子於乌巾上拂之，相國又曰：\"此尤不可也。\"陪僚俯首而已。天水其後漢南失守，已而奔吳，路由夏口，杜洪念公郊迓，以主座遜之，遽尸其位。其不識去就，皆此類也，竟罹禍於淮甸宜乎。","sortOrder":2},
  {"id":"s_work_bmtn_6_3","chapterId":"ch_work_bmtn_6","text":"唐薛尚書能以文章自負，累出戎镇，常鬱鬱叹息。因有詩謝淮南寄天柱茶，其落句雲：粗官乞與真抛却，賴有詩名合得嘗。\"意以節將為粗官也。镇許昌日，幕吏鹹集，令其子具櫜鞬參諸幕客，幕客怪驚，八座曰：\"俾渠消灾。\"時人以為輕薄也。蓋不得本分官，矯此以見志，非輕薄乎？","sortOrder":3},
  {"id":"s_work_bmtn_6_4","chapterId":"ch_work_bmtn_6","text":"唐相國孫公偓宽裕通簡，不事矯異，常語於親友曰：\"凡人許己，務在得中。但士行無虧，不必太苦。以我之長彰彼之短，以我之清彰彼之濁，幸勿為之。\"後謫居衡山，情抱坦然，不以放逐而懷戚戚。每對客座，而厮仆辈紛詬殴曳，仆於面前。相國凝然似無所睹，謂客曰：\"若以怒心逢彼，即方寸自撓矣。\"其性度皆此類也。相國曾乘轺至蜀，詣杜光庭先生受籙，乃曰：\"嘗遇至人，話及時事，每有高栖之約。\"爾後雖登台辅，竟出官於南嶽，有詩《寄杜先生》，其要句雲：\"蜀國信難遇，楚乡心更愁。我行同范蠡，師舉效浮丘。他日相逢處，多應在十洲。\"唐末朝達罹穀水白馬驿之禍，唯相國獲免焉。","sortOrder":4},
  {"id":"s_work_bmtn_6_5","chapterId":"ch_work_bmtn_6","text":"唐柳大夫玭直清重德，中外憚之。謫授瀘州郡守，先詣東川庭參，具櫜鞬，元戎顧相彦朗堅却之。亚台曰：\"朝廷本用見责，此乃軍府舊儀。\"顧公不得已而受之。赴任，路由渝州，有牟黁秀才者，即都校牟居厚之子。文采不高，執所業謁見，亚台奖飾甚勤。甥侄從行以為牟子卷軸不消見遇，亚台曰：\"巴蜀多故，土豪倔起。斯乃押衙之子，獨能慕善，苟不誘進，渠即退志。以吾稱之，人必榮之。由此滅三五員草賊，不亦善乎。\"子弟竊笑而服之。","sortOrder":5},
  {"id":"s_work_bmtn_6_6","chapterId":"ch_work_bmtn_6","text":"唐末朝廷围太原不克，以宰相張浚為都統，華帥韓建為副使。泽潞孫揆尚書以本道兵會伐，軍容使楊复恭與張相不葉，逗撓其師，因而自潰，由是貶張相為繡州牧。孫尚書為太原所執，詬骂元戎李公克用以狗猪代之。李公大怒，俾以鋸解，雖加苦楚而鋸齒不行。八座乃謂曰：\"死狗猪！解人須用板夹，然後可得行，汝何以知之。\"由此施板而鋸。方行未絕間，骂聲不歇。何乃壮而不怖！斯則君子之儒必有勇也。近者劉知俊自梁奔秦，自秦奔蜀，驍暴之聲，天下鹹聞焉。蜀先生坐其惨酷而誅之，受戳日，章皇萬端，乞命不暇。行刑者嗟而笑之。比孫帥何勇怯之不侔也。","sortOrder":6},
  {"id":"s_work_bmtn_6_7","chapterId":"ch_work_bmtn_6","text":"唐崔相國慎猷廉察浙西日，有瓦棺寺持《法華經》僧為門徒。或有術士言相國面上氣色有貴子。問其妊娠之所在，夫人洎妾滕間皆無所見。相國徐思之，乃召曾侍更衣官妓而示術士，曰：\"果在此也。\"及載誕日，腋下有文，相次分明，即瓦棺僧名也，因命其小字緇郎。年七歲尚不食肉，一日有僧請見，乃掌其頰謂曰：\"既愛官爵，何不食肉\"自此方味葷血，即相國胤也。崔事一說雲是終南山僧，兩存之。","sortOrder":7},
  {"id":"s_work_bmtn_6_8","chapterId":"ch_work_bmtn_6","text":"唐朱崖李太尉與同列款曲，或有征其所好者，掌武曰：\"喜見未聞言、新書策。\"崔魏公铉好食新?頭，以為珍美。從事开筵，先一夕前必到使院索新煮?頭也。杜豳公每早食饙飯乾脯。崔侍中安潛好看斗牛。雖各有所美而非近利，與夫牙筹金埒、錢癖穀堆不亦遠乎。","sortOrder":8},
  {"id":"s_work_bmtn_6_9","chapterId":"ch_work_bmtn_6","text":"唐畢相誠家本寒微，其渭陽為太湖縣伍伯。相國恥之，俾罢此役，為除一官。累遣致意，竟不承命。特除選人楊載宰此邑，參辭特於私第延坐與語，期為落此猥籍，津送入京。楊令到任，具達台旨。伍伯曰：\"某下賤人也，豈有外甥為宰相耶\"楊令堅勉之，乃曰：\"某每歲公稅享六十缗事例錢，苟無败闕，終身優渥。不審相公欲為致何官職\"楊令具以聞，相國叹賞，亦然其說，竟不奪其志也。近者蜀相庾公傳，素與其從弟凝績曾宰蜀州唐興縣，郎吏有楊會者，庾氏之崑弟深念之。洎迭秉蜀政，為楊會除長馬以酬之。楊會曰：\"某之吏役，遠近皆知。忝冒為官，寧掩人口豈可將數千家供待而博一虛名長馬乎？\"雖強假軍職除授檢校官，竟不舍縣役，亦畢舅之次也。","sortOrder":9},
  {"id":"s_work_bmtn_6_10","chapterId":"ch_work_bmtn_6","text":"唐楊蔚使君典洋州，道者陳休复每到州，多止於紫極宮。弘農甚思一見，而潁川辄便他適，乃謂道士曰：\"此度更來，便須申報。\"或一日再至，遽令申白，俄而州將擁旆而至。方遂披揖，弘農曰：\"向風久矣，幸獲祗奉，敢以將來祿算為請，勿迓造次。\"潁川呼人為卿，乃謂州牧曰：\"卿三為刺史，了更無言。\"州牧不怿，以其曾典兩郡，至此三也，自是常以見任為終焉之所。爾後秩滿無恙，不喻其言。無何，又授此州，亦終考限，罢後又除是郡。凡三任，竟殒於是邦。《三為刺史》之說果在於此乎。楊公季弟玭為愚話之。","sortOrder":10},
  {"id":"s_work_bmtn_6_11","chapterId":"ch_work_bmtn_6","text":"唐軍容使田令孜擅權，有回天之力，嘗致書於許昌為其兄陳敬瑄求兵馬使職，節將崔侍中安潛不允。爾後崔公移镇。川，敬瑄與楊師立、牛勖、羅元杲以打球爭三川，敬瑄獲頭筹，製授右蜀節旄以代崔公，中外驚駭。報状雲陳仆射之命，莫知誰何。青城縣弥勒會妖人窥此聲势，乃伪作陳仆射行李，雲山東盜起，車駕必謀幸蜀。先以陳公走馬赴任。乃树一魁妖，共翼佐之。軍府未喻，亦差迎候。至近驿，有指揮索白馬四匹，察事者覺其非常，乃羁縻之。未供承間而真陳仆射亦連辔而至，其妖人等悉擒縛而俟命，潁川俾隱而誅之。識者曰：\"陳仆射由閹官之力，無涓尘之效。盜處方镇，始為妖物所凭，終以自貽誅滅，非不幸也。\"","sortOrder":11},
  {"id":"s_work_bmtn_6_12","chapterId":"ch_work_bmtn_6","text":"唐李相磎高才奧學，冠絕群彦，為朋党所排，洎登嚴廊，似涉由径。雖然，亦才授也。製下之日，劉舍人崇魯抱麻而哭之，李相斥其祖祢，條上其事，具表論之。又以彭城先德受賄飲鸩，乃作《鸚鵡杯賦》，丑詞訐切，人為寒心。朝士有識者閱其表曰：\"何必多言，但雲倒策侧龟於君前有誅，彭城子何所逃刑。\"時以為然。","sortOrder":12},
  {"id":"s_work_bmtn_6_13","chapterId":"ch_work_bmtn_6","text":"唐蔡京尚書為天德軍使，衙前小將顧彦朗、彦暉知使宅市買，八座有知人之鑒。或一日，俾其子叔向已下備酒饌於山亭，召二顧賜宴。八座俄亦即席，約令勿起。二顧惶惑，莫喻其意。八座勉之曰：\"公弟兄俱有封侯之相，善自保愛，他年願以子孫相依。\"因遷其職級。洎黃寇犯闕，顧彦朗領本軍同立收复功，作東川，加使相。蔡叔向兄弟往依之，請叔向為節度副使，仍以丈人行拜之，軍府大事皆谘謀焉。大顧薨，其弟彦暉嗣之，亦至使相。","sortOrder":13},
  {"id":"s_work_bmtn_6_14","chapterId":"ch_work_bmtn_6","text":"唐陆相扆舉進士，屬僖宗再幸梁洋，隨駕至行在。於時奔避勞止，又時當六月，而相國策名。爾後在翰林，暑月苦於蒸溽，同列戲之曰：\"今日好造榜天。\"以其進取非時也。然相國文才重德，名冠一時，朝中陆氏三人，號曰\"三陆\"，即相國洎希聲及威三人也。","sortOrder":14},
  {"id":"s_work_bmtn_6_15","chapterId":"ch_work_bmtn_6","text":"盧相光啟先人伏刑，爾後弟兄修飾赴舉，因謂親知曰：\"此乃开荒也。\"然其立性周謹，進取多涂。著《初舉子》一卷，即進取諸事，皆此類也。策名後扬歷台省，受知於租庸張浚。清河出征併汾，盧每致書疏，凡一事別為一幅，朝士至今效之。蓋八行重叠別紙自公始也。唐末舉人不問士行文藝，但勤於請謁，號曰精切，亦楷法於范陽公爾。其族弟汝弼嘗為張相出征判官，傳檄四方，其略雲：\"致赤子之流離，自朱邪之版荡。\"自謂人曰：\"天生朱邪、赤子供我之筆也。\"俊邁亦有族崑之風。","sortOrder":15},
  {"id":"s_work_bmtn_6_16","chapterId":"ch_work_bmtn_6","text":"唐吳融侍郎策名後曾依相國太尉韦公昭度，以文筆求知。每起草先呈，皆不稱旨。吳乃祈掌武親密俾達其誠，且曰：\"某幸得齒在賓次，唯以文字受眷。雖愧荒拙，敢不著力。未聞愜當，反甚忧懼。\"掌武笑曰：\"吳校書誠是藝士，每有見請，自是吳家文字，非幹老夫。\"由是改之，果愜上公之意也。散版出官，寓於江陵，為僧貫休撰詩序，以\"唐來唯元白休師而已，\"又《祭陆龟蒙文》即雲\"海內文章止魯望而已。\"自相矛盾，於時不免識者所譏。","sortOrder":16},
  {"id":"s_work_bmtn_6_17","chapterId":"ch_work_bmtn_6","text":"唐荆州衣冠藪泽，每歲解送舉人多不成名，號曰天荒解。劉蜕舍人以荆解及第，號為\"破天荒\"。爾來餘知古、關圖、常修皆荆州之居人也，率有高文，連登上科。關即衙前將校之子也，及第歸乡，都押已下為其張筵，乃指盤上醬甌戲老校曰：\"要校卒為者。\"其人以醋樽進之曰：\"此亦校卒為者也。\"席人大噱。關圖妻即常修妹，才思婦也，有祭夫文行於世。","sortOrder":17},
  {"id":"s_work_bmtn_6_18","chapterId":"ch_work_bmtn_6","text":"唐荆州成令公汭領蔡州軍戍江陵，為節度使，張璝謀害之，遂弃本都，奔於秭歸。一夜為巨蛇繞身，幾至於殒，乃曰：\"苟有所負，死生唯命。\"逡巡蛇亦亡去。爾後招辑戶口，訓練士卒，沿流而镇渚宮。尋授節旄，撫綏凋殘，励精為理。初年居民唯一十七家，末年至萬戶。勤王奉國，通商務農，有足稱焉。朝廷號北韓南郭。有孔目官贺隱者，亦返俗僧也，端貞俭約，始為腹心，凡有闕政，賴其規贊。自贺隱物故，率由胸襟，加以騁辯陵人，又多矜伐，為識者所鄙。婦翁竺知章乃餅匠也，言多不遜。又元子微過，皆手刃之，竟無系嗣。樓船之役，幕僚結舌，終致鄂渚之败，惜哉！","sortOrder":18},
  {"id":"s_work_bmtn_6_19","chapterId":"ch_work_bmtn_6","text":"唐黃巢犯闕，僖宗幸蜀。張相國浚白身未有名第，時在河中永樂莊居，里有一道人，或麻衣，或羽帔，不可親狎。一日，張在村路前行，後有唤\"張三十四郎，駕前待爾破賊\"，回顧乃是此道人。相國曰：\"某一布衣耳，何階緣而能破賊乎？\"道人勉其入蜀，適遇相國聖善疾苦，未果南行。道者乃遺兩粒丹，曰：\"服此可十年無恙。\"相國得藥奉親，所疾痊复，後歷登台辅。道者亦不复見。破賊之說何其验哉。","sortOrder":19},
  {"id":"s_work_bmtn_6_20","chapterId":"ch_work_bmtn_6","text":"唐薛澄州昭緯，即保遜之子也。恃才傲物，亦有父風。每入朝省，弄笏而行，旁若無人。好唱《浣溪紗》詞，知舉後有一門生辭歸乡里，臨岐獻規曰：\"侍郎重德，某乃受恩。爾後請不弄笏與唱《浣溪紗》，即某幸也。\"時人謂之至言。有小吏常學其行步揖遜，公知之，乃召謂曰：\"试於庭前學得似則恕爾罪。\"於是下帘擁姬妾而觀，小吏安詳傲然，舉動酷似。笑而舍之。","sortOrder":20},
  {"id":"s_work_bmtn_6_21","chapterId":"ch_work_bmtn_6","text":"路侍中巖在西蜀，嘗夏日納涼於球場廳中，使院小吏羅九皋巾裹步履，有似裴條郎中。大貂遙見，促召衫帶，逼视方知其非，因笞之。","sortOrder":21},
  {"id":"s_work_bmtn_6_22","chapterId":"ch_work_bmtn_6","text":"唐張策早為僧，败道歸俗，後為梁相。先在華山雲台觀修業，觀侧有莊，其弟簴亦輕易道教，因脱亵服掛於天尊臂上雲：\"借此公為我掌之。\"須臾，精神恍惚，似遭殴击，痛叫狼狽，或頓或起，如有人拖曳之状，歸至別業而卒。斯人也，必党於釋氏而輕侮道尊，人之無禮，自貽陰殛，非不幸也，與嘉州崔使君开尹真君石函事同。李載仁郎中目睹，為愚話之。","sortOrder":22},
  {"id":"s_work_bmtn_6_23","chapterId":"ch_work_bmtn_6","text":"唐柳仆射仲郢镇郪城，有一婢失意，將婢於成都鬻之。蓋巨源使君乃西川大校，累典雄郡，宅在苦竹溪。女儈具以柳婢言导，蓋公欲之，乃取歸其家。女工之具悉，隨之日夕，賞其巧技。或一日，蓋公臨街窥窗，柳婢在侍，通衢有鬻綾羅者從窗下過，召俾就宅。蓋公於束缣內選擇邊幅，舒卷揲之，第其厚薄，酬酢可否。柳婢失聲而仆，似中風恙。命扶之而去，一無言語，但令舆還女儈家。翌日而瘳。詰其所苦，青衣曰：\"某雖賤人，曾為柳家細婢，死則死矣，安能事賣絹牙郎乎。\"蜀都聞之皆嗟叹也。清族之家率由禮門，蓋公暴貴，未知士風，為婢仆所譏，宜矣哉。","sortOrder":23},
  {"id":"s_work_bmtn_6_24","chapterId":"ch_work_bmtn_6","text":"唐柳玭大夫之任瀘州，溯舟經馬驍镇。土豪趙師儒率乡兵數千，凭高立寨，刑訟生殺，得以自专，本道署以軍職。聞五馬經過，乃棹扁舟，被褐衫把杖子迎接，參状雲\"百姓趙師儒\"。亚台以其有職，非隸屬邑，怪而辭之。師儒曰：\"巴蜀亂離，某懷集乡人拒他盜，非敢僭幸，妄徼戎職。\"亚台欣而接之，乃駐旌旆馆於寨中，供亿丰備，钦禮弥勤。師儒亦有詩句，皆陳素心。亚台悉為和之。睹其清俭，不覺嗟叹曰：\"我他年若登廊廟，必為斯人而致節察。\"蓋賞其知分任真也。","sortOrder":24},
  {"id":"s_work_bmtn_6_25","chapterId":"ch_work_bmtn_6","text":"禪門有《祖系圖》，得佛心印者皆次列之。進士有《登科記》，懷將相才者鹹編缀之。而名實相违，玉石混雜，疑誤後人，良可怪也。唐進士宇文翃，雖士族子，無文藻，酷愛上科。有女及笄，真國色也，朝之令子弟求之不得。時窦璠年逾耳順，方謀繼室，其兄諫議叵有氣焰，能為人致登第。翃嫁女與璠，璠為言之元崑，果有所獲。相國韦公說即其中表，甚鄙之。因滑台杜尚書宅遭火，幾爇神柩，家人雲老鼠尾曳火入库內，因而延燎。京兆謂宇文曰：\"魚將化龍，雷為燒尾。近日老鼠亦有燒尾之事。\"用以譏之。葆光子嘗试一僧，備谙谬妄，一旦擁徒說法，自言出世，安知他日不預《祖系》乎。是則宇文翃登科，後人何以知之，悲夫！","sortOrder":25},
  {"id":"s_work_bmtn_6_26","chapterId":"ch_work_bmtn_6","text":"溫庭雲，字飛卿，或雲作\"筠\"字，舊名岐，與李商隱齊名，時號曰\"溫李\"。才思艳麗，工於小賦，每入试押官韻作賦，凡八叉手而八韻成，多為鄰鋪假手，號曰救數人也。而士行有缺，縉紳簿之。李義山謂曰：\"近得一聯句雲'遠比召公三十六年宰辅'，未得偶句。\"溫曰：\"何不雲'近同郭令二十四考中書'。\"宣宗嘗賦詩，上句有\"金步搖\"，未能對，遣未第進士對之。庭雲乃以\"玉條脱\"續也，宣宗賞焉。又藥名有白頭翁，溫以蒼耳子為對，他皆此類也。宣宗愛唱《菩薩蠻》詞，令狐相國假其新撰密進之，戒令勿他泄。而遽言於人，由是疏之。溫亦有言雲：\"中書堂內坐將軍。\"譏相國無學也。宣皇好微行，遇於逆旅，溫不識龍顏，傲然而詰之曰：\"公非司馬長史之流\"帝曰：\"非也。\"又謂曰：\"得非大參簿尉之類\"帝曰：\"非也。\"謫為方城縣尉，其製詞曰：\"孔門以德行為先，文章為末。爾既德行無取，文章何以補焉。徒負不羁之才，罕有適時之用\"雲雲。竟流落而死也。杜豳公自西川除淮海，溫庭雲詣韦曲杜氏林亭，留詩雲：\"卓氏爐前金線柳，隋家堤畔錦帆風。貪為兩地行霖雨，不見池莲照水紅。\"豳公聞之，遺絹一千匹。吳興沈徽雲：\"溫舅曾於江淮為親表檟楚，由是改名焉。\"庭雲又每歲舉場多借舉人為其假手。沈詢侍郎知舉，別施鋪席授庭雲，不與諸公鄰比。翌日帘前謂庭雲曰：\"向來策名者皆是文賦托於學士，某今歲場中併無假托學士，勉旃！\"因遣之，由是不得意也。","sortOrder":26},
  {"id":"s_work_bmtn_6_27","chapterId":"ch_work_bmtn_6","text":"浙西周寶侍中博陵崔夫人乃乾符中時相之姊妹也，少為女道士，或雲寡而冠帔，自幽獨焉。大貂素以豪俠聞，知崔有容色，乃逾垣而竊之，宗族亦莫知其存没。爾後周除浙右，其內亦至國號，乃具車馬偕歸崔門曰：\"昔者官職卑下，未敢先言。此际叨尘，亦不相辱。\"相國不得已而容之。末山尼开堂說法，禪師邓隱峰，有道者也，试其所守，中夜挟刃入禪堂欲行強暴，尼憚死失志。隱峰取去衵服，集眾僧以晓之，其徒立散。王蜀先主部將張勍暴橫，鞭人之胸。典眉州，有一少尼姿容明悟，講《無量寿經》。張欲逼辱，以死拒之，不肯破戒，因而詬骂。張乃折其齒，與其父同沈於蟆颐津也。崔氏女、末山尼以畏懦而苟全，徐仙姑用道力而止暴，講經尼以守戒而陨命，是知女子修道亦似一段障難，而况冶容誨淫者哉。孫棨舍人著《北里志》，叙朝賢子弟平康狎遊之事，其旨似言盧相携之室女失身於外甥鄭氏子，遂以妻之，殺家人而滅口。是知平康之遊亦何傷於年少之流哉！","sortOrder":27},
  {"id":"s_work_bmtn_6_28","chapterId":"ch_work_bmtn_6","text":"唐世梁太祖未建國前，崔禹昌擢進士第，有別業在汴州管內。禹昌敏俊，善接對。初到夷門，希梁祖意，請陳桑梓禮。梁祖甚喜，以其不相輕薄，甚蒙管領，常預賓次，或陪亵戲。梁祖以其有莊墅，必藉牛，乃問曰：\"莊中有牛否\"禹昌曰：\"不識得有牛。\"意是無牛，以時俗語\"不識得有\"對之。梁祖大怒，曰：\"豈有人不識牛為我是村夫即識牛，渠則不識。如此輕薄，何由可奈！\"幾至不测，後有人言，方漸釋怒。","sortOrder":28},
  {"id":"s_work_bmtn_6_29","chapterId":"ch_work_bmtn_6","text":"唐右補闕張曙，吏部侍郎褧之子，禕之侄。文章秀麗，精神敏俊，甚有時稱。所生母常戴玉天尊，黃巢亂離，莫知存没。或有於枯骸中頭上見有玉天尊，以曙未訪遺骸，不合進取，以此阻之。後於裴贽侍郎下擢進士第，官至右補闕。曾戲同年杜荀鶴曰：\"杜十四仁賢大榮，幸得與張五十郎同年。\"荀鶴答曰：\"張五十郎大榮，幸得與荀鶴同年。\"天下只聞杜荀鶴名字，豈知張五十郎耶。彼此大咍，是知虛名不足定人優劣。曙有《击甌賦》，其警句雲：\"董双成青琐鸞驚，啄开珠網；穆天子紅韁馬解，踏破琼田。\"又有《鄠郊賦》叙長安亂離，亦《哀江南》、《悲甘陵》之比，區區之荀鶴不足擬倫。","sortOrder":29},
  {"id":"s_work_bmtn_7_1","chapterId":"ch_work_bmtn_7","text":"●卷五","sortOrder":1},
  {"id":"s_work_bmtn_7_2","chapterId":"ch_work_bmtn_7","text":"唐大和中，閹官恣橫，因甘露事，王涯等皆罹其禍，竟未昭雪。宣宗即位，深抑其權，末年嘗授旨於宰相令狐公。公欲盡誅之，慮其冤，乃密奏榜子曰：\"但有罪莫舍，有闕莫填，自然無遺類矣。\"後為宦者所見，於是南北司益相水火。洎昭宗末，崔侍中得行其志，然而玉石俱焚也已。乾符後，宮娥皆以木团頭。自是四方效之，唯內官各自出樣。匠人曰\"斫軍容頭\"、\"特進頭\"，至是果验也。","sortOrder":2},
  {"id":"s_work_bmtn_7_3","chapterId":"ch_work_bmtn_7","text":"唐進士曹唐《遊仙詩》，才情縹緲，嶽陽李遠員外每吟其詩而思其人。一日曹往謁之，李倒屣而迎。曹生儀质充伟。李戲之曰：\"昔者未睹標儀，將謂可乘鸞鶴。此际拜見，安知壮水牛亦恐不勝其載。\"時人聞而笑之。","sortOrder":3},
  {"id":"s_work_bmtn_7_4","chapterId":"ch_work_bmtn_7","text":"李肇《國史補》雲：\"正元末，有郎官四人自行軍司馬賜紫而登粉署，省中謔之為四君子也。\"唐自大中至鹹通，白中令入拜相，次畢相誠、曹相確、羅相劭權使相也，繼升嚴廊。崔相慎猷曰：\"可以歸矣。近日中書盡是蕃人。\"蓋以畢、白、曹、羅為蕃姓也。始蒋伸相登庸，李景遜尚書西川覽報状而叹曰：\"不能伏事斯人也。\"遽托疾離镇，有詩曰：\"成都十萬戶，抛若一鸿毛。\"亦博陵之比也。近代吳融侍郎乃趙崇大夫門生，即世日，天水叹曰：\"本以畢、白待之，何乃乖於所望。\"歉其不大拜，而亦譏當時也。","sortOrder":4},
  {"id":"s_work_bmtn_7_5","chapterId":"ch_work_bmtn_7","text":"唐乾寧中，荆南成令公汭曾為僧，盜據渚宮，尋即貢命，末年騁辨，每事標特。初以澧朗舊在巡屬，為土豪雷滿所據，奏請割隸。相國徐公彦若在中書，不為處置。由是衔之。相國出镇番禺，路由渚宮，成令雖加接延，而常怏怏。饌後更席而坐，诡辯鋒起。相國曰：\"令公位尊方面，自比桓文。雷滿者，偏州一伙草賊耳，令公不能加兵而怨朝廷乎？\"成公赧焉而屈。東海文雅高談，聽之亹亹。成令雖甚敬憚，猶以嶺外黃茅瘴，患者發落，而戲曰：\"黃茅瘴，望相公保重。\"相國曰：\"南海黃茅瘴，不死成和尚。\"蓋譏成令曾為僧也，終席慚恥之。","sortOrder":5},
  {"id":"s_work_bmtn_7_6","chapterId":"ch_work_bmtn_7","text":"唐大中初，盧携舉進士，風貌不扬，語亦不正，呼携為彗，蓋短舌也。韦氏崑弟皆輕侮之，獨韦岫尚書加钦謂其崑弟曰：\"盧雖人物甚陋，觀其文章有首尾。斯人也，以是卜之，他日必為大用乎。\"爾後盧果策名，竟登廊廟，奖拔京兆至福建觀察使。向時輕薄諸弟率不展分。所謂以貌失人者，其韦諸季乎。","sortOrder":6},
  {"id":"s_work_bmtn_7_7","chapterId":"ch_work_bmtn_7","text":"唐大中初，綿州魏城縣人王助舉進士，有奇文，蜀自李白、陳子昂後，繼之者乃此侯也。嘗撰《魏城縣道觀碑》，詞華典贍。於時辭逢牧綿州，見而賞之，以其邑子延遇，因改名助，字次安，壮其文類王勃也。自幼婦刊建，薛使君列衔於碑陰，以光其文，雖兵亂焚荡，而螭首巋然。好事者經過，皆稅駕而覽之。助後以瞽废，無聞於世，賴河東公振發增价，而子孫榮之。其子朴仕蜀至翰林學士。","sortOrder":7},
  {"id":"s_work_bmtn_7_8","chapterId":"ch_work_bmtn_7","text":"大中年，洪州處士陳陶者，有逸才，歌詩中似負神仙之術，或露王霸之說。雖文章之士亦未足凭，而以詩見志，乃宣父之遺訓也。其詩句雲：\"江湖水深淺，不足掉鯨尾。\"又雲：\"飲冰狼子瘦，思日鹧鸪寒。\"又雲：\"中原不是無麟鳳，自是皇家結網疏。\"又雲：\"一鼎雄雌金液火，十年寒暑鹿霓衣。寄與東流任斑鬢，向隅終守鐵梭飛。\"諸如此例，不可殫記。著《癖書》十卷，聞其名而未嘗見之。","sortOrder":8},
  {"id":"s_work_bmtn_7_9","chapterId":"ch_work_bmtn_7","text":"王贊侍郎，中朝名士。有弘農楊蘧者，曾到嶺外見陽朔荔浦山水，談不容口。以階緣嘗得接琅琊，從容不覺形於言曰：\"侍郎曾見陽朔荔浦山水乎？\"琅琊曰：\"某未曾打人唇綻齒落，安得而見。\"因之大笑。楊宰俄而選求彼邑，挈家南去，亦州縣官中一高士也。","sortOrder":9},
  {"id":"s_work_bmtn_7_10","chapterId":"ch_work_bmtn_7","text":"唐僖宗皇帝蒙尘於蜀，朝士未集，闕人掌誥。樂朋龟、侯翮辈雖居翰林，而排難解紛之才非所長也。高太尉镇淮海，擁兵不進，與浙西周寶不睦，表章遞奏，各述短長。朝廷欲降詔和之，學士草詞，殊不愜旨。前進士李端有壮筆，軍容田令孜知之，召而與語，授以毫翰。李仍請酒，飲數杯，詔書一筆而成，文藻之外乃奇辯也，深稱上旨，除行在知製誥，官至省郎。舊說李紳相镇淮海，奏荐副使章服，累表不允。有一舉人候謁，紳相知其文詞，請撰一表，其略雲：\"當道地管八州，軍雄千乘。副使著绿，不稱其宜。\"相國大喜，果以此章而獲恩命也。李太尉破昭義，自草詔意而宣付翰林，至如鄭文公自草高太尉詔，皆務集事，非侵局奪美也。","sortOrder":10},
  {"id":"s_work_bmtn_7_11","chapterId":"ch_work_bmtn_7","text":"錢尚父始殺董昌，奄有兩浙，得行其志，士人恥之。吳侍郎，趙州萧山縣人，舉進士，場中甚有聲采，屢遭維縶，不遂觀光，乃脱身西上。將及蘇台界，回顧有紫綬者二人追之，吳謂必遭籠罩。須臾，紫綬者殊不相顧，促遽前去，至一津渡，唤船命吳共濟，比達岸，杳然失之。由是獲免，爾後策名升朝。是知分定者必有神明助之。","sortOrder":11},
  {"id":"s_work_bmtn_7_12","chapterId":"ch_work_bmtn_7","text":"沈詢侍郎精粹端美，神仙中人也。製除山北節旄，京城誦曹唐《遊仙詩》雲：玉詔新除沈侍郎，便分茅土領東方。不知今夜遊何處，侍從皆騎白鳳凰。\"即風姿可知也。將凝侍郎亦有人物，每到朝士家，人以為祥瑞，號\"水月觀音\"，前代潘安仁、衛叔寶何以加此。唐末朝士中有人物者，時號\"玉筍班\"。","sortOrder":12},
  {"id":"s_work_bmtn_7_13","chapterId":"ch_work_bmtn_7","text":"舊例，士子不與內官交遊，十軍軍容田令孜擅回天之力，僖皇播遷，行至洋源，百官未集，闕人掌誥。樂朋龟侍郎亦及行在，因謁中尉，仍請中外，由是荐之，充翰林學士。張濬相自處士除起居郎，亦出子方之門，皆申中外之敬。洎車駕到蜀，朝士畢集。一日，中尉為宰相开筵，學士洎張起居同預焉。張公恥於對眾設拜，乃先謁中尉，便施謝酒之敬。中尉訝之。俄而賓主即席坐定，中尉白諸相曰：\"某與起居，清濁異流。曾蒙中外，既慮玷辱，何憚改更。今日猥地謝酒，即又不可。\"張公慚懼交集。自此甚為群彦薄之。樂公舉進士，初陳啟事謁李昭侍郎自媒雲：\"別於九經、書、史及老、莊洎八都賦外，著八百卷書，請垂比试。\"誠有學問也。然於製誥不甚簡當，時人或未可之。","sortOrder":13},
  {"id":"s_work_bmtn_7_14","chapterId":"ch_work_bmtn_7","text":"唐薛廷珪少師，右族名流，仕於衰世。梁太祖兵力日強，朝廷傾動，漸自尊大，天下懼之。孤卿為四镇官告使，夷門客將劉翰先來類會，恐申中外，孤卿佯言不會，謂謁者曰：\"某無德，安敢辄受令公拜。\"竟不為屈。洎受禪之後，勉事於梁，而太祖優容之，寿考而終也。中間奉命册蜀先主為司徒，馆中舊疾發動，蜀人送當医人楊仆射，俾攻療之。孤卿致書感謝，其書末請借肩舆，歸京尋医。蜀主訝之，乃曰：\"幸有方藥，何不俟愈而行\"堅請且駐行軒，公謂客將曰：\"夜來問此医官，殊不識字，安可以性命委之乎？\"竟不服藥而北歸。後唐相國韦公說仕梁為中書舍人，倅轺於錢塘。先是，錢尚父自據一方，每要姑息。梁主以河北、關西悉為勍敵，又頻失利於淮海，甚藉兩浙牵掎之，其次又資貢賦。凡命使臣遠泛沧溟，一則希其丰遺，二則懼不周旋，悉皆拜之。錢公亦自尊大，唯京兆公長揖而已。既不辱命，識者異之，竟有巖廊之拜也。","sortOrder":14},
  {"id":"s_work_bmtn_7_15","chapterId":"ch_work_bmtn_7","text":"唐楊晟始事鳳翔節度李昌符，累立軍功，因而疑之，潛欲加害。昌符愛妾周氏愍其無辜，密告之，由是亡去而獲免也。後為駕前五十四軍都指揮使，除威勝軍節度使，建節於彭州，撫綏士民，延敬賓客，洎僧道辈各得其所。厚於禮敬，人甚懷之。李昌符之败，因令求訪。周氏既至，以義母事之。周氏自以少年复有美色，恐有好合之請。弘農告誓天地，終不以非禮偶之。每旦未视事前必伸問安之禮，雖厄在重围，未嘗废也。新理之所，兵力未完，遽為王蜀先主攻围，保守孤城，救兵不至，凡十日而為西川所破而害焉。有馬步使安師建者，楊氏之腹心也，城克執之。蜀先主知其忠烈，冀為其用，欲宽之。師建曰：\"某受楊司徒提拔，不敢惜死。\"先主叹賞而行戮，為設祭而葬之。","sortOrder":15},
  {"id":"s_work_bmtn_7_16","chapterId":"ch_work_bmtn_7","text":"唐天祐中，淮師围武昌不解，杜洪令公乞師於梁王。梁王與荆方睦，乃諷成中令帥兵救之。於是禀奉霸主，欲親征。乃以巡屬五州事，力造巨艦一艘，三年而成，號曰和州載艦。上列萬事洎司局，有若衙府之製，又有齊山截海之名，其於華壮即可知也。飾非拒諫，斷自己意，幕僚俯仰，不措一詞，唯孔目官楊厚贊成之。舟次破軍山下，為吳師縱燎而焚之，中令溺死，兵士潰散。先是，改名曰汭，汭字即水內也。水內之死，豈非前兆乎湖南及朗州軍入江陵，俘載軍人百姓職掌伎巧僧道伶官併歸長沙。改汭之名，和州之說，蓋前定也。","sortOrder":16},
  {"id":"s_work_bmtn_7_17","chapterId":"ch_work_bmtn_7","text":"唐陳敬瑄據成都府拒命，韦太尉昭度充招讨使，率東川兵以伐之。王蜀先主時為草賊，剽掠諸縣，乃擁手下兵投掌武，署為衙內指揮使，資其爪牙也，因奏請割西川數州就臨邛建節以授之。蜀主卑謙多智，事韦公甚謹。掌武量其事势終不能駕御，况軍旅之事又非所長，每欲攻城，請戎服臨陣，慮矢石所及，不敢近前。掌武曰：\"軍人安敢無禮\"東川都顯有唐吃人者，呼而戒之曰：\"人肉何如猪羊\"乃賜一缗俾充肉价，他皆仿此。重围二年，蜀城已困，不日將下。一旦門外喧哗，以軍糧闕乏，兵士擒曳掌武親吏骆別駕名志者脔而啖之。由是懼罹其禍，遽托疾以西川牌印付蜀主而歸朝。雖曰不武，斯亦用智自免也。","sortOrder":17},
  {"id":"s_work_bmtn_7_18","chapterId":"ch_work_bmtn_7","text":"屯難之世，君子遭遇不幸往往有之。唐進士章魯封與羅隱齊名，皆浙中人，頻舉不第，聲采甚著。錢尚父土豪倔起，號錢塘八都，洎破董昌，奄有杭越。於是章、羅二士罹其籠罩。然其出於草萊，未谙事體，重縣宰而輕郎官，嘗曰：\"某人非才，只可作郎官，不堪作縣令。\"即可知也。以章魯封為表奏孔目官，章拒而見笞。差羅隱宰錢塘，皆畏死禀命也。章、羅以之為恥，錢公用之為榮。玉石俱焚，吁，可惜也！或雲章魯封後典蘇州，著《章子》三卷行於世。羅隱為中朝所重，錢公尋倍加钦，官至給事中，享寿考，溫飽而卒。","sortOrder":18},
  {"id":"s_work_bmtn_7_19","chapterId":"ch_work_bmtn_7","text":"唐裴司徒璩性靳啬，廉問江西日，凡什器圖障皆新其製，閉屋緘貯，未嘗施用。每有宴會，即於朝士家借之。在番禺時，鐘愛一女，選滎陽鄭進士以婿之。才過禮期，遽屬秋荐，不免隨計，無何到京，尋報物故。五教念女及婿，不勝悲痛，而鄭偶笑之，蓋夫婦之愛未深，不解思慮，非有他故也。大凡士族女郎無改醮之禮，五教念女早寡，不能忘情，乃召門生故吏而告之，因別適人。亂倫再醮，自河東始也。元禎少監、蘇涯中丞、賜紫楊玭少尹與五教親吏別駕，說皆同。","sortOrder":19},
  {"id":"s_work_bmtn_7_20","chapterId":"ch_work_bmtn_7","text":"歸登尚書每浴皆屏左右，自於浴斛中坐移時。或有窥者見一巨龟吹水也。性甚鄙啬，嘗烂一羊脾，旋割旋啖，封其殘者。一旦內子於封處割食，八座不見元封，大怒。其內由是没身不食肉。斯亦愈於和峤之流也。","sortOrder":20},
  {"id":"s_work_bmtn_7_21","chapterId":"ch_work_bmtn_7","text":"西川自唐劉辟構逆後久無幹戈，人不習戰，每歲諸道差兵屯戍大渡河，蠻旗才舉，望風而潰。鹹通中，長驅直抵府城，居人有扃戶而拒之，蠻亦不敢扣門也。嘗有一蠻迷路入廣都縣村墅，里人相率數百辈叫噪而逐之，蠻一回顧却走，如堵牆崩焉。自晝及螟，終不能擒致。其怯懦如此。王蜀先主時，雲南寇蜀。蜀軍勇銳欲吞之，俘擒啖食，不以為敵，與向前之兵，百倍其勇也。","sortOrder":21},
  {"id":"s_work_bmtn_7_22","chapterId":"ch_work_bmtn_7","text":"鹹通中，南蠻围西川，朝廷命太尉渤海高公骈自天平軍移镇成都。戎車未屆，乃先以帛書軍號，其上仍畫一符，於郵亭遞之，以壮軍聲。蠻酋懲交趾之败，望風而遁。先是，府無羅郭，南寇才臨，遂成煨燼，士民無久安之計。渤海規畫地势，圖版筑焉。慮畚锸將施，亭堠有警，乃命門僧景山奉使入南詔宣言躬自巡邊。自下手筑城日，舉烽直至大渡河，幾九十三日，樓橹矗然，旌旆竟不行，而驃信栗不暇。兵以诈勝，斯之謂也。","sortOrder":22},
  {"id":"s_work_bmtn_7_23","chapterId":"ch_work_bmtn_7","text":"唐天复中張道古，沧州蒲台縣人，擢進士第，拜左補闕。文學甚富，介僻不群，因上《五危二亂表》左授施掾，爾後入蜀。先是，所陳《二亂疏》雲：\"只今劉備、孫權已生於世矣。\"懼為蜀主所憾，無路栖托。洎逢开創，誠思征召，為幕僚排擯，卒不齒錄，竟罹非命也。嘗自筮遇凶卦，預造一穴，題表雲\"唐左補闕張道古墓\"，後果遇害而瘞之。人有獲其《上蜀主書》遺稿，極言僚寮掩其才學，不為延譽，又非违時变盤桓取禍之流也。","sortOrder":23},
  {"id":"s_work_bmtn_7_24","chapterId":"ch_work_bmtn_7","text":"唐貞元中，秭歸人覃正夫頃栖庐嶽，帥符載征召為文，竟汨没於巴巫也。或有以其文數篇示愚，辭韻挺特，風調凛然，真得武都之刀尺也，號《巢居子》，有二十卷。愚因致書於歸州之衙校李玩，俾搜訪之。書未達前三日，里人有家藏全集者，適遇延爇而煨燼之。嗟乎！鄙於覃生異時也，苟得繕寫流爇布，振彼聲光，而焚如之酷，何不幸之甚也！","sortOrder":24},
  {"id":"s_work_bmtn_7_25","chapterId":"ch_work_bmtn_7","text":"唐羅員外袞，成都臨邛人，應進士舉，文學優贍，操尚甚高。唐大順中策名，不歸故乡，時屬丧亂，朝廷多故，契闊兵難，備歷飢寒。蜀先主致書於翰林令狐學士、吳侍郎選書記一員，欲以桂陽應聘。外郎謂知己曰：\"誓擁馬通衢，服弊布衣以俟外朝，無复西歸為魯國東家丘也。\"竟通朝籍，終於梁禮部員外郎也。蜀人有志者唯外郎乎扬子雲二息亡，遺體葬於蜀，與夫延陵季子何相遠哉！近代李頻、黃匪躬皆嶺表人，頻即遺其糟糠，別婚士族，黃即三十年不返乡里，於時妻母俱在，又何心乎！","sortOrder":25},
  {"id":"s_work_bmtn_7_26","chapterId":"ch_work_bmtn_7","text":"唐高测，彭州人，聰明博識，文翰縱橫，至於天文歷數、琴棋書畫、長笛胡琴，率皆精巧，乃梁朝朱異之流。嘗謁高燕公，上啟事自序，其要雲：\"讀書萬卷，飲酒百杯。\"燕公曰：\"萬卷書不易征詰，百杯酒得以奉试。\"乃飲以酒，果如所言。僖皇帝幸蜀，因進所著書除秘校，卒於威勝軍節度判官也。","sortOrder":26},
  {"id":"s_work_bmtn_7_27","chapterId":"ch_work_bmtn_7","text":"韓昭仕王氏至禮部尚書、文思殿大學士，粗有文章，至於琴棋書算射法悉皆涉獵，以此承恩於後主，時有朝士李台嘏曰：\"韓八座事藝如拆襪線，無一條長。\"時人韙之。","sortOrder":27},
  {"id":"s_work_bmtn_7_28","chapterId":"ch_work_bmtn_7","text":"唐武都符載，字厚之，本蜀人，有奇才。始與楊衡、宋濟栖青城山以習業，楊衡擢進士第，宋濟先死無成，唯符公以王霸自許，恥於常調懷會之望。韦南康镇蜀，辟為支使，雖曰受知，尚多偃蹇。韦公於二十四化設醮，請撰斋詞，於是陪飲於摩诃之池。符公離席盥漱，命使院小吏十二人捧砚，人分兩題，繞步池濱，各授口占，其敏速如此。劉辟時為金吾仓曹參軍，依栖韦公，特與譔《真贊》，其詞雲：\"矯矯化初，氣杰文雄。靈螭出水，秋鹗乘風。行義則固，辅仁乃通。他年良觌，麟閣之中。\"洎京兆变故，彭城知留務，起雄據之意，符為其所縻，凡有代奏，愈更恭順。劉辟之败也，幕僚多罹其禍，唯符生以箋奏稿草一箧呈高崇文相公，長揖東下，栖於庐山，即前之《真贊》可謂有先鑒也。居潯陽二林間，優遊卒歲。南昌軍奏請為副倅，授奉禮郎，不赴，命小僮持一幅上於襄陽乞百萬錢買山，四方交辟，羔雁盈於山門草堂中，以女妓二十人娱侍，聲名藉甚於時，守道循常者號曰\"凶人\"。","sortOrder":28},
  {"id":"s_work_bmtn_7_29","chapterId":"ch_work_bmtn_7","text":"唐光啟中，成都人侯翮風儀端秀，有若冰壶，以拔萃出身為邠寧從事。僖皇播遷，擢拜中書舍人、翰林學士，內试數題目，其詞立就，舊族朝士潛推服之。僖宗歸闕，除郡不赴，歸隱导江別墅，號臥龍馆。王蜀先主圖霸，屈致幕府，先俾節度判官冯涓候其可否。冯有文章大名，除眉州刺史，田令孜拒朝命，不放之任。羁寓成都，為侯公軫恤，甚德之，其辟書即冯涓極筆也。侯有謝書上王先主，其自負雲：\"可以行修箋表，坐了檄書。\"","sortOrder":29},
  {"id":"s_work_bmtn_7_30","chapterId":"ch_work_bmtn_7","text":"趙蕤者，梓川鹽亭縣人也，博學韜鈐，長於經世。夫婦俱有節操，不受交辟，撰《長短經》十卷，王霸之道見行於世。","sortOrder":30},
  {"id":"s_work_bmtn_8_1","chapterId":"ch_work_bmtn_8","text":"●卷六","sortOrder":1},
  {"id":"s_work_bmtn_8_2","chapterId":"ch_work_bmtn_8","text":"唐李紳，性刚直，在中書與李衛公相善，為朋党者切齒。镇淮海日，吳湘為江都尉。時有零落衣冠顏氏女寄寓廣陵，有容色，相國欲納之。吳湘強委禽焉，於是大怒。因其婚娶聘财反甚丰，乃羅織執勘，准其俸料之外有陳設之具，坐贓，奏而殺之，懲無禮也。宣宗初在民間備知其屈，登極後，與二李不葉者导而進状訴冤。衛公以此出官朱厓，路由澧州，謂寄寓朝士曰：\"李二十誤我也。\"馬植曾為衛公所忌，出為外任。吳湘之事鞫於憲台，扶風時為中憲，得行其志焉。吳湘乃澧州人，顏尋歸澧陽，孀獨而終。舊說浙東理難，十分公事，紳相晓得五六，唯劉漢弘晓得七分，其他廉使乃三四而已。蓋公之才已難得也。","sortOrder":2},
  {"id":"s_work_bmtn_8_3","chapterId":"ch_work_bmtn_8","text":"唐裴相公休留心釋氏，精於禪律，師圭峰密禪師，得達摩頓門。密師《註法界觀》、《禪詮》，皆相國撰序。常被毳衲於歌妓院持鉢乞食，自言曰：\"不為俗情所染，可以說法。\"為人每自發願，願世世為國王弘護佛法。後於闐國王生一子，手文有相國姓字，聞於中朝，其子弟欲迎之，彼國敕旨不允也。双峰禪師聚徒千人，談玄之盛無能及也，一旦惑於民女而败道焉，是知淫為大罰，信矣。相國李公蔚始與師善，為致一宰而已。道士文如海註《莊子》，文詞浩博，恳求一尉，與夫湯惠休、廖廣宣旨趣共卑也，惜哉！","sortOrder":3},
  {"id":"s_work_bmtn_8_4","chapterId":"ch_work_bmtn_8","text":"丞相韦公宙出镇南海，有小將劉謙者職級甚卑，氣宇殊異，乃以從猶女妻之。其內以非我族類，慮招物議，諷諸幕僚請諫止之。丞相曰：\"此人非常流也，他日吾子孫或可依之。\"謙以軍功拜封州刺史，韦夫人生子曰隱、曰巖，隱為廣帥，巖嗣之，奄有嶺表四府之地，自建號曰漢，改名龑，在位經二紀而終。次子嗣。即京兆知人之鑒非谬也。","sortOrder":4},
  {"id":"s_work_bmtn_8_5","chapterId":"ch_work_bmtn_8","text":"唐通義相國崔魏公铉之镇淮扬也，盧丞相耽罢浙西，張郎中铎罢常州，俱過維扬謁魏公。公以暇日與二客私款方弈，有持状報女巫與田布尚書偕至，泊逆旅某亭者。公以神之至也，甚異之。俄而复曰：\"顯验與他巫異，請改舍於都候之廨署。\"公乃趣召巫者至。至乃與神迭拜曰：\"謝相公。\"公曰：\"何謝\"神曰：\"布有不肖子默货無厭，郡事不治當犯大辟，賴相公陰德免焉。使布之家廟血食不絕者，公之恩也。\"公矍然曰：\"異哉！某之為相也，未嘗以機密損益於家人。忽一日夏州節度使奏銀州刺史田鐬犯贓罪，私造鎧甲以易市邊馬布帛。帝赫然怒曰：'贓罪自別議，且委以邊州，所宜防盜，以甲資敵，非反而何。'命中書以法論，將盡赤其族。翌日，從容謂上曰：'鐬贓罪自有憲章，然是弘正之孫、田布之子。弘正首以河朔請朝觐，奉吏員。布亦繼父之款。布會征淮口，繼以忠孝，伏劍而死。今若行法論罪以固邊圉，未若因事弘貸，激勸忠烈。'上意乃解，止黜授遠郡司馬。而某未嘗一出口於親戚私昵，已將忘之。今神之言正是其事。\"乃命廊下表而見焉。公謂之曰：\"君以義烈而死，奈何區區為愚婦人所使乎？\"神怃然曰：\"某嘗負此嫗八十萬錢，今方忍恥而偿之，乃宿债爾。\"公與二客及監軍使幕下共偿其未足，代付之日，神乃辭去，自後言事不验。梁相國李公琪傳其事，且曰：\"嗟乎，英特之士負一女子之债，死且如是，而况於負國之大债乎！竊君之祿而不報，盜君之柄而不忠，豈其未得聞於斯論耶而崔相國出入將相殆三十年，宜哉！\"","sortOrder":5},
  {"id":"s_work_bmtn_8_6","chapterId":"ch_work_bmtn_8","text":"李德裕太尉未出學院，盛有詞藻，而不樂應舉。吉甫相俾親表勉之，掌武曰：\"好騾馬不入行。\"由是以品子叙官也。吉甫相與武相元衡同列，事多不葉。每退，公詞色不怿。掌武啟白曰：\"此出之何難\"乃請修狄梁公廟，於是武相漸求出镇。智計已聞於早成矣。愚曾覽太尉《三朝獻替錄》，真可謂英才，竟罹朋党，亦獨秀之所致也。","sortOrder":6},
  {"id":"s_work_bmtn_8_7","chapterId":"ch_work_bmtn_8","text":"宣宗希冀遐齡，無储嗣，宰臣多有忤旨者，懿宗藩邸常懷危栗。後郭美人誕育一女，未逾月卒，適值懿皇傷忧之际，皇女忽言得活。登極後鐘愛之，封同昌公主，降韦保衡，恩泽無比。因有疾，湯藥不效而殒，医官韓宗昭、康守商等數家皆族誅。劉相國瞻上諫，懿皇不聽。懿皇嘗幸左軍，見觀音像陷地四尺，問左右，對曰：\"陛下中國之天子，菩薩即邊地之道人。\"上悅之。寇入京，郭妃不及奔赴行在，乞食於都城，時人乃嗟之。","sortOrder":7},
  {"id":"s_work_bmtn_8_8","chapterId":"ch_work_bmtn_8","text":"唐自廣明後，閹人擅權，置南北废置使，軍容田令孜有回天之力，中外侧目。而王仙芝、黃巢剽掠江淮，朝廷忧之。左拾遺侯昌業上疏極言時病，留中不出，命於仗內戮之。後有傳侯昌業疏詞不合事體，其末雲：\"請开揭諦道場以消兵厲。\"似為庸僧伪作也，必若侯昌業以此識見犯上，宜其死也。","sortOrder":8},
  {"id":"s_work_bmtn_8_9","chapterId":"ch_work_bmtn_8","text":"隴西李涪常侍，福相之子，质氣古淡。光化中，與諸朝士避地梁川，小貂日遊鄰寺以散鬱陶。寺僧有爽公者因與小貂相識，每晨他出，或赴斋請，苟小貂在寺，即不扃鎖其房，請其宴息，久而弥篤，乃曰：\"李常侍在寺，爭忍阖扉乎。\"或一日，從容謂小貂曰：\"世有黃白之術，信乎好之乎？\"貂曰：\"某雖未嘗留心，安敢不信又安敢辄好\"僧曰：\"貧道之每拂曙出寺，為修功德因緣也。仰常侍德，豈敢秘惜。\"小貂辭遜再三，竟得其術。爾後最受三峰朝相、四入崔相恩知，每遇二公載誕之辰，乃獻銀藥盂子。此外雖家屢空，終不自奉，亦不傳於子孫。遂平宰李璩乃嫡孫也，嘗為愚話之。廣成杜光庭先生常雲：\"未有不修道而希得仙術，苟得之，必致禍矣。唯名行謹絜者往往得之。\"即李貂之謂也。","sortOrder":9},
  {"id":"s_work_bmtn_8_10","chapterId":"ch_work_bmtn_8","text":"陵相扆出典夷陵時，有士子修謁。相國與之從容，因命酒勸。此子辭曰：\"天性不飲酒。\"相國曰：\"誠如所言，已校五分矣。\"蓋平生悔吝若有十分，不為酒困，自然减半也。朱秀才遂寧府人虔餘，舉進士，有《楊貴妃別明皇賦》最佳，然狂於酒。隴州防御使巩鹹乃蜀將也，朱生以乡人下第謁之，巩亦使酒，新鑄一劍，乃曰：\"如何得一漢试之。\"朱便引頸，俄而身首異處。惜哉！死非其所。即陆公之戲，誠哉善言也。東皋子王勣，字無功，有《杜康廟碑》、《醉乡記》備言酒德。竟陵人劉虛白擢進士第，嗜酒，有詩雲：\"知道醉乡無戶稅，任他荒却下丹田。\"世之嗜酒者苟為孔門之徒，得無违告誡乎。","sortOrder":10},
  {"id":"s_work_bmtn_8_11","chapterId":"ch_work_bmtn_8","text":"唐僖宗再幸梁洋，朱玫立襄王，宰相萧遘、裴澈、厥匡圖等同奉之。洎破伪主，而僖皇反正，裴、鄭等緣罹大辟。始具兵衛四围，矛槊森然，裴相猶戲曰：'天子之牆仞也。\"萧遘相就河中，賜毒，握之在手，自以主上舊恩，希貶降，久而毒烂其手，竟飲之而終。","sortOrder":11},
  {"id":"s_work_bmtn_8_12","chapterId":"ch_work_bmtn_8","text":"唐太尉韦公昭度，舊族名人，位非忝竊。而沙門僧澈承恩，為人潛結中禁，京兆與一二時相皆因之大拜。悟達國師知玄，乃澈之師也，嘗鄙之。諸相在西川行在，每謁悟達皆申跪禮，國師揖之，請於僧澈處吃茶。後掌武伐成都，田軍容致檄書曰：\"伏以太尉相國，頃因和尚，方始登庸。在中書則开鋪賣官，居翰林則借人把筆。\"蓋謂此也。","sortOrder":12},
  {"id":"s_work_bmtn_8_13","chapterId":"ch_work_bmtn_8","text":"唐李師望乃諸宗屬也，自負才術，欲以方面為己任。因旅遊邛蜀，備知南蠻之勇怯，遂上書希割西川數州於臨邛郡建定邊軍節度，詔旨允之。乃自鳳翔少尹擢領此任。於時西川大將嫉其分裂巡屬，乃陰通南詔。於是蠻軍為近界乡豪所导，侵軼蜀川，元戎窦滂不能遏截，師望亦尋受貶，黜隴西。光化中，朱朴自《毛詩》博士登庸，恃其口辯可以立致太平，由藩邸引导聞於昭宗，遂有此拜。對扬之日，面陳時事數條，每言\"臣必為陛下致之。\"洎操大柄，無以施展，自是恩泽日衰，中外騰沸。內宴日，俳優穆刀陵作念經行者，至御前曰：\"若是朱相，即是非相。\"翌日出官。時人曰：\"拔士為相，自古有也。君子不恥其言之不出，恥躬之不逮。况唐末丧亂，天下阻兵，雖負奇才不能謀畫，而朱公一儒生，以區區辯給欲整其亂，只自取辱焉。\"涓縷未申，勍敵已至。勤教樂僮吹篳篥，甚為識者所责也。","sortOrder":13},
  {"id":"s_work_bmtn_8_14","chapterId":"ch_work_bmtn_8","text":"唐李群玉校書，字文山，澧州人。有詩名，散逸不樂應舉，親友強之，一上而已。嘗受知於相國河東裴公休，為其延譽，因進詩，授弘文馆校書，終於荆襄間。然多狎酒徒，疑其為張祜之流。李少逢善夷謫官澧陽，備知其行止，因為紀之，乃清介高節之人，非輕率之士，疑為同人所謗。或曰曾為荆之幕下假書題謁澧吏艾使君，李謂艾侯曰：\"小子困甚，幸使君痛救之。\"以戲其姓之癖也。州將以其輕脱，所濟不厚也。又近年京兆韦沆者，衣纓舊族，亦攻古文，流落不偶而没於世。隴西李璩乃福相之曾孫也，常宰襄州樂乡縣。京兆侨於是邑，常來幹扰，李亦只奉不厭。一旦謂李宰曰：\"客有相勉，且求一邑以救飢寒。室人聞之，大怒曰：'人唤郎為長官即得，唤我作長官夫人即不可。'\"隴西聞而鄙薄，亦笑亦怒也。","sortOrder":14},
  {"id":"s_work_bmtn_8_15","chapterId":"ch_work_bmtn_8","text":"先是，李遠以曾有詩雲\"人事三杯酒，流年一局棋\"，唐宣宗以其非牧人之才，不與郡守。宰相為言，然始俞允。蜀相韦莊應舉時，遇黃寇犯闕，著《秦婦吟》一篇，內一聯雲：\"內库燒為錦繡灰，天街踏盡公卿骨。\"爾後公卿亦多垂訝，莊乃讳之，時人號\"秦婦吟秀才\"。他日撰家戒，內不許垂《秦婦吟》障子。以此止謗，亦無及也。晉相和凝少年時好為曲子詞，布於汴洛。洎入相，专托人收拾焚毀不暇。然相國厚重有德，終為艳詞玷之。契丹入夷門，號為\"曲子相公\"。所謂好事不出門，惡事行千里，士君子得不戒之乎。","sortOrder":15},
  {"id":"s_work_bmtn_8_16","chapterId":"ch_work_bmtn_8","text":"宣宗以政事委相國令狐公，君臣道契，人無間然。劉舍人每訐其短，密奏之。宣宗留中，但以其事規於相國，而不言其人姓名。其間以丞相子不拔解就试，疏略雲：\"號曰無解進士，其實有耳未聞\"雲雲，又以子弟納财賄，疏雲：\"白日之下，見金而不見人\"雲雲。丞相憾之。乃俾一人為其書吏，謹事之。紫微托以腹心，都不疑慮，乃為一經業舉人致名第，受賂十萬，為此吏所告，由是貶之。君子曰：\"彭城公將欲律人，先須絜己。安有自負贓污而發人之短乎宜其不跻大位也。\"先是令孤相自以单族，每欲繁其宗党與崔、盧抗衡，凡是富家，率皆引進。皇籍有不得官者欲進状，請改姓令孤。時以此少之。","sortOrder":16},
  {"id":"s_work_bmtn_8_17","chapterId":"ch_work_bmtn_8","text":"唐吳郡陆龟蒙，字魯望，舊名族也。其父賓虞，進士甲科，浙東從事、侍御史，家於蘇台。龟蒙幼精六籍，弱冠攻文，與顏荛、皮日休、羅隱、吳融為益友，性高絜。家貧，思養親之祿，與張博為吳興、庐江二郡倅，著《吳興實錄》四十卷、《松陵集》十卷、《笠泽丛書》五卷。丞相李公蔚、盧公携景重之，羅給事《寄陆龟蒙》詩雲：\"龍樓李丞相，昔歲仰高文。黃閣今無主，青山竟不焚。\"蓋嘗有征聘之意。唐末以左拾遺授之，詔下之日疾終。光化三年赠右補闕，吳侍郎融傳貽史，右補闕韦莊撰诔文，相國陆希聲撰碑文，給事中顏荛書，皮日休博士為詩。皮寇死浙中。方幹詩名著於吳中，陆未許之，一旦頓作詩五十首裝為方幹新製，時辈吟賞降仰，陆謂曰：\"此乃下官效方幹之作也，方詩在模范中爾。\"句奇意精，識者亦然之。薛許州能以詩道為己任，還劉德仁卷，有詩雲：\"百首如一首，卷初如卷終。\"譏劉不能变態，乃陆之比也。","sortOrder":17},
  {"id":"s_work_bmtn_8_18","chapterId":"ch_work_bmtn_8","text":"顏給事荛謫官，没於湖外，嘗自草《墓志》，性躁急不能容物，其志詞雲：\"寓於東吳，與吳郡陆龟蒙為詩文之交，一紀無渝。龟蒙卒，為其就木至穴，情禮不缺。其後即故諫議大夫高公丞之、故丞相陆公扆，二君於荛至死不变。其餘面交皆如携手過市，見利即解携而去，莫我知也。复有吏部尚書辭公貽矩、兵部侍郎於公兢、中書舍人鄭公撰，三君子者，餘今日已前不变，不知異日見餘骨肉孤幼复如何哉。\"","sortOrder":18},
  {"id":"s_work_bmtn_8_19","chapterId":"ch_work_bmtn_8","text":"司空圖侍郎撰《李公磎行状》，以\"公有出倫之才，為時辈妒忌，罹於非橫。其平生著文有《百家著諸心要文集》三十卷、《品流志》五卷、《易之心要》三卷、《註論語》一部、《明無為》上下二篇、《義說》一篇，仓卒之辰焚於賊火，時人無所聞也，惜哉！《陽春白雪》，世人寡和，豈虛言也\"葆光子曰：\"唐代韓愈、柳宗元洎李翱、李觀、皇甫湜數君子之文，陵轹荀孟，糠秕顏謝，其所宗仰者唯梁浩補闕而已。乃諸人之龟鑒而梁之聲采寂寂，豈《陽春白雪》之流乎是知俗譽喧喧者宜鑒其濫吹也。\"","sortOrder":19},
  {"id":"s_work_bmtn_8_20","chapterId":"ch_work_bmtn_8","text":"白太傅與元相國友善，以詩道著名，時號元白。其集內有詩《挽元相》雲：\"相看掩淚俱無語，別後傷心事豈知。想得鹹陽原上树，已抽三丈白楊枝。\"洎自撰《墓志》雲：\"與彭城劉夢得為詩友\"，殊不言元公，時人疑其隙終也。鄭文公畋與盧相携親表也，閥閱相齊，詞學相均，同在中書，因公事不葉，揮霍間言語相挤詬，不覺砚瓦翻泼。謂宰相斗击亦不然也，竟以此出官矣。","sortOrder":20},
  {"id":"s_work_bmtn_8_21","chapterId":"ch_work_bmtn_8","text":"古者閹官擅權专製者多矣，其間不無忠孝，亦存簡編。唐自安史已來，兵難荐臻，天子播越，親衛戎柄皆付大閹，魚朝恩、窦文場乃其魁也。爾後置左右軍、十二衛，觀軍容、處置、枢密、宣徽四院使，擬於四相也。十六宮使皆宦者為之，分卿寺之職，以權為班行備員而已。供奉官紫綬入侍，後軍容使楊复恭俾其襴笏宣导，自弘農改作也。嚴遵美，內褐之最良也，嘗典戎，唐末致仕，居蜀郡，鄙叟庸夫時得親狎。其子仕蜀至合門使，曾為一僧致紫袈裟。僧來感謝，書記所謝之語於掌中，方屬炎天，手汗模糊，文字莫辨，折腰而趨，汗流喘乏，只雲\"伏以軍容\"，寂無所道。抵掌视之，良久雲：\"貌寢人微，凡事無能。\"嚴公曰：\"不敢。\"退而大咍。嚴公物故，蜀朝册赠命，給事中窦雍堅不承命。雖偏霸之世亦不苟且，士人多之。","sortOrder":21},
  {"id":"s_work_bmtn_8_22","chapterId":"ch_work_bmtn_8","text":"唐羅給事隱、顧博士雲俱受知於相國令狐公。顧雖鹾商之子，而風韻詳整，羅亦錢塘人，乡音乖刺。相國子弟每有宴會，顧獨與之，丰韻談諧，莫辨其寒素之士也。顧文賦為時所稱，而切於成名，嘗有啟事陳於所知，只望丙科盡處，竟列名於尾株之前也。羅既頻不得意，未免怨望，竟為貴子弟所排，契闊東歸。黃寇事平，朝賢議欲召之，韦貽范沮之曰：\"某曾與之同舟而載。雖未相識，舟人告雲：'此有朝官。'羅曰：'是何朝官！我腳夹筆亦可以敵得數辈。'必若登科通籍，吾徒為秕糠也。\"由是不果召。詩人方幹亦吳人也，王龟大夫重之，既延入內，乃連下兩拜。亚相安詳以答之，未起間，方又致一拜，時號\"方三拜\"也。","sortOrder":22},
  {"id":"s_work_bmtn_8_23","chapterId":"ch_work_bmtn_8","text":"梁李相國琪，唐末以文學策名，仕至御史。昭宗播遷，衣冠荡析，因與弘農楊玢藏跡於荆楚間。楊即溯蜀，琪相盤桓於夷道之清江，自晦其跡，號華原李長官。其堂兄光符宰宜都，嘗厭薄之。琪相寂寞，每臨流跋石，摘树葉而试草製詞，吁嗟怏怅而投於水中。梁祖受禪，征入，拜翰林學士，尋登廊廟。爾後宜都之子彬羁旅渚宮，因省相國，乃數厥父之所短而遣之矣。","sortOrder":23},
  {"id":"s_work_bmtn_8_24","chapterId":"ch_work_bmtn_8","text":"唐杜荀鶴嘗遊梁，獻太祖詩三十章，皆易晓也，因厚遇之。洎受禪，拜翰林學士，五日而卒。朱崖李太尉奖拔寒俊，至於掌誥，率用子弟，乃曰：\"以其谙練故事以濟缓急也。如京兆者，一篇一詠而已，經國大手非其所能。幸而殂逝，免貽伊恥也。\"製貶平曾、贾島，以其僻涩之才無所采用，皆此類也。","sortOrder":24},
  {"id":"s_work_bmtn_8_25","chapterId":"ch_work_bmtn_8","text":"唐昭宗劫遷，百官荡析，名娼伎兒皆為強諸侯有之。供奉彈琵琶樂工號關別駕，小紅者，小名也。梁太祖求之，既至，謂曰：\"爾解彈《羊不采桑》乎？\"關伶俯而奏之。及出，又為親近者俾其彈而送酒，由是失意，不久而殂。复有琵琶石潨者，號石司馬，自言早為相國令狐公見賞，俾與諸子涣、湚連水邊作名也。亂後入蜀，不隸樂籍，多遊諸大官家，皆以賓客待之。一日會軍校數員飲酒作歡，石潨以胡琴擅場，在坐非知音者，喧哗語笑，殊不傾聽。潨乃扑槽而詬曰：\"某曾為中朝宰相供奉，今日與健兒彈而不蒙我聽，何其苦哉！\"於時識者亦叹訝之。丧亂以來，冠履顛倒，不幸之事何可勝道，豈獨賤伶雲乎哉！","sortOrder":25},
  {"id":"s_work_bmtn_8_26","chapterId":"ch_work_bmtn_8","text":"唐樂安孫氏，進士孟昌期之內子，善為詩，一旦併焚其集，以為才思非婦人之事，自是专以婦道內治。孫有《代夫赠人白蠟燭》詩曰：\"景勝銀釭香比蘭，一條白玉逼人寒。他時紫禁春風夜，醉草天書仔細看。\"又《聞琴》詩曰：\"玉指朱絃軋後清，湘妃愁怨最難聽。初疑飒飒涼風動，又似萧萧暮雨零。近若流泉來碧嶂，遠如玄鶴下青冥。夜深彈罢堪惆怅，霧濕丛蘭月滿庭。\"又《代謝崔家郎君酒》詩曰：\"謝將清酒寄愁人，澄澈甘香氣味真。好是绿窗明月夜，一杯搖荡滿懷春。\"又台州盤巏叙村有一婦人萧惟香，有才思，未嫁，於所居窗下與進士王玄宴相對，因奔琅琊。复淫治不禁，王舍於逆旅而去。遂私接行客，托身無所，自經而死，店有數百首詩。所謂才思非婦人之事，誠然也哉！聞於劉山甫。","sortOrder":26},
  {"id":"s_work_bmtn_9_1","chapterId":"ch_work_bmtn_9","text":"●卷七","sortOrder":1},
  {"id":"s_work_bmtn_9_2","chapterId":"ch_work_bmtn_9","text":"唐襄陽孟浩然與李太白交遊。玄宗征李入翰林，孟以故人之分，有彈冠之望，久無消息，乃入京謁之。一日，玄宗召李入對，因從容說及孟浩然，李奏曰：\"臣故人也，見在臣私第。\"上令急召，賜對，俾口進佳句，孟浩然誦詩曰：\"北闕休上書，南山歸敝庐。不才明主弃，多病故人疏。\"上意不悅，乃曰：\"未曾見浩然進書，朝廷退黜，何不雲'氣蒸雲夢泽，波動嶽陽城'\"緣是不降恩泽，終於布衣而已。宣宗索趙嘏詩，其卷首有《題秦皇》詩，其略雲：\"徒知六國隨斤斧，莫有群儒定是非。\"上不悅。","sortOrder":2},
  {"id":"s_work_bmtn_9_3","chapterId":"ch_work_bmtn_9","text":"唐相國鄭綮雖有詩名，本無廊廟之望。嘗典庐州，吳王楊行密為本州步奏官，因有遺闕而笞责之。然其儒懦清慎，弘農常重之。昭宗時，吳雄據淮海，朝廷務行姑息，因盛言鄭公之德，由是登庸，中外驚駭。於是皇綱已紊，四方多故。相國既無施展，事必依违。太原兵至渭北，天子震恐，渴於攘却之術，相國奏對，請於文宣王謚號中加一\"哲\"字。其不究時病率此類也。同列以其忝竊，每譏侮之，相國乃題詩於中書壁上，其詞曰：\"侧坡蛆崑崙，蚁子競來拖。一朝白雨下，無钝無喽囉。\"意者以時運將衰，縱有才智亦不能康濟，當有玉石俱焚之慮也，時亦然之。相國《題老僧》詩雲：\"日照西山雪，老僧門未开。冻瓶粘柱礎，宿火焰爐灰。童子病歸去，鹿麑寒入來。\"常雲：\"此詩屬對可以稱衡，重輕不偏也。\"或曰：\"相國近有新詩否\"對曰：\"詩思在灞桥風雪中驢子上，此處何以得之\"蓋言平生苦心也。","sortOrder":3},
  {"id":"s_work_bmtn_9_4","chapterId":"ch_work_bmtn_9","text":"李程以《日五色賦》擢第。為河南尹日，试舉人，有浩虛舟卷中行《日五色賦》。程相大驚，慮掩其美，伸覽之次，服其才麗，至末韻\"侵晚水以芒動，俯寒山而秀發\"，程相大咍曰：\"李程賦且在，瑞日何為到夜秀發？\"由是浩賦不能陵邁。","sortOrder":4},
  {"id":"s_work_bmtn_9_5","chapterId":"ch_work_bmtn_9","text":"唐進士來鵬詩思清麗，福建韦尚書岫愛其才，曾欲以子妻之，而後不果。爾後遊蜀，夏課卷中有詩雲：\"一夜绿荷風翦破，赚他秋雨不成珠。\"識者以為不祥。是歲不隨秋賦而卒於通議郎。前進士沈光有《洞庭樂賦》，韦八座岫謂朝賢曰：\"此賦乃一片宮商也。\"後辟為閩從事。弘農楊敬之撰《華山賦》，朱崖李太尉每置座右，行坐諷之。其略雲：\"見若咫尺，田千畝矣；見若環堵，城千雉矣；見若杯水，池百里矣；見若蚁垤，寶九層矣。醯雞往來，周東西矣，蠛蠓紛紜，強秦去矣；蜂巢聯聯，構阿房矣，俄而复然，立建章矣，小星奕奕，焚鹹陽矣；累累茧栗，祖龍藏矣。其千載改更興懷，悲愁辛苦，循其上矣。\"","sortOrder":5},
  {"id":"s_work_bmtn_9_6","chapterId":"ch_work_bmtn_9","text":"唐乾寧中，劉昌美典夔州，時屬夏潦，峡涨湍险，俚俗雲：\"滟澦大如馬，瞿塘不可下。\"於是行旅輟棹而候水平去焉。有朝官李荛學士，挈家自蜀沿流，將之江陵。郡牧以水势正惡，且望少駐以圖利涉。隴西總遽，殆為人所促召，堅請東下，不能止之。才鼓行桡，長揖而別，州將目送之际，盤渦呀裂，破其船而倒。李一家溺死焉，唯奶嫗一人隔夜為駭浪推送江岸而蘇。先是，永安監竈戶陳小奴棹空船下瞿塘，見崖下有一人，裹四縫帽，穿白缺衫、皂義襴、青褲，執鐵蒺藜，問李公之行邁，自雲\"迎候\"。其奶嫗蘇後亦說於刺史雲：\"李學士至一官署上廳事，朱門白壁，僚吏參贺。又聞雲'此行無奶嫗名'，遂送出水濱。\"於時具以其事奏聞，自後以瞿塘為水府，春秋祭之。初，隴西文賦中有《金釵墜井賦》，至是讖焉。世傳雲：\"人之正直，死為冥官。\"道書雲：\"酆都陰府官屬，乃人間有德者卿相為之，亦號陰仙。\"近代朱崖李太尉、張讀侍郎小說鹹有判冥之說。劉昌美兩典夔州，雲安縣僧玄悟，曾有蜀川將校王尚書者，舍己俸三百千以修觀音堂，乃剩三十千入己。一旦物故，經七日，鄰於腐坏，忽然再蘇，灌湯藥以辅之，言曰：\"初至一官曹，見劉行軍說雲：\"何乃侵用功德錢以舊曾相識，放歸，須還此錢。\"玄悟乃戒門人鬻衣鉢而偿之，尋复卒也。西川孔目官勾伟，於其辈最號廉直，綿竹縣民王氏子病困入冥，因复還魂，見冥官謂曰：\"我即勾孔目也，家在成都西市，曾負人錢三萬未偿。汝今歸去，為我言於家人也。\"王生後訪勾氏子，仍以债主姓名言之，果為酬還。","sortOrder":6},
  {"id":"s_work_bmtn_9_7","chapterId":"ch_work_bmtn_9","text":"唐盧延讓業詩，二十五舉方登一第。卷中有句雲：\"狐冲官道過，狗觸店門开。\"租庸張浚親見此事，每稱賞之。又有饿猫臨鼠穴，饞犬舐魚砧\"之句，為成中令汭見賞。又有\"栗爆燒氈破，猫跳觸鼎翻\"句，為王先主建所賞。嘗謂人曰：'平生投謁公卿，不意得力於猫兒狗子也。\"人聞而笑之。盧嘗有詩雲：\"不同文賦易，為是者之乎。\"後入翰林，閣筆而已。同列戲之曰：\"不同文賦易，為是者之乎。\"竟以不稱職，數日而罢也。","sortOrder":7},
  {"id":"s_work_bmtn_9_8","chapterId":"ch_work_bmtn_9","text":"唐晉相李渷，磎相之子也，文學淵奧，迥出辈流，於時公相之子弟無能及者。應舉時，文卷行《明易先生書》，又有《答明易先生書》，朝士覽之，不测涯涘，即其他文章可知也。然恃才躁進，竟罹非禍。爾後磎相追雪，赠太子太師，謚曰文，司空圖撰《行状》，渷赠禮部員外郎。先是，劉崇魯舍人撰磎相麻，因而貶黜。磎以大彭先世，因贓仰藥，撰《鸚鵡杯賦》，李渷酬詞雲：\"玉犬吠天關，彩童哭仙吏。一封紅篆書，為奏尘宸事。八極鰲柱傾，四溟龍鬣沸。長庚冷有芒，文曲淡無氣。乌輪不再中，黃沙瘞腥鬼。請帝命真官，臨雲啟金匮。方與清華宮，重正紫極位。曠古兩露恩，安得借沾施。生人血欲盡，欃槍無飽意。\"甚有文義焉。又皮日休曾謁歸融尚書不見，因撰《夹虵龟賦》，譏其不出頭也，而歸氏子亦撰《皮靸鞋賦》遞相謗誚。皮生後為湖南軍倅，亦甚傲誕，自號間氣布衣，莊布以長書责之，行於世也。","sortOrder":8},
  {"id":"s_work_bmtn_9_9","chapterId":"ch_work_bmtn_9","text":"唐滎陽鄭准以文筆依荆州，成中令常欲比肩陳、阮。自集其所作為三卷，號《劉表軍書》，雖有胸襟而辭體不雅，至祝朝貴書雲中書令舍人曰草麻，通事舍人曰奏可。又贺襄州趙令嗣袭，其書雲：\"不沐浴佩玉而石祁光，不登山取符而無恤封。\"是於慶贺中顯言其庶賤也，鄰道之敬其若是乎應舉日詩卷《題水牛》曰：\"護犢橫身立，逢人揭尾跳。\"朝士以為大笑。唐前朝進士陳詠，眉州青神人，有詩名，善弈棋。昭宗劫遷，駐跸陝郊，是歲策名歸蜀，韦書記莊以詩贺之，又有乡人拓善者屬和韦詩，其略雲：\"讓德已聞多士伏，沽名還得世人聞。\"譏其比涤器當壚也，谬稱冯副使涓詩，以涓多諧戲故也。或雲蜀之拓善者作此詩假冯公之名也。潁川嘗以詩道自負，謁荆幕鄭准。准亦自負雄筆，謂潁川曰：\"今日多故，不暇操染，有三數處回緘，祈為假手。\"潁川自旦及暮，起草不就，蓋欲以高之。其詩卷首有一對語雲：\"隔岸水牛浮鼻渡，傍溪沙鳥點頭行。\"京兆杜光庭先生謂曰：\"先辈佳句甚多，何必以此為卷首。\"潁川曰：\"曾為朝貴見賞，所以刻於首章。\"都是假譽求售使然也。","sortOrder":9},
  {"id":"s_work_bmtn_9_10","chapterId":"ch_work_bmtn_9","text":"唐末，鳳翔判官王超推奉李茂貞，挟曹馬之势，箋奏文檄，恣意翱翔。王蜀先主初下成都，冯涓節製掌判其奏箋，歲久轉廳，以掌記辟韦莊郎中於權变之間，未甚愜旨。阆州人王保晦有文才而無體式，然其切露直致，易為晓悟，加以鳳翔用王超箋奏，超以一本舊族，思偶風雲，每遇飛章，言伪而辯。蜀先主愛之，以二王書題表稿示長樂公，公乃致書遜謝，倍加贊賞，其要曰：\"有眼未見，有耳未聞。\"蓋譏其阻兵恃強，失事君去就。王超後為興元留後，遇害，有《鳳鳴集》三十卷行於世。後又有名石钦若者，體效其筆，為劉知俊判官，隨軒降蜀，不能謙退遠害，賓主爭露鋒穎，竟同誅之。閱其緘題表章行行然，宜其見忌而取禍也。許存初背荆州成中令降蜀，先主有意殺之。親吏柳修業勸其謙靜，每立大功而皆托疾，由是獲免於先主之世，即彭城之舊僚不若高陽之小吏矣。王超全集三十卷，今只見三卷，聞於盧卿宏也。","sortOrder":10},
  {"id":"s_work_bmtn_9_11","chapterId":"ch_work_bmtn_9","text":"李商隱員外依彭陽令狐公楚，以箋奏受知。相國危急，有寶劍嘗為君上所賜，將進之，命李起草，不愜其旨，因口占雲：\"前件劍，武库神兵，先皇特賜。既不合將歸泉下，又不宜留在人間。\"時人服其簡當。彭陽之子繼有韦平之拜，似疏隴西，未嘗展分。重陽日，義山詣宅，於廳事上留題，其略雲：\"十年泉下無消息，九日樽前有所思。郎君官重施行馬，東閤無因許再窥。\"相國睹之，慚怅而已，乃扃閉此廳，終身不處也。蜀中庾傳昌舍人，始為永和府判官，文才敏贍，傷於冗雜。因候相國張公，有故未及見，庾怒而歸，草一啟事，仅數千字，授於謁者，拂袖而去。他日，張相謂朝士曰：\"庚舍人見示長箋，不可多得。雖然，曾聞其草角觝牒詞，動乃數幅。\"譏其無簡當體要之用也。黃籙擅場，星辰備位，顧雲博士為高燕公草斋詞雲：\"天靜則星辰可摘。\"奇险之句施於至敬可乎唐末亂離，渴於救時之術。孔相國緯每朝士上封事，不暇周覽，但曰：\"古今存亡某知之矣，未審所陳利害其要如何。\"蓋鄙其不達变也。國子司業於晦曾上崔相國公胤啟事數千字，上至尧舜，下及隋唐，一興一替，歷歷可紀，其末散漫，殊非簡略。所以儒生中通变者鮮矣。","sortOrder":11},
  {"id":"s_work_bmtn_9_12","chapterId":"ch_work_bmtn_9","text":"唐高相國崇文，本蓟州將校也，因讨劉辟有功，授西川節度使。一旦大雪，諸從事吟賞有詩，渤海遽至飲席，笑曰：\"諸君自為樂，殊不見顧鄙夫。鄙夫雖武人亦有一詩。\"乃口占雲：\"崇文崇武不崇文，提戈出塞號將軍。那个■兒射落雁，白毛空里落紛紛。\"其詩著題，皆謂北齊敖曹之比也。太尉骈即曾孫也，镇蜀日，以蠻蜑侵暴，乃筑羅城。城四十里，朝廷雖加恩賞，亦疑其固護。或一日，聞奏樂聲，知有改移，乃題風筝寄意曰：\"夜靜絃聲响碧空，宮商信任往來風。依稀似曲才堪聽，又被移將別調中。\"旬日報到，移镇渚宮。","sortOrder":12},
  {"id":"s_work_bmtn_9_13","chapterId":"ch_work_bmtn_9","text":"湘江北流，至嶽陽達蜀江，夏潦後蜀涨势高，遏住湘波，讓而退溢為洞庭湖，凡闊數百里，而君山宛在水中。秋水歸壑，此山复居於陆，唯一條湘川而已。海為桑田，於斯验也。前辈許棠《過洞庭》詩最為首出，爾後無繼斯作。詩僧齊已駐錫巴陵，欲吟一詩，竟未得意。有都押衙者，蔡姓而忘其名，戲謂己公曰：\"題洞庭者某詩絕矣，諸人幸勿措詞。\"己公堅請口劄，押衙抑扬朗吟曰：\"可怜洞庭湖，恰到三冬無髭須。\"以其不成湖也。諸僧大笑之。進士李洞慕贾島，欲鑄而顶戴，嘗念贾島佛，而其詩體又僻於贾。复有包贺者，多為粗鄙之句，至於\"苦竹筍抽青橛子，石榴树掛小瓶兒\"，又雲\"霧是山巾子，船為水靸鞋\"，又雲\"棹搖船掠鬢，風動竹搥胸\"，雖好事托以成之，亦空穴來風之義也。盧延讓《哭邊將》詩曰：\"自是磠砂發，非幹礮石傷。牒多身上職，盎大背邊瘡。\"人謂此是打脊詩也。世傳逸詩雲：\"窗下有時留客宿，室中無事伴曾眠。\"號曰自落便宜詩。顧况著作披道服在茅山，有一秀才行吟曰：\"駐馬上山阿。\"久思不得。顧曰：\"何不道'風來屎氣多'？\"秀才雲：\"賢莫無禮。\"顧曰：\"是况。\"其人慚惕而退。仆早歲嘗和南越詩雲：\"晓厨烹淡菜，春杼織穜花。\"牛翰林覽而絕倒，莫喻其旨，牛公曰：\"吾子只知名，安知淡菜非雅物也。\"後方晓之。學吟之流，得不以斯為戒也。","sortOrder":13},
  {"id":"s_work_bmtn_9_14","chapterId":"ch_work_bmtn_9","text":"進士高蟾，詩思雖清，務為奇险，意疏理寡，實風雅之罪人。薛許州謂人曰：\"倘見此公，欲赠其掌。\"然而《落第》詩曰：\"天上碧桃和露种，日邊紅杏倚雲栽。芙蓉生在秋江上，不向春風怨未开。\"蓋守寒素之分，無躁競之心，公卿間許之。先是，胡曾有詩曰：\"翰苑何時休嫁女，文章早晚罢生兒。上林新桂年年發，不許平人折一枝。\"羅隱亦多怨刺，當路子弟忌之，由是渤海策名也。愚嘗覽李贺歌詩篇，慕其才逸奇险，雖然，嘗疑其無理，未敢言於時辈。或於奇章公集中見杜紫薇牧有言\"長吉若使稍加其理，即奴仆命骚人可也\"，是知通論合符不相遠也。","sortOrder":14},
  {"id":"s_work_bmtn_9_15","chapterId":"ch_work_bmtn_9","text":"杜荀鶴曾得一聯詩雲：\"舊衣灰絮絮，新酒竹篘篘。\"時韦相國說右司員外郎寄寓荆州，或語於韦公，曰：\"我道'印將金鎖鎖，帘用玉鉤鉤。'\"即京兆大拜氣概，詩中已見之矣。或有述李頻詩於錢尚父曰：\"只將五字句，用破一生心。\"尚父曰：\"可惜此心何所不用，而破於詩句，苦哉！\"","sortOrder":15},
  {"id":"s_work_bmtn_9_16","chapterId":"ch_work_bmtn_9","text":"唐荆南節判司空董與京兆杜無隱，即滑台杜慆常侍之子，洎蜀人梁震俱稱進士，謁成中令，欲希荐送。有薛少尹者，自蜀沿流至渚宮。三賢嘗訪之。一日，薛亚尹謂司空曰：\"閣下與京兆勿議求名，必無所遂。杜亦不寿，唯大賢忽為人縶維，官至朱紫。如梁秀才者，此舉必捷，然登第後一命不沾也。\"後皆如其言。梁公却思歸蜀，重到渚宮，江路梗紛，未及西溯。淮師寇江陵，渤海王邀致府衙，俾草檄書，欲辟於府幕。堅以不仕為志，渤海竟诺之。二紀依栖，竟麻衣也。薛尹之言，果验耶。","sortOrder":16},
  {"id":"s_work_bmtn_9_17","chapterId":"ch_work_bmtn_9","text":"廣南劉仆射崇龟常有台辅之望，必謂罢镇，便期直上。羅浮處士夏侯生有道，彭城重之，因問將來之事。夏生言其不入相，發後三千里有不测之事。洎歸闕，至中路得疾而薨。劉山甫亦蒙夏生言，示五年行止。事無不验。蓋飲啄之有分也。","sortOrder":17},
  {"id":"s_work_bmtn_9_18","chapterId":"ch_work_bmtn_9","text":"唐曹相國確判計亦有台辅之望，或夢剃度為僧，心甚惡之。有一士占夢多验，相國召之，具以所夢語之。此人曰：\"前贺侍郎旦夕必登庸。出家者，號剃度也。\"無何，杜相出镇江西，而相國大拜也。","sortOrder":18},
  {"id":"s_work_bmtn_9_19","chapterId":"ch_work_bmtn_9","text":"福建道以海口黃碕岸橫石巉峭，常為舟楫之患。閩王琅琊王審知思欲製置，憚於力役。乾寧中，因夢金甲神自稱吳安王，許助开凿。及覺，話於賓僚，因命判官劉山甫躬往設祭，具述所夢之事，三奠未終，海內靈怪具見。山甫乃憩於僧院，凭高觀之，風雷暴興，見一物非魚非龍，鱗黃鬣赤。凡三日，風雷止霁，已別开一港，甚便行旅。當時錄奏，賜號甘棠港。閩從事劉山甫乃中朝舊族也，著《金溪閒談》十二卷，具載其事。愚嘗略得披覽，而其本偶亡絕，無人收得。海隅迢遞，莫可搜訪。今之所集雲聞於劉山甫，即其事也，十不記其三四，惜哉！","sortOrder":19},
  {"id":"s_work_bmtn_9_20","chapterId":"ch_work_bmtn_9","text":"光化中，有文士劉道濟止於天台山國清寺，夢見一女子引入窗下，有侧柏树葵花，遂為伉俪。後頻於夢中相遇，自不晓其故。無何，於明州奉化縣古寺內見有一窗侧柏葵花，宛是夢中所遊。有一客官人寄寓於此室，女有美才，貧而未聘，近中心疾，而生所遇乃女之魂也。蓋女子及笄不有所歸，豈非父兄之過哉。又有彭城劉生，夢入一倡婦家，與諸辈狎飲。爾後但夢便乃彼處，自疑非夢，所遇之姬芳香常袭衣。蓋心邪所致。聞於劉山甫也。","sortOrder":20},
  {"id":"s_work_bmtn_10_1","chapterId":"ch_work_bmtn_10","text":"●卷八","sortOrder":1},
  {"id":"s_work_bmtn_10_2","chapterId":"ch_work_bmtn_10","text":"唐李太尉德裕左降至朱崖，著《四十九論》，叙平生所志，嘗遺段少常成式書曰：\"自到崖州，幸且顽健。居人多養雞，往往飛入官舍，今且作祝雞翁爾。謹状。\"吉甫相典忠州，溯流之任，行次秭歸，地名雲居台，在江中。掌武誕於此處，小名台郎，以其地而命名也。","sortOrder":2},
  {"id":"s_work_bmtn_10_3","chapterId":"ch_work_bmtn_10","text":"唐孫會宗仆射，即偓相大王父也，宅中集內外親表开宴。有一甥侄為朝官，後至。及中門，見緋衣官人衣襟前皆是酒污，咄咄而出，不相識。洎即席說與主人，鹹訝無此官。沉思之，乃是行酒時於階上酹酒，草草傾泼也。自此每酹酒侧身恭跪，一酹而已，自孫氏始也。今人三酹，非也。有裴迪者，贽相之堂弟，無文學。於荆南投筆事趙司徒，為虞總小將，對客侧身一酹。趙公未喻朝賢間風規，極怪之，笞七下，何不幸也！","sortOrder":3},
  {"id":"s_work_bmtn_10_4","chapterId":"ch_work_bmtn_10","text":"唐張裼尚書朝望既高，號為流品，與韦相保衡有分。韦言於同列，以其名裼，裼，訓袒衣也，又《詩》雲：\"載衣之裼。\"裼即小兒褓衣，乃绷帶也。方欲因事改之，未幾，韦相流貶，竟不大拜。韦嘗問立名之由，楊以少孤，為無學問親表所誤也。後唐姚相名洎，善談吐，仍多辯捷。表兄弟崔沂侍郎戲之曰：\"洎訓肉汁，胡為名\"洎無以酬之，然洎亦訓至。雖然，古人以名貽誚者多矣，妨事者有焉。至如仙客、仙童、齊丘、用砺、希斆人過，亦無取焉。其衤复名須依義訓，唯单名易讳者善矣。裼公生五子，彝憲、文蔚知名，文蔚後登庸也。","sortOrder":4},
  {"id":"s_work_bmtn_10_5","chapterId":"ch_work_bmtn_10","text":"唐張裼尚書典晉州，名貯所愛營妓，生一子。其內子蘇氏號尘外，妒忌。不敢取歸，乃與所善張處士為子，居江津間，常致書題問其存亡，資以錢帛。及漸成長，教其讀書。有人告以\"非處士之子，爾父在朝，官高\"，因竊其父與處士緘劄，不告而遁歸京國。裼公已薨。至宅門，僮仆無有識者，但雲\"江淮郎君\"，兄弟皆愕然。其嫡母蘇夫人泣而謂諸子曰：\"誠有此子，吾知之矣。我少年無端，致其父子死生永隔，我罪多矣。\"家眷聚泣，取入宅，齒諸兄弟之列，名仁龟。有文，性好學，修詞應進士舉，及第，歷侍御史。因奉使江浙，於候馆自經而死，莫知所為。先是，張處士怅恨而終，必有冥訴，罹此禍也。柱史為楊鉅侍郎愛婿也。","sortOrder":5},
  {"id":"s_work_bmtn_10_6","chapterId":"ch_work_bmtn_10","text":"唐相國裴公坦，大和八年李漢侍郎下及第。自以舉業未精，遽此叨忝，未嘗曲謝座主，辭歸鄠縣別墅。三年肄業，不入城，歲時恩地，唯啟状而已，至於同年，鄰於謝絕，掩關勤苦，文格乃变。然始到京，重獻恩門文章，詞采典麗，舉朝稱之。後至大拜，為時名相也。夫世之幹祿，先資名第，既得之後，鮮不替懈，自非篤於文學省顧賓實者，安能及斯，裴公廟堂之期，有以見進德之無斁也。","sortOrder":6},
  {"id":"s_work_bmtn_10_7","chapterId":"ch_work_bmtn_10","text":"唐鹹通中，舉子侯泳有聲采，亦士流也，而闕於恭慎。豆盧琢罢相，守仆射，乘閒詣僧院，放仆乘他適，而於僧宇獨坐，皤然一叟也。泳自外入門，殊不顧揖，傲岸據榻，謂叟曰：\"大參長史乎？\"叟曰：\"非也。\"又問曰：\"令錄乎？\"亦曰：\"非也。\"\"遠州刺史乎？\"亦曰：\"稍高。\"又曰：\"少卿監乎？\"答曰：\"更向上。\"侯生矍然不安處，疑是丞郎，匆遽而出，至門，見仆御肩舆旋至，方知是豆盧公也。歸去後自咎悚惕，貢一長箋首過，賴先曾有卷及門，揆路通入。泳乃自陳乖疏，公亦遜謝，恕其不相識也，留而命酒，凡勸十盂，乃小懲也，仍雲：\"雖不奉訝，然凡事更宜在意。\"侯生仍慚灼無以自容。先是，豆盧家崑弟飲清酒而已，侯氏盛饌而飲。此日每飲一杯，回首摘席經咀之，幾不濟，所謂雅责也。","sortOrder":7},
  {"id":"s_work_bmtn_10_8","chapterId":"ch_work_bmtn_10","text":"唐陝州廉使盧沆在舉場甚有時稱，曾於滻水逆旅遇宣宗皇帝微行，意其貴人，斂身回避。帝揖與相見，沆乃自稱進士盧沆。帝請詩卷，袖之乘驢而去。他日對大臣語及盧沆，令主司擢第。沆不自安，恐僭冒之辱。宰臣向沆與主上有何階緣，沆乃具陳因由，時亦不訝，以其文章非叨忝也。沆後自廉察入朝知舉，遇黃寇犯闕，不及終場。趙崇大夫戲之曰：\"出腹不生養主司也。\"初盧家未嘗知舉，盧相携恥之，拔為主文，竟不果也。贾島遇宣宗微行，問秀才名，對曰：\"贾島。\"帝曰：\"久聞詩名。\"島曰：\"何以知之\"後言於宰臣，與平曾相次謫授長江尉，所謂不識貴人也。","sortOrder":8},
  {"id":"s_work_bmtn_10_9","chapterId":"ch_work_bmtn_10","text":"唐著作郎顧况，字逋翁，好輕侮朝士，貶在江外，多與僧道交遊，時居茅山。暮年有一子，即非熊前身也。一旦暴亡，况追悼哀切，所不忍言，乃吟曰：\"老人丧愛子，日暮泣成血。老人年七十，不作多時別。\"非熊在冥間聞之，甚悲憶，遂以情告冥官，皆悯之，遂商量却令生於况家。三歲，能言冥間聞父苦吟却求再生之事歷歷然。長成應舉，擢進士第。或有朝士問，即垂泣而言之。王定保《摭言》雲：\"人傳氵兄父子皆有所遇，不知何適\"由此而言，信有之矣。","sortOrder":9},
  {"id":"s_work_bmtn_10_10","chapterId":"ch_work_bmtn_10","text":"唐張禕侍郎朝望甚高，有愛姬，早逝，悼念不已。因入朝未回，其猶子右補闕曙才俊風流，因增大阮之悲，乃製《浣溪紗》，其詞曰：\"枕障薰爐繡帏，二年終日兩相思。好風明月始應知。天上人間何處去，舊歡新夢覺來時。黃昏微雨畫帘垂。\"置於幾上。大阮朝退，凭幾無聊，忽睹此詩，不覺哀恸，乃曰：\"必是阿灰所作。\"阿灰即中諫小字也。然於風教似亦不可，以其叔侄年顏相似，恕之可耳。諺曰：\"小舅小叔，相追相逐。\"謔戲固不免也。","sortOrder":10},
  {"id":"s_work_bmtn_10_11","chapterId":"ch_work_bmtn_10","text":"唐張裼尚書恃才直道，外仍有至性。及第後歸東都，一日仿佛見其亡親謂曰：\"去得也。\"遂辦裝入京，果登朝籍，不爽陰告也。東都柏坡有莊而多高大屋宇，中庭有土堆若冢。人言其下時有樂聲，本主鬻之不售。八座不信，以善价買之，遽令發掘，其下乃麥曲耳。以之和泥涂一院牆屋，不假他求。是知妖由人興，向使疑誤神怪，則有物凭焉，必為村巫酒食之資也。正直之人其可欺乎。","sortOrder":11},
  {"id":"s_work_bmtn_10_12","chapterId":"ch_work_bmtn_10","text":"進士趙中行家於溫州，以豪俠為事。至蘇州，旅止支山禪院。僧戶有一女商荆十三娘，為亡夫設大祥斋，因慕趙，遂同載歸扬州。趙以氣義耗荆之财，殊不介意。其友人李正郎弟三十九愛一妓，為其父母奪與諸葛殷，李怅恨不已。時諸葛殷與呂用之幻惑高太尉，恣行威福，李懼禍，飲泣而憶。偶話於荆娘，荆娘亦憤惋，謂李三十九郎曰：\"此小事，我能為郎報仇，但請過江於润州北固山六月六日正午時待我。\"李亦依之。至期，荆氏以囊盛妓兼致妓之父母首歸於李。後與趙進士同入浙中，不知所止。","sortOrder":12},
  {"id":"s_work_bmtn_10_13","chapterId":"ch_work_bmtn_10","text":"唐李當尚書镇興元，褒城縣有處士陳休复者，號陳七子，狎於博徒，行止非常。八座以其妖誕械之，而市井之間又有一休复。無何，殒於狴牢，遽睹腐败，轄司申而瘞之。爾後宛在褒城，八座驚異，不敢尋問。一旦愛女暴亡，其內子追悼成疾，無以救療。幕客有白八座曰：\"陳處士真道者，必有少君之術，能祈之乎？\"八座然之，因敬信延召。陳生曰：\"此小事爾。\"於初夜帷堂設燈炬，畫作一門，請夫人帘下屏氣。至夜分，亡者自畫門入堂中，行數遭，夫人愊臆，失聲而哭。亡魂倏而滅矣。然後戒勉，令其抑割，八座由是益敬之。","sortOrder":13},
  {"id":"s_work_bmtn_11_1","chapterId":"ch_work_bmtn_11","text":"●卷九","sortOrder":1},
  {"id":"s_work_bmtn_11_2","chapterId":"ch_work_bmtn_11","text":"唐孟弘微郎中誕妄不拘，宣宗朝，因次對曰：\"陛下何以不知有臣不以文字召用？\"上怒曰：\"卿何人斯聯耳全不知有卿。\"翌日，上謂宰臣曰：\"此人躁妄，欲求翰林學士，大容易哉！\"於是宰臣歸中書貶其官，示小懲也。又嘗忿狷，挤其弟落井，外議喧然。乃致書告親友曰：\"懸身井半，風言沸騰。尺水丈波，古今常事。\"與鄭諷鄰居，諷為南海從事，因牆頹，中郎夹入牆界五六尺。知宅者有状，請退其所侵。判其状曰：\"海隅從事，少有生還。地势尖斜，打牆夹入。\"平生操履率皆如是，不遭擯弃，幸矣。","sortOrder":2},
  {"id":"s_work_bmtn_11_3","chapterId":"ch_work_bmtn_11","text":"唐楊相國收貶死嶺外。於時鄭愚尚書镇南海，忽一日，客將報雲：\"楊相公在客次，欲見鄭尚書。\"八座驚駭，以弘農近有後命，安得此來乃接延之。楊相國曰：\"某為軍容使楊玄价所谮，不幸遭害。今已得請於上帝賜陰兵以复仇，欲托尚書宴犒，兼借錢十萬缗。\"滎陽诺之，唯錢辭以軍府事多，許其半。楊相曰：\"非銅錢也。燒時幸勿著地。\"滎陽曰：\"若此則固得遵副。\"從容間長揖而滅。滎陽令於北郊具酒饌素錢以祭之，楊相猶子有典寿陽者，見相國乘白馬，臂朱弓，捻彤矢，有朱衣天吏控馬，謂之曰：\"上帝許我仇殺楊玄价。我射著其腳，必死也。\"俄而楊中尉暴染腳疾而殂。蜀毛文錫司徒先德前潮牧龟范，曾趨事鄭尚書，熟詳其事。愚於毛氏子聞之。","sortOrder":3},
  {"id":"s_work_bmtn_11_4","chapterId":"ch_work_bmtn_11","text":"唐彭城劉山甫，中朝士族也。其先宦於嶺外，侍從北歸，泊船於青草湖。登岸見有北方毗沙門天王，因詣之，見廟宇摧頹，香燈不續。山甫少年而有才思，元隨張處權請郎君詠之，乃題詩曰：\"坏牆風雨幾經春，草色盈庭一座尘。自是神明無感應，盛衰何得却由人。\"是夜夢為天王所责，自雲：\"我非天王，南嶽神也，主張此地，汝何相侮\"俄而驚覺，而風浪斗起，倒樯絕纜，沉溺在即。遽起悔過，令撤詩牌，然後已。山甫自序。","sortOrder":4},
  {"id":"s_work_bmtn_11_5","chapterId":"ch_work_bmtn_11","text":"蜀路白衛嶺多虎豹噬人，有選人京兆韦，唐光化中調授巴南宰，常念《金刚經》。赴任至泥溪，遇一女人，著緋衣，挈二子偕行，同登此山。前路嶺頭行人相駐叫噪，見此女人乃赤大虫也，逡巡與韦分路而去。韦終不覺，蓋持經之力也。成都府廣都縣人陳微自少年常誦《金刚經》，馬胥姓馬者有隙。一旦事故亡匿，馬生扬言欲追捕之。陳乃砺一匕首，行坐相隨，傥遇馬生，必能刺之，誓不受其執錄。或一日，行於村路蓊薈間，與胥伏而掩之，陳抽刀一揮，馬生仰倒，由是獲脱。至前方悟手之所揮乃刀鞘，及歸所匿處，刀刃宛在，本不偕行，馬胥亦無所傷，何其異也！","sortOrder":5},
  {"id":"s_work_bmtn_11_6","chapterId":"ch_work_bmtn_11","text":"唐鹹通中，西川僧法進刺血寫經，聚眾教化寺。所司申報高燕公，判雲：\"斷臂既是凶人，刺血必非善事。貝多葉上不許尘埃，俗子身中豈堪腥腻宜令出境，無得惑人。與一繩遞出東界。\"所司不喻繩絞，賜錢一千送出東郭，幸而誤免。後卒於荆州玉泉寺。","sortOrder":6},
  {"id":"s_work_bmtn_11_7","chapterId":"ch_work_bmtn_11","text":"荆州成令公汭，唐天复中准詔統軍救援江夏，舟楫之盛近代罕聞，已决行期，不聽諫諍。師次公安縣寺，有二金刚神，土人號曰二聖，亦甚有靈。中令舣舟而謁之，炷香虔誠，冥祷勝負，以求杯交陰陽之兆，凡三十掷皆不吉，乃謂所信孔目官楊師厚曰：\"卦之不吉如之何\"師厚對曰：\"今公數年造船，旌旗已啟，中路而退，將何面目回見軍民\"於是不得已而進，竟有破陣之败，身死家破，非偶然也。向使楊子察人之情，幸其意怠，一言而止，則成氏滅亡未可知也。","sortOrder":7},
  {"id":"s_work_bmtn_11_8","chapterId":"ch_work_bmtn_11","text":"唐中和中，有士人蘇昌遠居蘇台屬邑，有小莊去官道十里。吳中水乡，率多荷芰。一日忽見一女郎，素衣紅脸，容质絕麗，閱其明悟若神仙中人，自是與之相狎，以莊為幽會之所。蘇生惑之既甚，嘗以玉環赠之，結系殷勤。或一日見槛前白莲花开，敖榮殊異，俯而玩之，見花房中有物，細视之，乃所赠玉環也，因折之，其妖遂絕。鬼神無形，必凭於物，精氣所附，非菡萏之能哉。聞於劉山甫。","sortOrder":8},
  {"id":"s_work_bmtn_11_9","chapterId":"ch_work_bmtn_11","text":"唐龍紀中，有士人柳鵬舉遊杭州，避雨於伍相廟，見一女子抱五絃，雲是錢大夫家女仆。鵬舉悅之，遂誘而奔藏於舟中，為厢吏所捕，其女仆自縊而死。或一日却到柳處，柳亦知其物故，驚訝其來。女仆具道其情，因以魂偶，經時而去。見劉山甫《閒談》中。","sortOrder":9},
  {"id":"s_work_bmtn_11_10","chapterId":"ch_work_bmtn_11","text":"僖宗幸蜀年，有進士李茵，襄州人，奔竄南山民家，見一宮娥，自雲宮中侍書家雲芳子，有才思，與李同行詣蜀，具述宮中之事，兼曾有詩書紅葉上，流出御溝中，即此姬也。行及綿州，逢內官田大夫識之，乃曰：\"書家何得在此\"逼令上馬與之前去，李甚怏怅，無可奈何。宮娥與李情愛至深，至前驿自縊而死，其魂追及李生，具道憶恋之意。怠數年，李茵病瘠，有道士言其面有邪氣。雲芳子自陳人鬼殊途，告辭而去。聞於劉山甫。","sortOrder":10},
  {"id":"s_work_bmtn_11_11","chapterId":"ch_work_bmtn_11","text":"唐文德中，小京官張寓蘇台，子弟少年時在丈人陆評事院往來，為一美人所悅，來往多時，久而心疑之，尋病瘠，遇开元觀吳道士守元，曰：\"子有不祥之氣。\"授以一符。果一冥器婢子，背書\"紅英\"字，在空舍柱穴中。因焚之，其妖乃絕。聞於劉山甫。","sortOrder":11},
  {"id":"s_work_bmtn_11_12","chapterId":"ch_work_bmtn_11","text":"淮海小將姓朱，有女未嫁，為鬼物所崇，常呼韓郎，往來如生人，唯不見形，奉外舅姑禮，自雲天朝神。朱以異事，不敢隱秘，乃告府主高燕公。公唯書名，俾朱歸帖於女房門上。其邪來見，咨嗟言別而去。聞於劉山甫。","sortOrder":12},
  {"id":"s_work_bmtn_11_13","chapterId":"ch_work_bmtn_11","text":"唐女道魚玄機字蕙蘭，甚有才思。鹹通中，為李憶補闕執箕帚，後愛衰，下山隸鹹宜觀為女道士。有怨李公詩曰：\"易求無价寶，難得有心郎。\"又雲：\"蕙蘭銷歇歸春浦，楊柳東西伴客舟。\"自是縱懷，乃娼婦也，竟以殺侍婢為京兆尹溫璋殺之。有集行於世。江淮間有徐月英，名娼也，其送人詩雲：\"惆怅人間事久违，兩人同去一人歸。生憎平望亭前水，忍照鴛鴦相背飛。\"亦有詩集。金陵徐氏諸公子寵一營妓，卒乃焚之。月英送葬，謂徐公曰：\"此娘平生風流，没亦帶焰。\"時號美戲也。唐末有《北里志》，其間即孫尚書储數賢平康狎遊之事，或雲孫棨舍人所撰。","sortOrder":13},
  {"id":"s_work_bmtn_11_14","chapterId":"ch_work_bmtn_11","text":"唐廣明中，黃巢犯闕，大駕幸蜀，衣冠荡析，寇盜縱橫。有西班李將軍女奔波隨人，迤逦達興元，骨肉分散，無所依托，適值鳳翔奏將軍董司馬者，乃晦其門閥，以身托之。而性甚明敏，善於承奉，得至於蜀，尋訪親眷，知在行朝，始謂董生曰：\"丧亂之中，女弱不能自濟，幸蒙提挈，以至於此。失身之事非不幸也，人各有偶，難為偕老，請自此辭。\"董生驚愕，遂下其山矣。識者謂女子之智亦足稱也。見劉山甫《閒談》。","sortOrder":14},
  {"id":"s_work_bmtn_11_15","chapterId":"ch_work_bmtn_11","text":"唐冯藻，常侍肅之子，涓之叔父。世有科名，小貂文采不高，酷愛名第，已十五舉，有相識道士謂曰：\"先辈某曾入靜觀之，此生無名第，但有官職也。\"亦未之信，更應十舉，已二十五舉矣，姻親勸令罢舉，且謀官職。藻曰：\"譬如一生無成。\"更誓五舉，亦無成，遂三十舉方就仕，歷官卿監峡牧，終於騎省。何浮名之引人而輕祿仕之如是也！","sortOrder":15},
  {"id":"s_work_bmtn_11_16","chapterId":"ch_work_bmtn_11","text":"唐李涪尚書，福相之子，以《开元禮》及第，亦為小文，好著述。朝廷重其博學，禮樂之事谘禀之，時人號為\"周禮库\"，蓋籍於舊典也。廣明以前，《切韻》多用吳音，而清青之字不必分用。涪改《切韻》，全刊吳音。當方進而聞於宰相，佥許之。無何，巢寇犯闕，因而寢止，於今無人敢以聲韻措懷也。然曾見《韻铨》，鄙驳《切韻》，改正吳音，亦甚核當，不知八座於此又何規製也，惜哉！古之製字卷紙題名姓，號曰名紙。大中年，薛保遜為舉場頭角，人皆體效，方作門状。洎後仍以所懷列於啟事，隨啟詣公相門，號為門状、門啟。雖繁於名紙，各便於時也。書雲\"謹祗候起居郎某官\"，即是起居在前，某官在後。至今顛倒，無人改更矣。有朝廷改之，亦美事也。","sortOrder":16},
  {"id":"s_work_bmtn_11_17","chapterId":"ch_work_bmtn_11","text":"唐監察李航，福相之子，美茂洽畅，播於時流。黃巢後，扶侍聖善歸東都別墅，與御史穆延晦同行，宿於虢州公馆。翌日修謁郡牧張存，即王珙下部將也，謂典客曰：\"我受穆家恩命。今穆侍御經過，必須展分報答也。\"典客詣馆話於穆生。因修状謁謝，張公大怒，且曰：\"此言得自何人\"具以典謁為對。乃斬謁者。穆生驚怪，失意歸馆。尋遣人就而害之。李監察不喻，方抱忧惶，俄亦遇害，將以滅口。於時李公繞聖善所憩之床，無以求活，竟同非命。他日兄弟訴冤，夢航謂骨肉間曰：\"張存已得請於上帝，不日即死。\"果為珙所誅。葆光子嘗讀李肇《國史補》曰：\"李公沂曾放死囚，他日道次遇之，其人感恩，延歸其家，與妻議所酬之物。妻嫌數少，此人曰：'酬物少，不如殺之。'李公急走，遇俠士方免此禍。\"常以為虛誕，今張存翻害穆、李，即《史補》之說，信非虛誕也，怪哉！","sortOrder":17},
  {"id":"s_work_bmtn_11_18","chapterId":"ch_work_bmtn_11","text":"唐王祝給事，名家子，以刚鯁自任，仍以所尚垂訓子孫，嫌人柔弱。又素有物力，殖利極丰。黃寇前嘗典常州，京國亂離，盤旋江湖，甚有時望。急詔征回，歸裝極厚，水陆分載。行至甘棠，王珙帥於是邦，不式王命，凶暴眾聞，以夕拜將來，必居廊廟，延奉勤至。夕拜鄙其武人，殊不降接。珙乃於內廳盛張宴席，備列珍玩，帘下妓樂齊列，其內子亦映帘共拱立。乃斂容向夕拜曰：\"某雖武夫，叨忝旄鉞。今日多幸，獲遇軒蓋經過。苟不弃末宗，願居子侄之列，即榮幸也。\"夕拜不允，堅抗再三。珙勃然作色曰：\"給事王程有限，不敢淹留。\"俄而罢宴，處分兩轄速請王給事離馆，暗授意旨，併令害之，一家上下悉投黃河，獲其囊三四百籠，以舟行没溺聞奏。朝廷多故，舍而不問。夕拜有一子，此际行至襄州，亦無故投井而卒。雖陝帥狂暴，亦未喻天意也。葆光子曰：\"刚有立事，時有用舍。以柔濟刚，不爽權变。當衰亂之世，須適時之宜。王公傥受其致敬，庸何傷哉但却其賂即善也。履尾滅族，悲夫！\"","sortOrder":18},
  {"id":"s_work_bmtn_11_19","chapterId":"ch_work_bmtn_11","text":"唐楊收、段文昌皆以孤進貴為宰相，率愛奢侈。楊相女適裴坦長子，嫁資丰厚，什器多用金銀。坦尚俭，聞之不樂。一日，與國號及兒女辈到新婦院，台上用碟盛果實。坦欣然，视碟子內乃臥魚犀，坦盛怒遽推倒茶台，拂袖而出，乃曰：\"破我家也。\"他日收相果以納賂竟至不令，宜哉。","sortOrder":19},
  {"id":"s_work_bmtn_11_20","chapterId":"ch_work_bmtn_11","text":"盧氏衣冠第一，歷代未嘗知舉。乾符中，盧携在中書，歉宗人無掌文柄，乃擢群從陝虢觀察使盧渥知禮闈。是歲十二月，黃巢犯闕，僖皇播遷，舉子星散。迨收复京都，裴贽連知三舉。渥有羨色，趙崇大夫戲之曰：\"閣下所謂出腹不生養主司也。\"","sortOrder":20},
  {"id":"s_work_bmtn_11_21","chapterId":"ch_work_bmtn_11","text":"唐相國張濬二子，一曰義師，即小字也，本名格，為蜀相。一曰興師，後號李將軍，名俨，與父達軍機於淮海，亦遇害也。格與興師，崑弟俊邁，而尚矯譎，皆有父風。興師幼年出宅門，見其門僧，傳相國處分，七笞之。其僧解後莫知何罪。俄而相國召僧，坐安，見其詞色不怿，因問之，僧以郎君傳相國處分見怪，未知罪名。相國驚駭慚謝，以兒子狂駭，幸師慈悲。回至堂前，唤興師怒责之，且曰：\"汝見僧何罪而敢造次\"對曰：\"今日雖無罪過，想其向來隱惡不少，是以笞之。\"相國不覺失笑。","sortOrder":21},
  {"id":"s_work_bmtn_12_1","chapterId":"ch_work_bmtn_12","text":"●卷十","sortOrder":1},
  {"id":"s_work_bmtn_12_2","chapterId":"ch_work_bmtn_12","text":"唐狄歸昌右丞愛與僧遊，每誦前辈詩雲：\"因過竹院逢僧話，略得浮生半日閒。\"其有服紫袈裟者乃疏之。鄭穀郎中亦愛僧，用比蜀茶，乃曰：\"蜀茶與僧未必皆美，不欲舍之。\"僧鸞有逸才而不拘檢，早歲稱卿御，謁薛氏能尚書於嘉州。八座以其顛率，難為舉子，乃俾出家。自於百尺大像前披剃，不肯師於常僧也。後入京為文章供奉，賜紫，柳玭大夫甚愛其才，租庸張相亦曾加敬，盛言其可大用。由是反初，號鮮於鳳，修刺謁柳公，公鄙之不接。又謁張相，張相亦拒之。於是失望而為李鋋江西判官，後為西班小將軍，竟於黃州遇害。","sortOrder":2},
  {"id":"s_work_bmtn_12_3","chapterId":"ch_work_bmtn_12","text":"唐乾寧中，宿州刺史陳璠以軍旅出身擅行威斷。進士張翱恃才傲物，席上調璠寵妓張小泰。怒而揖起，付吏责其無禮。状雲：\"有張翱兮寓止淮陰，來綺席兮放恣胸襟。\"璠益怒，雲：\"據此分析，合吃幾下\"翱雲：\"只此兩句，合吃乎三下五下；切求一笑，宜費乎千金萬金。\"金鞭响背十三長逝。惜其恃才而取禍也。出劉山甫《閒談》，詞多不載。蜀綿州刺史李，，時號嗑咀，以軍功致郡符，好賓客。有酒徒李堅白者，粗有文筆。李侯謂曰：\"足下何以名為堅白\"對曰：\"莫要改為士元，亮君雄是權耶\"又有蒋貽恭者，好嘲詠，頻以此痛遭檟楚，竟不能改。蜀中士子好著襪頭褲，蒋謂之曰：\"仁賢既裹將仕郎頭，為何作散子將腳\"他皆類此。","sortOrder":3},
  {"id":"s_work_bmtn_12_4","chapterId":"ch_work_bmtn_12","text":"唐劉瞻相公有清德大名，與弟阿初皆得道，已入仙傳。先婚李氏，生一子，即劉贊也。相國薨後，贊且孤幼，性甚懵钝。教其讀書，終不記憶。其舅即李殷衡侍郎也，以劉氏之門不可無後，常加楚箠，終不長進。李夫人慈念，不忍苦之，叹其宿分也。一旦不告他適，無以訪尋，聖善憶念，淚如绠縻，莫審其存亡。數年方歸，子母团聚，且曰\"因入嵩山，遇一白衣叟，謂曰：'與汝开心，將來必保聰明。'\"自是日誦一卷，兼有文藻，擢進士第。梁時登朝充崇政院學士，預時俊之流。其渭陽李侍郎充使番禺，為越王劉氏所縻，為廣相而薨。仆與劉贊猶子慤通熟，自言家世合有一人得道矣，即白衣叟其仿佛乎。","sortOrder":4},
  {"id":"s_work_bmtn_12_5","chapterId":"ch_work_bmtn_12","text":"唐盛唐縣令李鵬遇桑道茂，曰：\"長官只此一邑而已。賢郎二人，大者位極人臣，次者殆於數镇，子孫百氏。\"後如其言。長男名石，出將入相，子孫兩世及第，至今無間。次即讳福扬歷七镇，終於使相，凡八男，三人及第至尚書、給諫、郡牧，見有諸孫皆朱紫，不墜士風。何先見之妙如是。","sortOrder":5},
  {"id":"s_work_bmtn_12_6","chapterId":"ch_work_bmtn_12","text":"唐孔拯侍郎作遺補時，朝回遇雨，不赍油衣，乃避雨於坊叟之庑下。滂註愈甚，已過食時，民家意其朝飢，延入廳事。俄有一叟，乌帽紗巾而出，迎候甚恭。因備酒饌，一一精珍，乃公侯家不若也。孔公慚謝之，且借油衣。叟曰：\"某寒不出，熱不出，風不出，雨不出，未嘗置油衣，然已令鋪上取去，可以供借也。\"孔公賞羨，不覺頓忘宦情。他日說於僚友，為大隱之美也。古之富者擬於封君，《洪范》\"五福\"一曰富。先賢以無事當貴，豈斯人之徒耶。复有一丞郎，馬上內逼，急詣一空宅，迳登溷軒，斯乃大優穆刀綾空屋也。優忽至，丞郎慚謝之。優曰：\"侍郎他日內逼，但請光訪。\"人聞之，莫不絕倒。","sortOrder":6},
  {"id":"s_work_bmtn_12_7","chapterId":"ch_work_bmtn_12","text":"唐裴晉公度風貌不扬，自譔真贊雲：\"爾身不長，爾貌不扬。胡為而將胡為而相\"幕下從事遜以美之，且曰：\"明公以內相為優。\"公笑曰：\"諸賢好信謙也。\"幕僚皆悚而退。李洸者，渤海人，崑仲皆有文章。洸因旅次至江村，宿於民家，見覆斗上安錫佛一軀，洸诡詞以贊之。民曰：\"偶未慶贊，為去僧院地遠爾。\"洸曰：\"何必須僧，只我而已。\"民信之，明發隨分具斋餐炷香虔誠。洸俯仰朗稱曰：\"錫鑞佛子，柔软世尊。斗上莊嚴，為有十升功德。\"念《摩诃波若波羅密》。又趙璘員外為裴坦相漢南從事。璘甚陋，裴公戲之曰：\"趙公本不丑，孩抱時乳母怜惜，往往撫弄雲'作丑子，作丑子'，因此一定。\"趙公大咍。薛侍郎昭緯氣貌昏濁，杜紫微唇厚，溫庭筠號溫种馗，不稱才名也。薛侍郎未登第前就肆買鞋，鞋主曰：\"秀士腳第幾\"對曰：\"與昭緯作腳來，未曾與立行第也。\"杜德樣侍郎崑弟力困，要舉息利錢濟急用，召同坊富民到宅，且問曰：\"子本對是幾錢\"其人拂袖而出。又孔昭緯拜官，教坊優伶繼至，各求利市。石野猪獨先行到，公有所賜，謂曰：\"宅中甚闕，不得厚致。若有諸野猪，幸勿言也。\"复有一伶繼來，公索其笛，唤近階，指笛竅問之曰：\"何者是《浣溪紗》孔子？\"伶大笑之。又道士陳子霄登華山上方，偶有顛仆，宇文翰郎中致書戲之曰：\"不知上得不得，且怪玄之又玄。\"斯皆清雅戲，以之群居，又何傷也。","sortOrder":7},
  {"id":"s_work_bmtn_12_8","chapterId":"ch_work_bmtn_12","text":"唐溫璋為京兆尹，勇於殺戮，京邑憚之。一日，聞挽鈴聲，俾看架下，不見有人。凡三度挽掣，乃見鴉一只。尹曰：\"是必有人探其雏而訴冤也。\"命吏隨鴉所在捕之。其鴉盤旋引吏至城外树間，果有人探其雏，尚憩树下。吏乃執之送府。以禽鳥訴冤，事異於常，乃毙捕雏者而報之。","sortOrder":8},
  {"id":"s_work_bmtn_12_9","chapterId":"ch_work_bmtn_12","text":"唐僖宗朝，翰林待詔滑能棋品甚高，少逢敵手。有一張小子，年可十四，來謁觅棋，請饒一路。滑生棋思甚遲，沉吟良久，方下一子。張生隨手應之，都不介意，仍於庭际取適，候滑生更下，又隨手著應之。一旦黃寇犯闕，僖宗幸蜀，滑以待詔供職，謀赴行在，欲取金州路入。辦裝挈家將行，張生曰：\"不必前邁，某非棋客，天帝命我取公著棋，請指揮家事。\"滑生驚愕，妻子啜泣，奄然而逝。他日京都共知也。昔顏回、卜商為地下修文郎，又李長吉為帝召撰樂府，豈斯類耶。所言天帝者，非北極天皇大帝也，按《真誥》，又非北方玄天黑帝道君。此鬼都北帝，又號鬼帝。世人有大功德者，北帝得以辟請，四明公之流是也。召棋之命，乃酆宮帝君乎，與《真誥》仿佛，故梗概而言之。","sortOrder":9},
  {"id":"s_work_bmtn_12_10","chapterId":"ch_work_bmtn_12","text":"医者，意也，古人有不因切脈隨知病源者必愈之矣。唐崔魏公铉镇渚宮，有富商船居，中夜暴亡，迨晓氣猶未絕。鄰房有武陵医士梁新聞之，乃與诊视，曰：\"此乃食毒也，三兩日得非外食耶\"仆夫曰：\"主公少出船，亦不食於他人。\"梁新曰：\"尋常嗜食何物\"仆夫曰：\"好食竹雞，每年不下數百只，近買竹雞併將充饌。\"梁新曰：\"竹雞吃半夏，必是半夏毒也。\"命捣薑捩汁，折齒而灌之，由是方蘇。崔魏公聞而異之，召到衙安慰稱奖，資以仆馬錢帛，入京致書朝士，聲名大振，仕至尚医奉御。有一朝士詣之，梁奉御曰：\"何不早見示風疾已深矣，請速歸處置家事，委順而已。\"朝士聞而惶遽告退，策馬而歸。時有鄜州馬医趙鄂者，新到京都，於通衢自榜姓名雲\"攻医術士\"。此朝士下馬告之，趙鄂亦言疾已危，與梁生所說同矣，謂曰：\"只有一法，請官人剩吃消梨，不限多少，咀齕不及，捩汁而飲，或希萬一。\"此朝士又策馬歸，以書筒质消梨，馬上旋齕到家，旬日唯吃消梨，頓覺爽朗，其恙不作。却訪趙生感謝，又訪梁奉御，具言得趙生教也。梁公驚異，且曰：\"大國必有一人相繼者。\"遂召趙生，資以仆馬錢帛，廣為延譽，官至太仆卿。","sortOrder":10},
  {"id":"s_work_bmtn_12_11","chapterId":"ch_work_bmtn_12","text":"元颃博士話唐時中表間有一婦人，從夫南中效官，曾誤食一虫，常疑之，由是成疾，頻療不愈。京城医者知其所患，乃請主人姨奶中謹密者一人預戒之曰：\"今以藥吐泻，但以盤盂盛之。當吐之時，但言有一小虾蟆走去，然切勿令娘子知之，是誑語也。\"其奶仆遵之，此疾永除。又說有一少年眼中常見一小鏡子，医工趙卿诊之，與少年期來晨以魚脍奉候。少年及期赴之，延於閣子內，且令從容，俟客退後方得攀接。俄而設台子，止施一甌芥醋，更無他味。卿亦未出。迨禺中久候不至，少年飢甚，且聞醋香，不免輕啜之，逡巡又啜之，覺胸中豁然，眼花不見，因竭甌啜之。趙卿探知方出，少年以啜醋慚謝，卿曰：\"郎君先因吃鱠太多，非醬醋不快。又有魚鱗在胸中，所以眼花。適來所備醬醋，只欲郎君因飢以啜之，果愈此疾。烹鮮之會乃權誑也，請退謀餐。\"他妙多斯類，非庸医所及也。凡欲以仓、扁之術求食者，得不勉之哉","sortOrder":11},
  {"id":"s_work_bmtn_12_12","chapterId":"ch_work_bmtn_12","text":"唐時杜彦林為朝官，一日馬驚蹶倒，踏鐙既深，抽腳不出，為馬拖行，一步一踏，以至於卒。古人雲：\"乘船走馬，去死一分。\"是知跨御常宜介意也。杜相審權弟延美亦登朝序，乘馬入門，為門楣所軋，項頸低曲，伸ㄕ前引，肩高於顶，乃一生之疾也。荆州文獻王好馬，不惜千金，没世不遇。周先帝命內臣李廷玉賜馬與南平王，且問所好何馬，乃曰：\"良馬千萬無一，若駿者即可得而選。苟要坐下坦穩，免勞控製，唯騸庶幾也。既免蹄嚙，不假衔枚，兩軍列陣，萬騎如一。苟未經騸，亂氣狡憤，介胄在身，與馬爭力，罄控不暇，安能左旋右軸，舍辔揮兵乎？\"自是江南蜀馬往往學騸，甚便乘跨。是知蹀躞者夸於目，馴柔者便於身。此君子之難逢，假翦剔者抑其次也哉。","sortOrder":12},
  {"id":"s_work_bmtn_12_13","chapterId":"ch_work_bmtn_12","text":"唐崔枢為小朝官，家人於井中汲得一魚。枢本好鮮食，意是厨人治魚誤落井中，乃令烹而啖之。忽夢為冥官領過，讀判雲：\"人間小臣辄食龍子，所有官爵併削除。\"後一年卒。枢甚有聲，不跻顯位，誤有所食，豈命也夫。","sortOrder":13},
  {"id":"s_work_bmtn_12_14","chapterId":"ch_work_bmtn_12","text":"唐薛准官至員外郎，丧亂後不養繼母。盤桓江淮間道門寄榻。遊江南，至吉州閤皂觀遇修黃籙斋道士升壇行法事，准亦就列，忽失聲痛叫，雲\"中箭\"，速請筆砚，口占一詩曰：\"蓋國深恩不易仇，又離繼母出他州。誰知天怒無因息，積惡終身乞命休。\"頃便卒。天复辛酉年事，斯人也必有隱慝而致陰誅。古者史籍皆以至孝繼母聞於列傳，蓋以常人難行而巳，能行即親母可知也，豈可以繼母而同行路哉薛死仓卒，可用垂戒也。","sortOrder":14},
  {"id":"s_work_bmtn_12_15","chapterId":"ch_work_bmtn_12","text":"唐鹹通中，庞勋反於徐州。時崔雍典和州，為勋所陷，執到彭門。雍善談笑，遜詞以從之，冀纾其禍。勋亦見待甚厚。其子少俊，飲博击拂，自得親近，更無阻猜。雍以失節於賊，以門戶為忧，謂其子曰：\"汝善狎之，或得方便，能倳刃乎？人皆有死，但得其所，吾复何恨。\"其子承命，密懷利刃，忽色变身戰。勋疑訝，因搜懷袖，得匕首焉，乃令烹之。翌日，召雍赴飲。既彻，問雍曰：\"肉美乎？\"對曰：\"以味珍且飽。\"勋曰：\"此即賢郎肉也。\"亦命殺之。後黃巢入廣州，執節度使李佋，隨軍至荆州，令佋章表述其所懷。佋曰：\"某骨肉滿朝，世受國恩，腕即可斷，表終不為。\"尋於江津害之。唐末蘇循尚書諂媚苟且，梁太祖鄙之。他日至併門謁晉王，時張承業方以匡复為意，而循忽獻晉王畫敕筆一對，承業愈鄙薄之。與夫雍、佋為人，视蘇循誠遠矣。","sortOrder":15},
  {"id":"s_work_bmtn_12_16","chapterId":"ch_work_bmtn_12","text":"王迪舍人早負才業，未卜騫翔。一日謁宰相杜太尉於宅門十字通衢。街路稍狹，有二牛車東西交至，迪馬夹在其間。馬驚，仆而臥，為車轍輾靴鼻逾寸而不傷腳指，三日後入拜翰林。雖幸而免，亦神助也。","sortOrder":16},
  {"id":"s_work_bmtn_12_17","chapterId":"ch_work_bmtn_12","text":"唐韓文公愈之甥有种花之異，聞於小說。杜給事孺休典湖州，有染戶家池生青莲花。刺史收莲子，歸京种於池沼，或变為紅莲，因異，驿致書問染工。曰：\"我家有三世治靛瓮，常以莲子浸於瓮底，俟經歲年然後种之。若以所种青莲花子為种，即為紅矣。蓋還本质，又何足怪。\"乃以所浸莲子寄奉之。道士田匡圖親看此花，為愚話之。愚見今以雞粪和土培芍藥花丛，其淡紅者悉成深紅，染者所言益信矣哉。蜀王先主將晏駕，其年峨嵋山娑羅花悉开白花。又荆州文獻王未薨前數年，溝港城隍悉开白莲花。一則染以氣類，一則表於凶兆，斯又何哉","sortOrder":17},
  {"id":"s_work_bmtn_12_18","chapterId":"ch_work_bmtn_12","text":"唐左軍容使嚴遵美，於閹宦中仁人也，自言北司為供奉官，褲衫給事，無秉簡入侍之儀，又雲：\"枢密使廨署三間屋書櫃而已，亦無视事廳堂。状後貼黃，指揮公事，乃是楊复恭奪宰相權也。\"自是常思退休。一旦發狂，手足舞蹈，家人鹹訝。傍有一猫一犬，猫謂犬曰：\"軍容改常也，顛發也。\"犬曰：\"莫管他，從他。\"俄而舞定，自驚自笑，且異猫犬之言。遇昭宗播遷鳳翔，乃求致仕梁川。蜀軍收降興元，因徙於劍南，依王先主，優待甚異。於青城山下卜別墅以居之，年過八十而終。其忠正謙約，與西門季玄為季孟也。於時誅宦官，唯西川不奉詔，由是脱禍。家有《北司治亂記》八卷，備載閹宦忠佞好惡，嘗聞此傳，偶未得見。即巷伯之流未必俱邪，良由南班輕忌太過，以致參商。蓋邦國之不幸也。先是路巖相自成都移镇渚宮，所乘馬忽作人語，且曰：\"庐荻花，此花开後路無家。\"不久及禍。然畜類之語，豈有物凭之乎石言於晉殆斯比也。","sortOrder":18},
  {"id":"s_work_bmtn_12_19","chapterId":"ch_work_bmtn_12","text":"唐崇賢窦公家罕有名第，璟仆射先人，不善治生，事力甚困。京城內有隙地一段，與大閹相鄰。閹貴欲之，然其地止值五六百千而已。窦公欣然以此地奉之，殊不言地价，乃曰：\"將軍所便，不敢奉违。某有故欲往江淮上，希三兩處護戎緘題。\"其閹喜而致書，凡獲三千缗，由是幸濟。東市有隙地一片，窪下渟污。乃以廉值市之，俾奶嫗將煎餅盤就彼誘兒童，若抛砖瓦中一紙標，得一个餅。兒童奔走抛砖瓦博煎餅，不久十分填其六七，乃以好土填之，起一店停波斯，日獲一缗。他皆效此，由是致富，延客朝士，時皆謂之輕薄，號為酒炙地。亦能為人求名第，酒食聚人，亦希利之一端也。窦回、窦雍，無文藝而取名，蓋飲啖之力也，得於元中凡數賢。《御史台記》說裴明禮買宅事，與窦氏同，疑窦效裴之為也。","sortOrder":19},
  {"id":"s_work_bmtn_12_20","chapterId":"ch_work_bmtn_12","text":"唐鹹通中，前進士李昌符有詩名，久不登第。常歲卷軸，怠於裝脩，因出一奇，乃作《婢仆詩》五十首，於公卿間行之。有詩雲：\"春娘愛上酒家樓，不怕歸遲總不留。推道那家娘子臥，且留教住待梳頭。\"又雲：\"不論秋菊與春花，个个能噇空肚茶。無事莫教頻入库，一名閒物要些些。\"諸篇皆中婢仆之讳。浃旬京城盛傳其詩篇，為奶嫗辈怪骂騰沸，盡要摑其面。是年登第。與夫桃杖虎靴事雖不同，用奇即無異也。","sortOrder":20},
  {"id":"s_work_bmtn_12_21","chapterId":"ch_work_bmtn_12","text":"唐廣南節度使下元隨軍將鐘大夫晚年流落旅寓陵州，多止佛寺。有仁寿縣主簿欧陽ぅ愍其衰老，常延待之。三伏間患腹疾，臥於欧陽之家，逾月不食。欧主簿慮其旦夕溘然，欲陳牒州衙，希取鐘公一状以明行止。鐘公曰：\"病即病矣，死即未也。既此奉煩，何妨申報。\"於是聞於官中。爾後疾愈。葆光子時為郡卒，鐘公惠然來訪。因問所苦之由，乃曰：\"曾在湘潭遇幹戈不進，與同行商人數辈就嶽麓寺設斋。寺僧有新合知命丹者，且雲服此藥後要退即飲海藻湯。或大期將至，即肋下微痛，此丹自下，便須指揮家事以俟終焉。遂各奉一缗吞一丸。他日入蜀，至樂溫縣，遇同服丹者商人寄寓樂溫，得與話舊。且說所服之藥大效。無何，此公來報肋下痛，不日其藥果下。急區分家事，後凡二十日卒。某方神其藥，用海藻湯下之，香水沐浴，却吞之。昨來所苦，藥且未下，所以知未死。\"兼出藥相示。然鐘公面色紅润，強飲啖，似得藥力也。他日不知其所終，以其知命丹有验，故記之。","sortOrder":21},
  {"id":"s_work_bmtn_13_1","chapterId":"ch_work_bmtn_13","text":"●卷十一","sortOrder":1},
  {"id":"s_work_bmtn_13_2","chapterId":"ch_work_bmtn_13","text":"唐金吾大將軍張直方，西班倜傥勋臣也，好接賓客，歌妓絲竹甲於他族，與裴相國休相對。相國始麻衣就试，執金慕其風采。裴因造謁，執金款待異禮。他日朝中盛稱裴秀才文藝，朝賢訝之，相國恐涉雜交，不遑安處，自是不敢更歷其門。執金頻召不往。或曰：\"裴秀才方謀進取，慮致物譽，非是偃蹇。\"一日又召，傳語曰：\"若不防及，即更奉荐。\"裴益悚惕。","sortOrder":2},
  {"id":"s_work_bmtn_13_3","chapterId":"ch_work_bmtn_13","text":"唐薛昭緯侍郎，恃才與地，鄰於傲物，常以宰辅自許，切於大拜。於時梁太祖已兼四镇，兵力漸大，有問鼎之心，速於傳禪。薛公衔命梁國。梁祖令客將約回。乃謂竭者曰：\"大君有命，無容却回。\"速辔前邁，既至夷門，梁祖不獲已而出迎接，見薛公標韻詞辯，方始改觀，自是宴接莫不款曲。一日，梁祖話及鷹鷂，薛公秪對，盛言鷙鳥之俊。梁祖欣然，謂其亦曾放弄。歸馆後傳語送鷂子一頭，薛生致書感謝，仍對來人戒僮仆曰：\"令公所賜，真須愛惜，可以紙裹安鞲袋中。\"來人失笑，聞於使衙。","sortOrder":3},
  {"id":"s_work_bmtn_13_4","chapterId":"ch_work_bmtn_13","text":"唐進士崔昭矩為状元，有進士团所由動靜舉罰。一日，所由疏失，状元笞之，逡巡，所由謝伏，於階前對諸進士曰：\"崔十五郎不合於同年前面瞋决所由，請罰若幹。\"博陵無言以對。","sortOrder":4},
  {"id":"s_work_bmtn_13_5","chapterId":"ch_work_bmtn_13","text":"唐崔亚郎中典眉州，程贺以乡役差充廳子，其弟在州曾為小書吏。崔公見贺風味有似儒生，因詰之曰：\"爾讀書乎？\"贺降階對曰：\"薄涉藝文。\"崔公指一物俾其賦詠，雅有意思。處分令歸。選日，裝寫所業執贽，甚稱奖之，俾稱進士，依崔之門，更無他岐。凡二十五舉及第。每入京，馆於博陵之第，常感提拔之恩。亚卒之日，贺為崔公縗服三年，人皆美之。","sortOrder":5},
  {"id":"s_work_bmtn_13_6","chapterId":"ch_work_bmtn_13","text":"唐南蠻侵軼西川，苦無章障。自鹹通已後劍南苦之，牛丛尚書作镇，為蠻寇凭陵，無以抗拒。高公自東平移镇成都，蠻酋猶扰蜀城。掌武先選驍銳救急，人背神符一道。蠻觇知之，望風而遁。爾後僖宗幸蜀，深疑作梗，乃許降公主。蠻王以連姻大國，喜幸逾常，因命宰相趙隆眉、楊奇鯤、段義宗來朝行在，且迎公主。高太尉自淮海飛章雲：\"南蠻心膂唯此數人，請止而鸩之。\"迄僖宗還京，南方無虞，用高公之策也。楊奇鯤辈皆有詞藻，途中詩雲：\"風里浪花吹又白，雨中岚色洗還青。江鷗聚處窗前見，林狖啼時枕上聽。此际自然無限趣，王程不敢暫留停。\"詞甚清美也。","sortOrder":6},
  {"id":"s_work_bmtn_13_7","chapterId":"ch_work_bmtn_13","text":"唐相國夏侯公孜富貴後得彭素之術，甚有所益。出镇蒲中，悅一娼妓，不能承奉，以致尾闾之泄，因而致卒。有夏侯長官者，本反初僧也，曾依相國門庭，亂離後挈家寄於鳳州山穀，尋亦物故，惟寡妻幼子而已。夏嫗獻此術於節使滿存，相公大獲濡濟。其子名籍，學吟詩，入西川依托勋臣為幕下從事，時人號為夏侯驢子，乃世濟其鄙猥也。仆聞之於強山人甚詳，亦嘗與籍相識。籍子婿羅峤與仆相知，亦多蓄姬妾，疑其染夏氏之風。然夏侯長官者得非相國之師乎。","sortOrder":7},
  {"id":"s_work_bmtn_13_8","chapterId":"ch_work_bmtn_13","text":"唐金吾大將軍張直方一旦开筵，命朝士看乾水銀，點製不谬。眾皆叹羨，以謂清河曾遇至人。良久，張公大笑曰：\"己非所能，有自來矣。頃任桂府团練使，逢一道士蘊此利術，就而求之，終不可得。乃令健卒縛於山中，以死胁之。道士驚怕，但言藥即多獻，術則不傳，唯死而已。由是得藥，縱其他適。今日奉呈唯成丹也，非己能也。\"","sortOrder":8},
  {"id":"s_work_bmtn_13_9","chapterId":"ch_work_bmtn_13","text":"唐高骈镇成都，甚好方術。有處士蔡畋者，以黃白幹之，取瓦一片，研丹一粒，半涂入火，燒成半截紫磨金，乃奇事也。蔡生自負，人皆敬之，以為地仙。燕公求之不得，久而乖露，乃是得藥於人，眩惑賣弄，為元戎笞殺之。王先主時有何法成者，小人也，以賣符藥為業。其妻微有容色，居在北禪院。侧左院有毳衲者，因與法成相識，出入其家，令賣藥銀，就其家飲啖而已。法成以其內子餌之而求其法，此僧秘惜，遷延未傳。乃令其妻冶容而接之，法成自外還家，掩縛欲報巡吏。此僧驚懼，因谬授其法，併成藥數兩。釋縛而竄。法成聞此術以致發狂，大言於人，夸解利術，未久聞於蜀。後主召入苑中，與補軍職。然不盡僧法，他日藥盡，遽屬更变，伶俜而已，偶免谬妄之誅也。彭韜光者，與何生切鄰，兼得其事，為餘話之。","sortOrder":9},
  {"id":"s_work_bmtn_13_10","chapterId":"ch_work_bmtn_13","text":"高骈镇維扬，有申屠別駕懷至術，為呂用之谮毀，一旦作竄。燕公命吏赍長限牒所在尋捕，至襄州禪院中遇之，擒得申生，寄襄獄縶維。申生告獄吏要見督郵韦公，吏以告之。韦遽面見，屏人曰：\"某身上有化金藥欲獻元戎劉公巨容，可乎？\"韦審之，遂非時入謁，因得道達，點甎瓦半葉以呈之。劉公叹訝，乃虛以叛獄而匿之。僖皇在蜀，降天使至峴山，即田令孜弟也。劉公乘醉將藥金夸衒於中使，中使回，聞於田中尉。洎劉司空朝觐行在，與申生偕往，藏隱此人，不令他適。田軍容衔之，於导江莊加害，劉、申皆不幸也。有一子號申司馬，居朗州，尚存點汞藥在身。荆南節判司空董太監得申生四粒藥，點四汞，奉一百千，以慰好奇之心也。","sortOrder":10},
  {"id":"s_work_bmtn_13_11","chapterId":"ch_work_bmtn_13","text":"唐世長安有宗小子者解黃白術，唯在平康狎遊，與西川節度使陳敬瑄微時遊處，因色失歡。他日陳公遭遇，出镇成都，京國亂離，僖皇幸蜀，宗生避地，亦到錦江。然畏潁川知之，遂旅遊資中郡，銷聲斂跡，惟恐人知。寓應真觀，修一爐大丹未竟。宗生解六壬，每旦運式，看一日吉凶。無何，失聲便謀他適，走至內江縣。潁川差人吏就所在害之，所修藥道士收得，傳致數家，皆不利人，莫知何也。","sortOrder":11},
  {"id":"s_work_bmtn_13_12","chapterId":"ch_work_bmtn_13","text":"唐李璧尚書出镇東川，有律僧臨壇度人，四方受具者奔走師仰，檀施雲集，由是鞅掌嗜欲之心炽焉。一旦發露，前後女童為尼者呈身之物殆一百四十五人，八座戮之。葆光子嘗見同僚王行軍說幽州有壇長，近八十歲，即都校之元崑也。每歸俗家，以其衰老，令小青扶侍，因而及亂，遂要反初，以青為偶，乃謂偶曰：\"平生不謂有此歡畅，悔知之晚也。\"軍府怪而笑之。仆有門徒僧，不欲斥其名。經論甚博，未有乖露，他日預臨壇之列，尼辈參請，號曰依止。自是丑聲盈耳，亦不以為恥。呜呼，如來製戒為入道之門，苟非其人，反為聚淫丛藪。信乎道不虛行也！","sortOrder":12},
  {"id":"s_work_bmtn_13_13","chapterId":"ch_work_bmtn_13","text":"唐崔元亮曾典眉州，每公退，具簡履以朝太上，焚脩精至，不舍晝夜。嘗於州衙开黃籙道場，為民祈水旱疾疫而已。散斋之晨必降祥雲鸞鶴，州民鹹睹。至今眉州每歲設黃籙斋，凡執事軍校及茶酒厮役祗承皆知斋法次第。道士羅昭然寿一百一十三歲，預崔牧之斋席，跨驢出街，墜驢而腳在鐙內，因拖曳而死也。又王蜀時，玉局觀道士趙駕仙、上官道士住青城山，修斋入壇行法事，其厮仆臥而驚魇，問師何在。人問之，乃曰：\"適見四人著緋自天而下，曳二道士於壇前鞭背二十。\"問者止之，令勿言。比趙駕仙與上官道士相次患發背而毙。又有何景冲作道門威儀，好食蒜，上壇行法事，時有蒜氣。後於青城修斋，度江，船覆溺死。斯蓋罔道不恭，為天罰也。成中令镇荆南，請道士梁威儀行法事，俯伏奏章，頓首存想，因之不起，乃醉睡也。成公斥之，毀废道場。斯亦何、趙之流也。大約荆湘僧道赴斋皆恣洪飲，俚人不以為非，欲求降鑒，安可得也","sortOrder":13},
  {"id":"s_work_bmtn_13_14","chapterId":"ch_work_bmtn_13","text":"唐鹹通亂離後，坊巷訛言關三郎鬼兵入城，家家恐悚，罹其患者令人寒熱戰栗，亦無大苦。弘農楊玭挈家自骆穀路入洋源，行及秦嶺，回望京師，乃曰：\"此處應免關三郎相隨也。\"語未終，一時股栗，斯又何哉夫丧亂之間，陰厲旁作，心既疑矣，邪亦隨之。關妖之說正謂是也。愚幼年曾省故里，傳有一夷迷鬼魇，人，闾巷夜聚以避之，凡有窗隙悉皆涂塞，其鬼忽來即扑人驚魇，須臾而止。","sortOrder":14},
  {"id":"s_work_bmtn_13_15","chapterId":"ch_work_bmtn_13","text":"唐自大中後進士尤盛。封定乡、丁茂珪場中頭角，舉子與其交者必先登第，而二公各二十舉方成名，何進退之相懸也！先是，李都、崔雍、孫瑝、鄭嵎四君子蒙其盼睞者，因是進升，故曰：\"欲得命通，問瑝嵎都雍。\"葆光子曰：\"士無華腴寒素，雖瑰意琦行、奧學雄文，苟不資發扬，無以昭播，是則希顏慕蘭、馳騁利名者不能免也。\"","sortOrder":15},
  {"id":"s_work_bmtn_13_16","chapterId":"ch_work_bmtn_13","text":"唐進士殷保晦、妻封夫人皆中朝士族也。殷公歷官台省，始舉進士時文卷皆內子為之，動合規式，中外皆知。良人倜傥疏放，善與人交，未嘗以文章為意。黃寇犯闕，夫妻遭難。初封夫人就刃，殷公失聲，双血被面。其從母為尼，親見其禍，泣言於姻親。愚於殷之中表聞之方信。古人雲：淚盡繼之以血，哀痛之極也。","sortOrder":16},
  {"id":"s_work_bmtn_13_17","chapterId":"ch_work_bmtn_13","text":"唐世劉崇望弟兄五人，內四人皆登進士第，仕至將相丞郎。其元崑崇彝不及第，官至省郎。生五男，每院各與一人為後，崇彝留一男，少有才思。一旦心疾，唯染翰草製誥，褒貶朝中卿相，鹹摭其實。骨肉間懼聞於外，旋取燼之。宛為掌誥之美，竟废於時。鄙夫蜀乡，與前簡刺李詠使君有分。隴右有一子，年十四，掌握管草詞，指揮天曹地府陰隙之事，落翰如飛。家君忧懼，亦苦戒之。此子乃曰：\"但為我父，勿預我事。\"他日墜井而死。心為靈台，既婴風恙，而才思倫序，斯又何哉！","sortOrder":17},
  {"id":"s_work_bmtn_14_1","chapterId":"ch_work_bmtn_14","text":"●卷十二","sortOrder":1},
  {"id":"s_work_bmtn_14_2","chapterId":"ch_work_bmtn_14","text":"唐盧尚書藩以文學登進士第，以英雄自許，歷數镇，薨於靈武。連帥恩賜弔祭，內臣厚希例貺。其家事力不充，未辦歸裝，而天使所求無厭。家人苦之，親表中有官人於靈前告曰：\"家貧如此，將何遵副尚書平生奇杰，豈無威靈及此宦者乎？\"俄而馆中天使中惡，以至於卒。是知精魂強俊者可不畏之哉！八座從孫尚在江陵，嘗聞此說，故紀之，以儆貪货者。","sortOrder":2},
  {"id":"s_work_bmtn_14_3","chapterId":"ch_work_bmtn_14","text":"唐相國楊收，江州人，祖為本州都押衙，父直為蘭溪縣主簿，生四子發、嘏、收、嚴，皆登進士第。收即大拜，發以下皆至丞郎。發以春為義，其房子以柷以乘為名。嘏以夏為義，其房子以煚為名。收以秋為義，其房子以鉅、鏻、鑣、鑒為名。嚴以冬為義，其房子以註、涉、洞為名。盡有文學，登高第，號曰修竹楊家，與靜恭諸楊比於華盛。收相少年於庐山修業，一日，尋幽至深隱之地，遇一道者謂曰：\"子若學道，即有仙分。必若作官，位至三公，終焉有禍，能從我學道乎？\"收持疑，堅進取之心，忽道人之語。他日雖登廊廟，竟離南荒之殛，悲夫！薛泽補闕乃楊氏之女孫婿，嘗語之。","sortOrder":3},
  {"id":"s_work_bmtn_14_4","chapterId":"ch_work_bmtn_14","text":"唐張裼尚書有五子，文蔚、彝憲、濟美、仁龟皆有名第至宰辅丞郎。內一子少年聞說壁魚入道經函中，因蠹食\"神仙\"字，身有五色。人能取壁魚吞之，以致神仙而上升。張子惑之，乃書\"神仙\"字，碎翦實於瓶中，捉壁魚以投之，冀其蠹蚀，亦欲吞之，遂成心疾。每一發作，竟月不食，言語粗秽，都無所避其家扃閉而守之，俟其發愈，一切如常，而倍餐啜一月食料，須品味而飫之，多年方謝世。是知心，靈物也，一傷神氣，善猶不可，况為惡乎！即劉辟吞人，張子吞神仙，善惡不同，其傷一也。","sortOrder":4},
  {"id":"s_work_bmtn_14_5","chapterId":"ch_work_bmtn_14","text":"唐柳大夫玭清廉耿介，不以利回家，世得筆法，蓋公權少師之遺妙也。责授瀘州牧，禮參東川元戎顧彦朗相公，適遇降德政碑，顧欲濡染以光刊刻，亚台曰：\"惡劄固無所吝，若以润筆先賜，即不敢聞命。\"相國钦之。書訖，竟不幹渎也。梁世兖州有下猛和尚，聚徒說法，檀施雲集，時號金刚禪也。他日物故，建塔树碑。庐嶽道士李德陽善欧書，下猛之徒請書碑志，許奉一千缗。德陽不允，乃曰：\"若以一醉相酬得以施展，千缗之遺非所望也。\"終不肯書。斯亦近代一高人也。","sortOrder":5},
  {"id":"s_work_bmtn_14_6","chapterId":"ch_work_bmtn_14","text":"唐十軍軍容使开府嚴遵美門客楊寅善袁許之術，於京城西畿逢一李生，亦唐之疏屬，隆准龍顏，垂手過膝。楊生異之，說於中尉，由是時有資遺之，意其必致非常。黃寇犯闕，僖宗幸蜀。李生為士民挟持入京，升含元殿，不逾浃旬，尋亦遇害。豈大人之相只為一升殿乎莫可知之。楊生叹嗟，不复言知人之鑒也。王蜀先主時有道士李暠，亦唐之宗室，生於徐州而遊於三蜀，詞辯敏捷，粗有文章。因栖陽平觀，為妖人扶持，上有紫氣，乃聚眾舉事。將舉而败，妖辈星散，而暠獨罹其禍焉。其適長裕者，臨邛之大儒也，與暠相善，不信暠之造妖，良由軀幹國姓，為群凶所凭。所以多事之秋，滅跡匿端，無為绿林之嚆矢也。先是，李暠有書召玉局觀楊德辉赴斋，有老道崔無斁，自言患聋，有道而托算術，往往預知吉凶。德辉問曰：\"將欲北行，何如\"崔令畫地作字，弘農乃書\"北千\"兩字，崔公以\"千\"插\"北\"成\"乖\"字，曰：\"去即乖耳。\"楊生不果去，而李暠斋日就擒，道士多罹其禍。楊之幸免，由崔之力也。","sortOrder":6},
  {"id":"s_work_bmtn_14_7","chapterId":"ch_work_bmtn_14","text":"唐楊鑣，收相之子，少年為江西推巡，優遊外幕也。屬秋祭，請祀大姑神。西江中有兩山孤拔，號大者為大孤，小者為小孤，朱崖李太尉有《小孤山賦》寄意焉。後人語訛作姑姊之\"姑\"，創祠山上，塑像艳麗，而風涛甚惡，行旅憚之。每歲本府命從事躬祭，鑣預於此行。鑣悅大姑容，偶有言謔浪。祭畢回舟，而見空中雲務有一女子，容质甚麗，俯就楊公呼為楊郎，遜詞雲：\"家姊多幸，蒙楊郎采顧，便希回桡以成禮也，故來奉迎。\"弘農驚怪，乃曰：\"前言戲之耳。\"小姑曰：\"家姊本無意辄慕君子，而楊郎先自發言，苟或中輟，恐不利於君。\"弘農忧惶，遂然诺之，恳希從容一月處理家事。小姑亦許之。楊生歸，指揮訖，仓卒而卒，似有鬼神來迎也。薛泽補闕與鑣姻懿，常言此事甚詳。近者故登州節判史在德郎中子光泽，甚聰俊，方修舉業，自別墅歸乘，醉入太山廟，謂神曰：\"與神作第三兒，得否\"自是歸家精神恍惚，似有見召，逾月而殂也。呜呼！幽明道隔，人鬼路殊，以身許之，自貽伊戚，將來可為鑒戒也。","sortOrder":7},
  {"id":"s_work_bmtn_14_8","chapterId":"ch_work_bmtn_14","text":"仆嘗覽《柳氏訓序》，見其家法整肅，乃士流之最也。柳玭出官瀘州郡，洎牵复，沿路染疾，至東川通泉縣求医，幕中有崑弟之子省之，亚台回面，且雲\"不識\"。家人曰：\"是某院郎君。\"堅雲：\"不識，莫喻尊旨。\"良久，老仆忖之：得非郎君幞頭腳乎固宜見怪。但垂之而入，必不見阻。比郎君垂下翘翘之尾，果接撫之。其純厚皆此類也。仆親家柳坤即亚台疏房也，侨寓陽安郡。伯仲相率省焉，亚台先問：\"讀書否修文否苟不如是，須學作官。我之先人修文成名，皆作官業，幸勿弃分陰也。\"瀘州郡有柳大夫所造公廨，家具皆牢實粗重，傳及數政，莫知於今存否。蜀朝東川節度許存太師，有功勋臣也。其子承杰即故黔使君禧實之子，隨母嫁許，然其驕貴僭越，少有倫比。作都頭，軍籍只一百二十有七人，是音聲伎術，出即同節使行李，凡從行之物一切奢大，騎碧暖座，垂魚紛错。每修書題，印章微有浸渍即必改換，書吏苦之，流辈以為話端，皆推茂刺顧為首。許公他日有會，乃謂顧曰：\"閣下何太談謗\"顧乃分疏，因指同席數人為證。顧無以對，逡巡乃曰：\"三哥不用草草，碧暖座為眾所知，至於魚袋上鑄蓬萊山，非我唱扬。\"席上愈笑，方知魚袋更僭也。刺茂州，入蕃落，為蕃酋害之。西川衛前軍將李思益者，所著衣服莫非華煥纖麗。蜀先主左右羨而怪之，先主曰：\"李思益一副衣裳大有所費，是要為我光扬軍府，仰與江货場勾當，俾其作衣裝也。\"先主又於作院見匠人裹里小朵帽子，前如鷹嘴，後露腦枕，怪而截其嘴也。又登樓見行人戴褴〈帛炎〉席帽，雲：\"破頭烂額，是何好事\"然自務俭素，愛净絜，皆此類也。蜀朝有小朝士裴璨，俸薄且閒，或勸求宰一邑，裴曰：\"今之畿縣，非有仙骨何以得\"見其愛羨即可知也。每雲：\"黃寇之後所失已多，唯襪頭褲穿靴不傳舊時也。\"仆同院司空監雲：\"木围裹頭於事最便，何必油拭火熨，日日勞煩此一事不請師古，又嫌以銀稜瓷器托里碗碟，徒費功夫。\"又曰：\"措大暮年方婚少女，一生之事，遺丑可知。自非鐵石為心，未有不貽他說。戒之，慎之！\"因述柳氏幞頭引起數事，豈資談笑，亦足小懲也。","sortOrder":8},
  {"id":"s_work_bmtn_14_9","chapterId":"ch_work_bmtn_14","text":"唐乾寧中，補闕楊貽德華族科名，德孤道直，不容於時，請告華陰。方屬京國扰攘，乃謀南來，藏跡於江陵，闾巷僦居，不露行止，旅舍無煙，藜藿不給，未嘗陨獲。於時成中令延接朝客，士有依劉之言。弘農韜藏，不及門宇。一旦堂帖追回，成令驚訝，以為聞聽不至，闕申情禮，兼以入翰苑秉鈞軸期之。補闕曰：\"人之官職又非妄圖，令公過飾，何當奖遇。今宰相何必要某，至於垂搜羅之命他日不過作南中一刺史爾。此际必有奉扰。\"中令赠三百缗，只受三十缗，辦裝所却納朝廷，號為\"鐵補闕\"。未久，除道州牧，却經江陵，告成令求十人，散從官衣裝五十千行資，他無所要。成令甚重之。他日栖南嶽，與玄泰布衲、遁希禪師同居車箱源双泉，歸本長老得祖印於楊公。既殁，家人亦終，似得懸解之道也。本公得禪道於三賢，乃鄭起先辈為愚話之。","sortOrder":9},
  {"id":"s_work_bmtn_14_10","chapterId":"ch_work_bmtn_14","text":"唐張林本士子擢進士第，官至台侍御，為詩小巧，多采景於園林亭沼間。至如\"菱葉乍翻人采後，荇花初没舸行時\"，他皆此類。受眷於崔相昭緯，或謁相庭，崔公曰：\"何以久不拜見\"林曰：\"為飯瓮子熱發\"。崔訝飯瓮不康之語，林曰：\"數日來水米不入，非不康耶\"又寒月遺以衣襦，問其所需，乃曰：\"一衫向下，便是張林。\"相國大笑，終始優遇也。葆光子曰：\"東方朔以詼諧自容，娄君卿以唇舌取適，非徒然也，皆有意焉。今世希酒炙之徒托公侯之势，取容苟媚，過於優旃，自非厚德嚴正之人未有不為此辈調笑也。\"","sortOrder":10},
  {"id":"s_work_bmtn_14_11","chapterId":"ch_work_bmtn_14","text":"唐沈詢，侍郎亚之之子也。崑弟二人，一人乘舸泛河，為驚湍激船Ａ，梁板漂遞，沈子亦漂而死。詢镇潞州，寵婢，夫人甚妒，因配與家人歸秦。其婢旦夕只在左右，歸秦漸恨，伺隙倳刃於詢，果罹凶手。殺歸秦以充祭，亦無及也。唐天复中，湖南節度使劉建封淫其牵拢官陳之婦。陳為同列所戲，恥而發怒，伺便以蒺藜击殺之。馬氏有其位，於今禁蒺藜，蓋懲彭城之遭罹也。淫為大罰，昔賢垂戒，作人君父得不以子禍奴禍取鑒哉！","sortOrder":11},
  {"id":"s_work_bmtn_14_12","chapterId":"ch_work_bmtn_14","text":"唐王潛司徒與武相元衡有分，武公仓卒遭罹，潛常於四時爇紙錢以奉之。王後镇荆南，有染戶許琛一旦暴卒，翌日却活，乃具榜子詣衙，雲\"要見司徒\"。乃通入於階前問之，琛曰：\"初被使人追攝至一衙府，未見王，且領至判官廳，見一官人凭幾曰：'此人错來，自是鷹坊許琛，不幹汝事，即發遣回。'謂許琛曰：'司徒安否我即武相公也。大有門生故吏鮮有念書於身後者，唯司徒不忘，每歲常以紙錢見遺，深感恩德。然所賜紙錢多穿不得。司徒事多，檢點不至，仰為我詣衙具道此意。'\"王公聞之，悲泣慚訝，而鷹坊許琛果亦物故。自此選好紙翦錢以奉之。此事與楊收相於鄭愚尚書處借錢事同。又南嶽道士秦保言威儀，勤於焚修者，曾白真君雲：\"上仙何以須紙錢有所未喻。\"夜夢真人曰：\"紙錢即冥吏所籍，我又何須。\"由是嶽中亦信之。","sortOrder":12},
  {"id":"s_work_bmtn_14_13","chapterId":"ch_work_bmtn_14","text":"閩從事崔員外正直檢身，幕僚所重，奉使湖湘，复命在道，逢寇賊，悉遭殺戮。唯外郎於仓惶中忽有人引路獲免，驅馳遠路，复患痁疾，行邁之次，難求藥铒，途次延平津廟，夢為廟神賜藥三丸，服之，驚覺頓愈。此亦鬼神辅德也。彭城劉山甫自雲外祖李公敬彝郎中宅在東都毓财坊，土地最靈。家人張行周事之有應，未大水前，預夢告張求飲食。至其日，率其類遏水頭，併不冲圮。李宅異事也。","sortOrder":13},
  {"id":"s_work_bmtn_14_14","chapterId":"ch_work_bmtn_14","text":"庐山書生張璟乾寧中以所業之桂州，欲謁連帥張相，至衡州犬嗥滩，損船上岸，寢於江廟，為廟神所责。生以素業對之，神為改容，延坐，從容雲：\"有巫立仁者，罪合族誅。廟神為其分理，奏於嶽神，無人作奏。\"璟為草之。既奏，蒙允。神喜，以白金十餅為赠。劉山甫與廖骘校書親見璟說其事，甚詳也。","sortOrder":14},
  {"id":"s_work_bmtn_14_15","chapterId":"ch_work_bmtn_14","text":"唐黃寇奔冲，有小朝士裴移挈妻子南趨漢中，才發京都，其室女路次暴亡。兵難揮霍，不暇藏瘞，其為悲悼即可知也。行即洛穀，夜聞其女有言，不見其形。父母怪而詰之，女曰：\"我為滻水神之子強暴，誘我歸其家。厥父责怒，以妄殺生人，遽行笞责，兼遜謝撫慰，差人送來。緣夕旦未有托，且欲隨大人南行。\"俾拔茅為苞致於箱笥之中，庶以魂識依止，飲食語言不異於常爾。後白於嚴慈雲：\"已有生處。\"悲咽告辭去。夫鬼神之事，世所難言。素滻之靈有義方之訓，所謂聰明正直之流也。","sortOrder":15},
  {"id":"s_work_bmtn_14_16","chapterId":"ch_work_bmtn_14","text":"古有宅墓之書，世人多尚其事，識者猶或非之。杜公正倫與京兆宗派不同，常蒙輕遠，衔之。洎公宦達後，因事堑斷杜陵山脈，由是諸杜數代不振。鮮於仲通兄弟，阆州新井縣人，崛起俱登將壇。望氣者以其祖先墳上有異氣。降敕堑斷之。裔孫有鮮於嶽者，幼年寢處席底有一小蛇，蓋新出卵者，家人見之以為奇事。此侯及壮，常有自負之色，歷官終於普州安嶽縣令，不免風尘。其徒戲之曰\"鮮於蛇\"也。唐峰亦阆州人，有墳塋在茂賢草市。峰因負販與一術人偕行，經其先塋，術士曰：\"此墳塋子孫合至公相。\"峰謂曰：\"此即家墳隴也。\"士曰：\"若是，君家恐不勝福也。子孫合為賊盜，皆不令終。\"峰志之。爾後遭遇蜀先主开國，峰亦典郡，其二子道袭官，皆至節將。三人典郡，竟如術士之言，何其验也。嚴司空震，梓州鹽亭縣人，所居枕釜戴山，但有鹿鳴，即嚴氏一人必殒。或一日，有親表對坐，聞鹿鳴，其表曰：\"釜戴山中鹿又鳴。\"嚴曰：\"此际多應到表兄。\"其表兄遽對曰：\"表兄不是嚴家子，合是三兄與四兄。\"不日嚴氏子一人果亡，是何異也！","sortOrder":16},
  {"id":"s_work_bmtn_14_17","chapterId":"ch_work_bmtn_14","text":"相國張公文蔚莊在東都北坡，莊內有鼠狼穴，養四子，為蛇所吞。鼠狼雄雌情切，乃於穴外坋土恰容蛇頭，俟其出穴，果入所坋處出頭，度其回轉不及，當腰嚙斷而劈蛇腹，衔出四子，尚有氣，置於穴外，衔豆葉嚼而傅之，皆活。何微物而有情有智若是乎！最靈者人，胡不思也？","sortOrder":17},
  {"id":"s_work_bmtn_15_1","chapterId":"ch_work_bmtn_15","text":"●卷十三","sortOrder":1},
  {"id":"s_work_bmtn_15_2","chapterId":"ch_work_bmtn_15","text":"王中令铎落都統，除滑州節度使，尋罢镇，以河北安靜。於楊全玫有舊，避地浮陽，與其都統幕客十來人從行，皆朝中士子。及過魏，樂彦禎禮之甚至。铎之行李甚侈，從客侍姬有輦下升平之故態。彦禎有子曰從訓，素無賴，愛其車馬姬妾，以問其父之幕客李山甫。山甫以鹹通中數舉不第，尤私憤於中朝貴達，因勸從訓圖之。俟铎至甘陵，以輕騎數百盡掠其橐裝姬仆而還。铎與賓客皆遇害。及奏朝廷，雲：\"得貝州報，某日殺却一人，姓王名令公。\"其凶。誕也如此。彦禎父子尋為亂軍所殺，得非琅琊公訴於上帝乎！","sortOrder":2},
  {"id":"s_work_bmtn_15_3","chapterId":"ch_work_bmtn_15","text":"河中節度使王重榮始為牙將，黃巢犯闕，元戎李都奉伪，畏重榮党附者多，因荐為副使。一日忽謂都曰：\"凡人受恩只可私報，不可以公徇。令公助賊陷一邦，於國不忠，而又日加箕斂，眾口紛然，倏忽变生，何以遏也\"遽命斬其伪使。都無以對，因以軍印授重榮而去。及都至行在，朝廷又以前京兆尹窦潏間路至河中代都為帥，重榮迎之。潏前為京兆尹，有惨酷之名，時謂之墮叠。及至，翌日，集軍校於庭，謂曰：\"天子命重臣作镇將，遏賊冲，安可輕議斥逐令北門出乎且為惡者必一兩人而已，爾等可言之。\"潏不知軍校皆重榮之親党也。眾皆不對，重榮乃自屏肅佩劍歷階而上，謂潏曰：\"為惡者非我而誰\"召潏之仆吏控馬及階，請依李都前例速去之。潏不敢仰视，乃躍馬复由北門而出。重榮破黃巢有功，正授節製，封郡王。與田令孜結怨，他日為部將常行儒殺之，時號\"鐵條\"，以其刚也。","sortOrder":3},
  {"id":"s_work_bmtn_15_4","chapterId":"ch_work_bmtn_15","text":"鄭文公畋字台文，父亚曾任桂管觀察使。畋生於桂州，小字桂兒。時西門思恭為監軍，有詔征赴闕，亚餞於北郊，自以衰年，因以畋托之，曰：\"他日願以桂兒為念，九泉之下不敢忘之。\"言訖，泣然流涕。思恭志之。及為神策軍中尉，亚已卒，思恭使人召畋馆之於第，年未及冠，甚愛之如甥侄，因選師友教道之。畋後官至將相。黃巢之入長安，西門思恭逃難於終南山，畋以家财厚募有勇者訪而獲之以歸岐下，溫清侍膳，有如父焉。思恭終於畋所，畋葬於鳳翔西岡，松柏皆手植之。未幾，畋亦卒，葬近西門之墳。百官皆造二隴以弔之，無不墮淚，鹹伏其義也。","sortOrder":4},
  {"id":"s_work_bmtn_15_5","chapterId":"ch_work_bmtn_15","text":"魏博節度使韓簡性粗质，每對文士不晓其說，心常恥之，乃召一孝廉，令講《論語》。及講至《為政》篇，明日謁諸從事，曰：\"仆近知古人淳朴，年至三十方能行立。\"外有聞者無不絕倒。秦王李茂貞請三傳王利甫講《春秋》。利甫古僻性狷，然演經義文亹亹堪聽。茂貞連月聽之不倦。利甫後寄褐於道門，改名晝，卒於洛中也。武臣未必輕儒，但未睹通儒，多逢鄙薄之辈沮其學善也，惜哉！","sortOrder":5},
  {"id":"s_work_bmtn_15_6","chapterId":"ch_work_bmtn_15","text":"昭義軍節度使孟方立，邢州平乡人也。少以勇力隸於本軍為裨將。廣明中，潞帥高潯攻諸葛爽於河陽，方立出天井關為前鋒。時潯為大將劉廣所逐，廣忌方立，留戍於關。後廣為潞人所殺，三軍乃以方立為帥，因有首邱之思，遂移軍於邢州。用法平正，人皆附之。始拜墳墓於乡里，詣縣令里所陳桑梓之敬，有識者賞焉。侄遷嗣為潞帥，降太原。葆光子曰：\"羅虬累舉不第，務於躁進，因罢舉，依於宦官，典台州，晝錦也。常以展墓，勉竭邑宰，橫笏傲然。宰曰：'某雖尘吏，不達事體，然使君豈不看松柏下人乎？'譏其無桑梓之敬，曾武人之不若也。虬有俊才，嘗見雕陰官妓比紅兒詩，他無聞也。\"","sortOrder":6},
  {"id":"s_work_bmtn_15_7","chapterId":"ch_work_bmtn_15","text":"景福中，幽州帥李匡威率兵救镇州，軍次博水，會軍亂，推其弟匡儔充留後。諸軍皆散，乃以書報弟，付之軍政，南欲赴闕，泊於陆泽。镇州趙王王鎔以匡威救難失國，因請稅駕於常山府郭以中離变。會匡威有幕客李貞抱自闕回，與匡威相遇，同登寺樓觀镇州山川之美，有愛恋之意，乃謀托親。忌王鎔既造之，逼以兵仗，同詣理所，乃入自子城東門，門內有鎔親騎營中之卒，忽掩其外關，复於闕垣中有一人識是王鎔，遽挟於馬上，肩之而去。匡威格斗移時，與貞抱俱死。鎔年十六七，疏瘦，當與匡威併辔之時，雷電忽起，雨雹交下，而屋瓦皆飛，拔大木數株。明日，鎔但覺項偏痛，乃因有力者所挟，不勝其苦故也。訪之，則曰：\"墨君和，鼓刀之士也。\"天意冥數，信然！鎔自脱此難，更在位三十餘年。不有神明扶持，何以獲免！","sortOrder":7},
  {"id":"s_work_bmtn_15_8","chapterId":"ch_work_bmtn_15","text":"唐乾符末，范陽人李全忠少通《春秋》，好鬼穀子之學，曾為棣州司馬，忽有芦一枝生於所居之室，盈尺，三節焉。心以為異，以告別駕張建章。建章積書千卷，博古之士也，乃曰：\"昔者蒲洪以池中蒲生九節為瑞，乃姓蒲後子孫昌盛。芦者茅也，合生陂泽之間，而生於室，非其常也。君後必有分茅之貴。三節者，傳節鉞三人，公可志之。\"全忠後事李可舉為戎校，諸將逐可舉而立全忠，累加至檢校太尉，臨戎甚有威政。全忠死，子匡威嗣。匡威為三軍所逐，弟匡儔為太原所攻，挈家赴闕，至沧州景城為盧彦威所害。先是，匡威少年好勇，不拘小節，自布素中以飲博為事，漁陽士子多忌之。曾一日，與諸遊俠辈釣於桑乾赤欄桥之侧，自以酒祷曰：\"吾若有幽州節製分，則獲一大魚。\"果釣得魚，長三尺，人甚異焉。有馬鬱者，少負文藝。匡威曾問其年，鬱曰：\"弱冠後兩周星。\"傲形於色。後匡威繼父為侯，首召馬鬱問曰：\"子今弱冠後幾周星歲\"鬱但頓顙謝罪。匡威曰：\"好子之事，吾平生所愛也，何懼之有\"因署以府職。其闊達多如此類，故人多附之。葆光子嘗見范陽熟人說李匡儔妻張氏國色也，其兄匡威為帥，強淫之。匡儔按劍而俟，夜深，妻回，出步輦，為其夫殺之。匡威羞見其弟及將校。或言欲將兵救援镇州，既出城，三軍立匡儔為帥，匡威遂稱欲歸朝觐，行次常山，又有劫质王鎔之事。匡儔移牒王鎔，往复指陳，終不及淫秽之事，讳國惡也。","sortOrder":8},
  {"id":"s_work_bmtn_15_9","chapterId":"ch_work_bmtn_15","text":"張建章為幽州行軍司馬，後歷郡守，尤好經史，聚書至萬卷，所居有書樓，但以披閱清净為事，經涉之地無不理焉。曾赍府戎命往渤海，遇風涛，乃泊其船，忽有青衣泛一葉舟而至，謂建章曰：\"奉大仙命請大夫。\"建章乃應之，至一大島，見樓台巋然，中有女仙處之，侍翼甚盛，器食皆建章故乡之常味也。食畢，告退，女仙謂建章曰：\"子不欺暗室，所謂君子人也。忽患風涛之苦，吾令此青衣往來导之。\"及還，風涛寂然，往來皆無所懼。又回至西岸，經太宗征遼碑，半在水中。建章則以帛包麥屑置於水中，摸而讀之，不欠一字。其篤學也如此，蓟門之人皆能說之，於時亦聞於朝廷。葆光子曾遇蓟門軍校姓孫細話張大夫遇水仙，蒙遺鲛绡，自赍而進。好事者為之立傳。今亳州太清宮道士有收得其本者，且曰明宗皇帝有事郊丘，建章乡人掌東序之寶，其言國玺外唯有二物，其一即建章所進鲛绡，箧而貯之，軸之如帛，以紅線三道劄之，亦雲夏天清暑，展开可以滿室凛然。邇來变更，莫知何在。","sortOrder":9},
  {"id":"s_work_bmtn_16_1","chapterId":"ch_work_bmtn_16","text":"●卷十四","sortOrder":1},
  {"id":"s_work_bmtn_16_2","chapterId":"ch_work_bmtn_16","text":"鳳翔李茂貞跋扈至甚，昭宗謂宰相杜讓能曰：\"《春秋》之義，叛而必誅，安有甸服之間顯违朝旨而悖慢如此我若不讨，四方其謂我何\"讓能奏曰：\"艱難已來行貞元故事，姑息戎臣久矣，根牢蔓炽，附之者眾，一旦難骤革之。又京師去岐咫尺，人心易以危懼。設有陵犯，損威愈甚，願陛下稍解雷霆而熟計之。\"帝曰：\"政刑弛紊，詔令不出，都門不欲孱孱守恬而坐。\"因除宰相徐彦若镇鳳翔，以茂貞為興元尹，以嗣覃王率禁軍送彦若。或茂貞遷延不受代，即以兵攻之，軍旅所决，一委讓能。讓能恳諫不從，王師果败。或雲此舉乃讓能報私怨也。茂貞先以長書與讓能，繼上表，仍擁兵至臨皋驿，請誅宰相。帝遂斬枢密使李周瞳以徇，乃貶讓能，仍詔送至軍前。茂貞具禮出迎。至驿，复表請行朝典，讓能奏曰：\"晁错之辜，谬及於臣，今若歸罪於臣，可纾國難。\"帝不得已，貶讓能雷州司戶參軍，遣中使害於驿內。識者以讓能臨難無苟免，亦得其死也。後追赠太尉。其子晓貌如削玉，有製誥之才，仕梁至宰相。鳳歷年洛都有变，為亂軍誤害，時皆叹惜之。","sortOrder":2},
  {"id":"s_work_bmtn_16_3","chapterId":"ch_work_bmtn_16","text":"唐乾寧二年，邠州王行瑜會李茂貞、韓建入觐，决謀废立。帝既睹三帥齊至，必有異謀，乃御樓見之，謂曰：\"卿等不召而來，欲有何意\"茂貞等汗流浃背，不能對，但雲：\"南北司紊亂朝政。\"因疏\"韦昭度讨西川失謀。李磎麻下，為劉崇龟所哭。陛下不合违眾用之\"。及令宦官詔害昭度已下，三帥乃還镇，內外冤之。初王行瑜跋扈，朝廷欲加尚書令，昭度力止之曰：\"太宗以此官總政而登大位，後郭子儀以六朝立功，雖有其名，終身退讓。今行瑜安可輕授焉\"因請加尚父，至是為行瑜所憾，遽罹此害。後追赠太師。李磎字景望，拜相麻出，為劉崇龟抱而哭泣，改授太子少傅，乃上十表及納諫五篇以求自雪，後竟登庸，且計崇龟之惡。時同列崔昭緯與韦昭度及磎素不相协，王行瑜专製朝廷，以判官崔鋋入闕奏事，與昭緯關通，因托鋋致意，由是行瑜率三镇胁君，磎亦遇害。其子渷有高才，同日害之磎著書百卷，號李書樓，後追赠司徒。太原李克用破王行瑜後，崔昭緯貶而賜死，昭皇切齒下詔捕崔鋋，亦冤報之一事也。","sortOrder":3},
  {"id":"s_work_bmtn_16_4","chapterId":"ch_work_bmtn_16","text":"古者文武一體，出將入相，近代裴行俭、郭元振、裴度、韦皋是也。然而時有夷险，不可一概而論。王铎初镇荆南，黃巢入寇，望風而遁。他日將兵捍潼關，黃巢令人傳語雲：\"相公儒生，且非我敵，無污我鋒刃，自取败亡也。\"後到成都行朝，拜諸道都統，高骈上表目之為\"败軍之將\"，正謂是也。諫議大夫鄭寶曾獻書以規其旨雲：\"未知令公以何人為牙爪何士參帷幄當今大盜移國，群雄奋戈，幕下非舊族子弟白面郎君雍容談笑之秋也。\"爾後罢軍權，镇滑台，竟有貝州之禍。鄭文公畋首倡中興，傳檄讨賊，殺戮黃寇，镇靜關畿。一旦部校李昌言胁而逐之，尚不能固位。至如越州崔璆、湖南崔瑾、福建韦岫、鄆州蔡崇、徐方支詳、許昌薛能、河中李都、窦潏、鳳翔徐彦若，狼狽恐懼，求免不暇。唯張浚大言，自方管、葛，以無謀之韓建，倅用刚之孫揆，出征大滷，自貽败亡爾。後朱朴踵為大言，骤居相位，亦曾上表請破鳳翔，所謂以羊將狼，投卵击石。幸而不用，何過望哉！客有謂葆光子曰：\"儒將誠則有之。唐自大中已來，以兵為戲者久矣。廊廟之上恥言韜略，以櫜鞬為凶物，以鈐匮為凶言。就有如盧藩、薛能者，目為粗才，一旦宇內尘驚，闾左飆起，遽以褒衣博帶，令押燕頷虎頭，適足以取笑耳。則韦昭度之憚王建、浚之伐太原是也。\"","sortOrder":4},
  {"id":"s_work_bmtn_16_5","chapterId":"ch_work_bmtn_16","text":"河東節度副使李習吉常應舉不第，為李都河中從事。都失守，習吉自昭義遊太原，辟為從事。習吉好學，有筆述，雖馬上軍前，手不釋卷，太原所發箋奏軍書皆習吉所為也。因從李克用至渭南，令其入奏。帝重其文章，授諫議大夫，使上事北省以榮之，竟歸太原，复其戎職。莊宗即位，追赠禮部尚書。梁太祖每覽太原書檄，遙景重之，曰：\"我何不得此人也！陳琳、阮瑀亦不是過。\"","sortOrder":5},
  {"id":"s_work_bmtn_16_6","chapterId":"ch_work_bmtn_16","text":"韓建兩隨李茂貞迫胁君上，殺戮辅相。昭宗出居，本幸鄜畤，建恳迎奏請至華下，供亿之勞具在《勤王錄》。而殺害郯王等八人，以孤君上，抑其罪也。近代史臣驳論《勤王錄》數條，且曰：\"韓建不遇時可也，而雲隄防道路，拱衛乘舆，欲蓋而彰，則禁固之意可知也。又與諸道書雲語詔書征赴行在，妄也。又曾無糾率諸侯述保大定功之志也。\"以為唐運陵替皆有歷數。自黃巢既戮，蔡賊生焉，宗權滅後而朱玫、王行瑜繼之，才舍茂貞而有韓建。所謂一莽雖死，十莽复生，何天意不祐乎！竟為朱溫宰相。蜀先主聞之，笑曰：\"韓建非豹变之才，與朱溫作相宜也。\"葆光子曰：\"華州韓建、荆渚成汭，勤王奉國，識有可嘉，於時號為北韓南郭，士大夫可以依賴也。古者奉霸主尊本朝，德義小虧，諸侯不至，葵邱之會是也。成、韓位居王辅，荷寵於唐。朱公有無君之心，露問鼎之意。建等不能效臧洪泣血，糾率同盟，亦可以結約親鄰，共張聲势，而乃助桀作孽，畫匹成蛇，舍我善鄰，陳誠伪室。華陰失守，既無力以枝梧；鄂渚丧師，乃無名而陷没。非忠非義，吾所謂二公始終谬也。向使成令睦漢南諸侯，結淮甸雄援，汴人篡逆亦恐未暇。推之天命，即吾不知；考之人謀，固無所取惜哉","sortOrder":6},
  {"id":"s_work_bmtn_16_7","chapterId":"ch_work_bmtn_16","text":"孔緯在中書，朱全忠併有數镇，兵力強盛，表請鹽鐵印。詔下宰相議之，緯力爭不從，謂其下邸吏曰：\"朱公若收鹽鐵印，非興兵不可。\"全忠尋止。後韓建讨太原不利，為張浚所誤，貶之。它日，昭宗欲再攻鳳翔，以問緯。緯曰：\"鳳翔天子西門，若自去窟穴，受製一面，即大事去矣。\"昭宗曰：\"卿是朕賢臣，殊未達時事。\"緯曰：\"陛下以臣為賢，是謗臣也。臣若賢，肯立於陛下之朝\"因稱疾以太子太師致仕，卒於華下。","sortOrder":7},
  {"id":"s_work_bmtn_16_8","chapterId":"ch_work_bmtn_16","text":"中和中，魏博帥羅弘信初為本軍步射小校，掌牧圉之事。曾宿於魏州觀音院門外，其地有神祠，俗號曰：\"白須翁\"。巫有宋遷者，忽詣弘信謂曰：\"夜來神忽有語君不久為此地主。\"弘信怒曰：\"欲危我耶\"他日复以此言來告弘信，弘信因令密之。不期歲，果有軍变，推弘信為帥。弘信状貌丰伟，多力善射，雖聲名未振，眾已服之，累加至太尉，封臨淮王。弘信卒，子紹威繼之，與梁祖通歡結親，情分甚至。先是，本府有牙軍八千人，丰其衣糧，動要姑息。時人雲：\"長安天子，魏府牙軍。\"主使頻遭斥逐，由此益驕。紹威不平，有意翦滅，因與汴人計會，诈令役夫肩籠內藏器甲，扬言汴帥葬羅氏之女。紹威密令人於兵仗库斷弓絃共甲襻，夜會汴人，擐甲持戈攻殺牙軍。牙軍覺之，排闼入库而弓甲無所施勇也，全營殺盡，仍破其家。人謂牙軍久盛，宜其死矣。紹威雖豁素心，而紀綱無有，漸為梁祖陵製，竭其帑藏以奉之。忽患腳瘡，痛不可忍，意其牙軍為祟，乃謂親吏曰：\"聚六州四十三縣鐵打一个错。\"不成也，紹威卒。其子周翰繼之，俄而移镇滑台，羅氏大去其國矣。","sortOrder":8},
  {"id":"s_work_bmtn_16_9","chapterId":"ch_work_bmtn_16","text":"劉仁恭微時，曾夢佛幡於手指飛出，或占之曰：\"君年四十九必有旌幢之貴。\"後如其說，果為幽帥。自破太原軍於安塞城後，士兵精強，孩视鄰道。發管內丁壮號三十萬南取鄴中，圖袁、曹之霸，先下甘陵，無少長悉坑之。初治甘陵城下，有鸺留數頭飛下幄帳內，逐之复來，仁恭惡之。竟為魏軍、汴軍夹攻，大败之，殺其名將单可及，仁恭单馬而遁。於時軍败於內黃。爾後汴帥攻燕，亦败於唐河。他日命使聘汴，汴帥开宴，俳優戲医病人以譏之，且問：\"病状內黃以何藥可瘥\"其聘使謂汴帥曰：\"內黃可以唐河水浸之必愈。\"賓主大笑，賞使乎之美也。","sortOrder":9},
  {"id":"s_work_bmtn_17_1","chapterId":"ch_work_bmtn_17","text":"●卷十五","sortOrder":1},
  {"id":"s_work_bmtn_17_2","chapterId":"ch_work_bmtn_17","text":"天复元年，鳳翔李茂貞請入觐奏事，朝廷允之，蓋軍容使韓全誨與之交結。昭宗御安福樓，茂貞涕泣陳匡救之言。時崔胤密奏曰：\"北奸人也，未足為信。陛下宜宽懷待之。\"翌日宴於寿春殿，茂貞肩舆衣駝褐入金鸞門，易服赴宴。鹹以為前代跋扈未有此也。時韓全誨深相交結，崔胤懼之，自此亦結朱全忠，竟致汴州迎駕，與鳳翔連兵劫遷入洛之始。識者以王子帶召戎，崔胤比之。先是，茂貞入闕，焚燒京城。是宴也，俳優安辔新號茂貞為火龍子。茂貞慚惕俯首。宴罢，有言他日須斬此優。辔新聞之，因請假往鳳翔。茂貞遙見，詬之曰：\"此優窮也，胡為敢來\"辔新對曰：\"只要起居，不為求救。\"茂貞曰：\"貧俭如斯，胡不求乞\"安曰近日京中但賣麩炭可以取濟，何在求乞\"茂貞大笑而厚賜，赦之也。","sortOrder":2},
  {"id":"s_work_bmtn_17_3","chapterId":"ch_work_bmtn_17","text":"軍容使韓全誨以駕幸鳳翔，李茂貞比懷挟帝以令諸侯之意，懼朱全忠之盛也。西川王公建亦有此慮，乃結汴州同起軍助其迎駕。汴軍傅城，川軍乃攻興元，其帥王萬洪以無救援遂降成都，由是山南十四州併為蜀有，方变謀却助鳳翔。於時命掌書記韦莊奉使至軍前，朱公大怒。自此與西川失歡，而汴帥軍罢。","sortOrder":3},
  {"id":"s_work_bmtn_17_4","chapterId":"ch_work_bmtn_17","text":"李巨川有筆述，歷舉不第。先以仕伪襄王與唐彦謙俱貶於山南，褒帥楊守亮優待之。山南失守，隨致仕楊軍容复恭與守亮同奔北投太原，导行者引出華州，复恭為韓建挫辱，極骂為奴，以短褐蒙之，毙於枯木。守亮槛送至京，斬於獨柳树。京城百姓莫不沾涕。此即南山一丈黑，本姓訾，黃巢時多救護导引朝士，令趨行在，人有逃黃巢而投附，皆濟之，由是人多感激也。巨川為韓建副使，朱令公軍次於華，用張浚計，先取韓建。其幕客張策携印率副使李巨川同詣轅門請降，朱公謂曰：\"車駕西幸，皆公所教也。\"建曰：\"某不識字，凡朝廷章奏、鄰道書檄皆巨川為之。\"因斬之，識者謂韓建無行，求解怒於朱公，遂為所賣。時人冤之。巨川有子慎儀，仕後唐為翰林學士。唯張策本與張浚有分，携印而降，葉浚之謀，後仕至梁相。朱公既得韓建以兄呼之，尋奏移許昌，梁鳳歷初亦遇害也。","sortOrder":4},
  {"id":"s_work_bmtn_17_5","chapterId":"ch_work_bmtn_17","text":"德宗皇帝好為詩，以賜容州戴叔倫。文宗、宣宗皆以詩賜大臣。昭宗駐跸華州，以歌辭賜韓建，以詩及《楊柳枝》辭賜朱全忠。所賜一也，或以敬，或以憚，受其賜者得不求其義焉。","sortOrder":5},
  {"id":"s_work_bmtn_17_6","chapterId":"ch_work_bmtn_17","text":"汴帥朱公再围鳳翔，與茂貞軍戰於虢縣西槐林驿，大败岐軍，橫尸不絕，鮑氣聞於十里。昭宗遂殺宦官韓全誨已下二十二人首宣示，茂貞亦斬其義子繼筠首以送。於是車駕還宮，朱令俯首馬前請罪，涕泣拢帝馬行千步。帝為之動容。至京師，以宰相崔胤判六軍，乃下詔誅宦官第五可范已下七百一十人，又鳳翔駕前宰相盧光啟等一百餘人併賜自盡。天复三年，汴人擁兵殺宰相崔胤，京兆尹鄭元規劫遷車駕移都東洛。既入華州，百姓呼萬歲，帝泣謂百姓曰：\"百姓勿唱萬歲，朕弗能與爾等為主也。\"沿路有《思帝乡》之詞，乃曰：\"紇幹山頭冻殺雀，何不飛去生處樂氵兄我此行悠悠，未知落在何所。\"言訖，泫然流涕。行至陝府內宴，皇後自捧玉盆以賜全忠，內人唱歌。全忠將飲酒，韓建躡其足，全忠懼，辭醉而退。至水而殺內人可證及隨駕五百人，自是帝孤立矣。","sortOrder":6},
  {"id":"s_work_bmtn_17_7","chapterId":"ch_work_bmtn_17","text":"昭宗遷都至洛，左右併是汴人，雖有尊名，乃是虛器，如在籠槛，鬱鬱不樂。朱全忠以諸侯盡有匡复之志，慮帝有奔幸之謀。時護駕朱友谅等聚兵殿庭，訴以衣食不足。帝方勞諭，友谅引兵升殿。帝顛仆入內，軍士躡而追之。帝叱曰：\"反耶\"友谅曰：\"臣非敢無禮，奉元帥之令。\"帝奔入御厨，以庖人之刀斬數辈，竟為亂兵所害。內人李漸榮、裴正一聞弒帝，投刃而死。又以朱友谅、氏叔琮扇動軍情，誅朱友谅、氏叔琮，以成濟之罪歸之。友谅等臨刑訴天曰：\"天若有知，他日亦當如我。\"後全忠即位，為子友珪所弒，竟如其言。","sortOrder":7},
  {"id":"s_work_bmtn_17_8","chapterId":"ch_work_bmtn_17","text":"辉王嗣位社，宴德王裕已下諸王子孫，併密為全忠所害。德王，帝之兄，曾册皇太子。劉季述等废昭宗，册為皇帝。季述等伏誅。令歸少陽院。全忠以德王眉目疏秀，春秋漸盛。全忠惡之，請崔胤密啟雲：\"太子曾竊寶位，大義滅親。\"昭宗不納。一日，駕幸福先寺，謂枢密使蒋玄暉曰：\"德王吾之愛子，何故頻令吾废之，又欲殺之\"言訖淚下，因嚙其中指血流。全忠聞之，宴罢，盡殺之。","sortOrder":8},
  {"id":"s_work_bmtn_17_9","chapterId":"ch_work_bmtn_17","text":"辉王即位天祐中，朱全忠以舊朝達官尚在班列，將謀篡奪，先俾翦除。凡在周行，次第貶降，舊相裴枢、獨孤損、崔遠，陆扆、王溥、大夫趙崇、王贊等於滑州白馬驿賜自盡。時宰相臣柳璨性陰狡貪權，惡枢等在己之上，與全忠腹心枢密使蒋玄暉、太常卿張廷范密友交結而害枢等。俄而廷范轅裂，玄暉與柳璨及弟瑤、瑊相繼伏誅。先是，故相張浚一家併害而弃尸黃河，朱公謀主李振累應進士舉不第，尤憤朝貴，時謂朱全忠曰：\"此清流辈宜投於黃河，永為濁流。\"全忠笑而從之。爾朱榮河陰之戮衣冠不是過也。俄而辉王禪位，封濟陰王，於曹州遇酖而崩，唐祚自此滅矣。","sortOrder":9},
  {"id":"s_work_bmtn_17_10","chapterId":"ch_work_bmtn_17","text":"朱全忠先以蒋玄暉為枢密使，伺帝動靜。積慶何太後以昭宗見害之後，常恐不保旦夕，曾使宮人阿秋面召玄暉屬戒，所乞它日傳禪之後，保全子母性命。言發，無不涕零。先是，全忠速要傳禪，召玄暉到汴州，责以太遲。玄暉以傳禪先須封國，授九錫之命，俟次第行之。全忠怒曰：\"我不要九錫，看作天子否。\"玄暉歸奔洛陽，與宰相商量，為趙殷衡誣谮雲：\"與太後交通，欲延唐祚。\"乃令殷衡逼殺太後及宮人，而誅蒋玄暉。時人冤之。趙殷衡後改姓孔名循，亦莫知其實是何姓，仕後唐明宗為宣徽使，出為許昌、沧州兩镇。時人知其狡譎傾险，莫不憚之。","sortOrder":10},
  {"id":"s_work_bmtn_17_11","chapterId":"ch_work_bmtn_17","text":"唐天祐三年，拾遺充史馆修撰崔彖進状，以堂叔母在孟州濟源私莊，抱疾加甚，無兄弟奉養，無強近告投，兼以年將七十，地絕百里，闕视藥膳，不遑晓夕。遂乞假躬往侍疾。敕旨依允。時人義之，或曰避禍而享義名者，亦智也。","sortOrder":11},
  {"id":"s_work_bmtn_17_12","chapterId":"ch_work_bmtn_17","text":"黃巢破後，蔡州秦宗權繼為反逆，兵力強銳，又复稱僭，山東諸郡苦之，十年之間屠脍生聚。汴帥朱全忠盡節御之，宗權為部將申丛擒而折足囚縛，朱全忠具表槛送至京。京兆尹孫揆率府縣吏閱之，宗權即槛中舉首曰：\"宗權非反也。\"大尹哀之，觀者因以為笑。","sortOrder":12},
  {"id":"s_work_bmtn_17_13","chapterId":"ch_work_bmtn_17","text":"李罕之，河陽人也，少為桑門無賴，所至不容。曾乞食於滑州酸棗縣，自旦至晡無與之者。掷鉢於地，毀僧衣，投河陽諸葛爽為卒。罕之即僧號，便以為名。素多力，或與人相殴，殴其左頰，右頰血流。爽尋署為小校，每遣讨賊，無不擒之。蒲絳之北有摩雲山，設堡柵於上，號摩雲寨，前後不能攻取，時罕之下焉，自此號李摩雲。累歷郡侯、河南尹節將，官至侍中，卒於汴州，荆南成汭之流也。","sortOrder":13},
  {"id":"s_work_bmtn_18_1","chapterId":"ch_work_bmtn_18","text":"●卷十六","sortOrder":1},
  {"id":"s_work_bmtn_18_2","chapterId":"ch_work_bmtn_18","text":"梁祖圖霸之初，寿州刺史江彦溫以郡歸我，乃遣親吏張從晦勞其勤。而從晦無賴，酒酣，有飲徒何藏耀者與之偕，甚昵，每事誤禀從晦。致命於郡，彦溫大張樂，邀不至，乃與藏耀食於主將家。彦溫果疑恐曰：\"汴王謀我矣，不然，何使者之如是也\"乃殺其主將，連誅數十人，而以状白其事。既而又疑懼曰：\"訴其腹心，亡我族矣。\"乃自縊而死。梁祖大怒，按其事，腰斬從晦，留藏耀，裂其夤，械斬於寿春市。葆光子曰：\"後唐明宗皇帝時，董璋據東川，將有跋扈之心，於時遣客省使李仁矩出使梓潼。仁矩比節使下小校骤居內職，性好狎邪。元戎張筵，托以寒熱，召之不至，乃與營妓曲宴。璋聞甚怒，索馬詣馆，遽欲害之。仁矩鞹足端簡迎門，璋怒稍解。他日作叛，兩川舉兵，併由仁矩獻謀於安重誨之所致也。\"","sortOrder":2},
  {"id":"s_work_bmtn_18_3","chapterId":"ch_work_bmtn_18","text":"梁太祖初兼四镇，先主遣押衙潘岏持聘。岏飲酒一石不亂，每攀燕飲，禮容益莊，梁祖愛之。飲酣，梁祖曰：\"押衙能飲一盤器物乎？\"岏曰：\"不敢。\"乃簇在席器皿，次第註酌。岏併飲之，岏愈溫克。梁祖謂其歸馆多應傾泻，困臥，俾人侦之。岏簪箨冠子，秤所得酒器，涤而藏之。他日又遣押衙鄭頊持聘，梁祖問以劍閣道路，頊極言危峻。梁祖曰：\"賢主人可以過得\"頊對曰：\"若不上聞，恐誤令公軍機。\"梁祖大笑。此亦近代使令之美者也。","sortOrder":3},
  {"id":"s_work_bmtn_18_4","chapterId":"ch_work_bmtn_18","text":"朱瑾之據兖州，梁祖攻之未克。其從父兄齊州刺史琼先降，與琼同詣壁下以晓之。瑾乃遣都虞候胡規出獻款曰：\"兄已降，願貸瑾不死，請以镇委吏。\"既而啟延寿門，陳牌印於笥，曰：\"兄來，請先奉此。\"梁祖命琼受之，葛從周疑诈，選勇士孫少迪等仗劍以馭。琼曰：\"彼力屈，不足疑。\"琼進前受印籥，瑾单馬，曰：\"兄獨來，密語耳。\"始相及，瑾令驍卒董懷進勾曳琼墜馬，乃發所匿刃殺琼，勾戟突出牵入之。須臾，城上鼓噪，掷琼首於埤也。我軍失色，梁祖哀恸久之，斬軍謀徐厚，署琼弟玭為齊州防御使，恩禮殊厚。瑾竟弃城投扬州。","sortOrder":4},
  {"id":"s_work_bmtn_18_5","chapterId":"ch_work_bmtn_18","text":"梁祖宿兵岐下以迎昭宗，敵壘尚堅旦思班退，親從指揮使高季昌抗言曰：\"天下雄杰窥此舉者一載矣，今奸党已窘，更少俟之。\"季昌乃密募人入岐為告事者，有騎卒馬景應命。因朱友倫總騎軍且至，將大出兵迓。景請其時給駿驷雜所出队中，十許里，躍馬西逸，叩岐闉，以軍怨東遁為告，且言列寨留卒尚萬，俟夕將逝，宜速掩之，當落我機內矣。然是往也决無生理，願錄其妻孥。梁祖悽然止其行，景固請，乃徇之。明日軍出，諸寨屏匿如無人，不十里，果風騎却走，岐人納之，不失厥料。岐軍啟兩扉悉眾來，我師宿已秣馬飽士，中軍一鼓，百營俱進，大破岐軍，十不存三四焉。李茂貞丧胆，昭宗降詔還京，始遂奉迎矣。功歸高公，而馬景妻孥倍加軫恤。且解扬以守正為忠，不顧其身也。馬景以死命行诈，非圖身也，人之難事唯景有之。","sortOrder":5},
  {"id":"s_work_bmtn_18_6","chapterId":"ch_work_bmtn_18","text":"宣州田頵、寿州朱延寿將舉軍以背楊行密，請杜荀鶴持箋詣淮都。俄而事泄，行密悉兵攻宛陵，延寿飛騎以赴，俱為淮軍所殺。延寿之將行也，其室王氏勉延寿曰：\"願日致一介以寧所懷。\"一日，介不至，王氏曰：\"事可知矣。\"乃部分家僮，悉授兵器，遽阖州中之扉，而捕騎已至，不得入。遂集家僮，私阜帑，發百燎，庐舍州廨焚之。既而稽首上告曰：\"妾誓不以皎然之軀為仇者所辱。\"乃投火而死。古之烈女無以過也。","sortOrder":6},
  {"id":"s_work_bmtn_18_7","chapterId":"ch_work_bmtn_18","text":"唐乾符中，荆州節度使晉公王铎後為諸道都統，時木星入南斗，數夕不退。晉公觀之，問諸知星者吉凶安在，鹹曰：\"金火土犯斗即為灾，唯木當應為福耳。\"鹹或然之，時有術士邊岡洞晓天文，精通歷數，謂晉公曰：\"唯斗帝王之宮宿，唯木為福神，當以帝王占之。然則非福於今，必當有验於後，未敢言之。\"它日，晉公屏左右密問，岡曰：\"木星入斗，帝王之兆。木在斗中，'朱'字也。\"識者言唐世嘗有緋衣之讖，或言將來革運或姓裴，或姓牛，以為\"裴\"字為緋衣，\"牛\"字著人即朱也，所以裴晉公度、牛相國僧孺每罹此謗。李衛公斥《周秦行紀》乃斯事也，安知鐘於碭山之朱乎","sortOrder":7},
  {"id":"s_work_bmtn_18_8","chapterId":"ch_work_bmtn_18","text":"梁开平中，潞州軍前李思安奏壶關縣庶穰乡人因伐树倒分為兩片，內有六字，皆如左書，曰：\"天四十載石進。\"乃圖其状以獻，仍付史馆。爾後唐莊宗皇帝自晉王登位以為應之，中間石氏自併門受國稱晉朝。湖南馬希范解釋此字，表聞焉。","sortOrder":8},
  {"id":"s_work_bmtn_18_9","chapterId":"ch_work_bmtn_18","text":"梁相國薛貽矩，名家子，擢進士第，在唐至御史大夫。先是，南班官忌與北司交通，天复中翦戮閹官，貽矩嘗與韓全誨等作寫真贊，悉紀於內侍省屋壁間，坐是謫官。它日，赍唐帝命禪於梁，仕至宰相。","sortOrder":9},
  {"id":"s_work_bmtn_18_10","chapterId":"ch_work_bmtn_18","text":"黃巢自長安遁歸，與其眾屯於陳、蔡間〈氵殷〉河，下寨連絡，號八山營。於時蔡州秦宗權懼巢，以城降之。時既飢乏，野無所掠，唯捕人為食，肉盡繼之以骨，或確捣或磨，鹹用充飢。天軍四合，巢軍不利，其党駭散，頻為雷電大雨淹浸其營，乃與妻孥崑弟奔於太山狼虎穀，為外甥林言斬首送徐州，時溥下裨將李師銳函首送成都行在也。","sortOrder":10},
  {"id":"s_work_bmtn_18_11","chapterId":"ch_work_bmtn_18","text":"梁祖親征鄆州，軍次衛南時，筑新壘，土工畢，因登眺其上，見飛乌止於峻堞之間而噪，其聲甚厲。副使李璠曰：\"是乌鳥也，將有不如意之事。\"其前軍朱友裕為朱瑄掩扑，拔軍南去。我軍不知，因北行，遇朱瑄軍來迎，梁祖策馬南走，入村落間為賊所迫，前有溝坑，頗極深廣，總遽之际忽見溝內蜀黍秆積以為道，正在馬前，遂騰躍而過，因獲免焉。副使李璠、都將高行思為賊所殺，張歸宇為殿騎，援戈力戰，仅得生還，被十四五箭。乃知衛南之乌，先見之验也。","sortOrder":11},
  {"id":"s_work_bmtn_18_12","chapterId":"ch_work_bmtn_18","text":"丁會為昭義節帥，常懼梁祖雄猜，疑忌功臣。忽謂敬翔曰：\"吾夢丁會在前祗候，吾將乘馬欲出，圉人以馬就台，忽為丁會跨之以出。時夢中怒，叱喝數聲，因驚覺。甚惡之。\"是月，丁會舉潞州軍民歸河東矣。","sortOrder":12},
  {"id":"s_work_bmtn_18_13","chapterId":"ch_work_bmtn_18","text":"梁祖末年多行誅戮。一夕，寢殿大棟忽墜於御榻之上，初聞土落於寢帳上，乃驚覺。久之，又聞有小木墜於帳顶間，遂懼然下床，未出殿門，其棟乃墜。遲明召諸王近臣令觀之。夜來驚危，幾不相見，由是君臣相泣，又曰：\"驚忧之時，如有人引頭於寢合門內雲：'里面莫有人否'所以總忙奔起，得非宮殿神乎？\"它日又遊於大內西九曲池，泛舟於池上，舟忽傾侧，上墮於池中，宮嫔併內侍從官併躍入池扶策登岸，移時方安。爾後發痼疾，竟罹其子郢王友珪弒逆之禍，舟傾棟折非佳事也。","sortOrder":13},
  {"id":"s_work_bmtn_18_14","chapterId":"ch_work_bmtn_18","text":"梁祖末年用軍不利，河北數镇不順其命。一旦躁撓，堅要親征，師次深州界，遂令楊師厚分兵攻棗強縣，半浃旬方拔其壘。是邑也，池湟堅牢，人心獷悍，晝夜攻击以至疲竭。既陷之日，無少長皆屠之，時有一百姓來投軍中，李周彝收於部伍間。乃謂周彝曰：\"請一劍，願先登以收其城。\"未許間，忽然抽茶擔子揮击周彝頭上中簷，幾仆於地，左右乃擒之。元是棗強城中遣來令诈降，本意欲窥梁軍招讨使楊師厚，斯人不能辨，誤中周彝。是知河朔之民勇劲如此。","sortOrder":14},
  {"id":"s_work_bmtn_18_15","chapterId":"ch_work_bmtn_18","text":"梁司天監仇殷術數精妙，每見吉凶不敢明言，稍關逆耳秘而不說，往往罰俸，蓋懼梁相之好殺也。梁自昭義失守，符道昭就擒，柏乡不利，王景仁大败，皆為太原節使嗣晉王李存勖之所挫也。方懷子孫之忧，唯柏乡狼狽，亦自咎雲：\"违犯天道，不取仇殷之言也。\"","sortOrder":15},
  {"id":"s_work_bmtn_19_1","chapterId":"ch_work_bmtn_19","text":"●卷十七","sortOrder":1},
  {"id":"s_work_bmtn_19_2","chapterId":"ch_work_bmtn_19","text":"梁祖，宋州碭山縣午溝里人，本名溫，賜名全忠，建國後改名晃。家世為儒，祖信、父誠皆以教授為業。誠蚤卒，有三子，俱幼，母王氏携養寄於同縣人劉崇家。崑弟之中唯溫狡猾無行，崇母撫養之。崇弟兄嘗加譴杖，一日偷崇家釜而竄，為崇追回，崇母遮護以兔朴责。善逐走鹿，往往及而獲之。又崇母常見其有龍蛇之異。它日與仲兄存入黃巢中作賊，伯兄昱與母王氏尚依劉家。溫既辭去，不知存亡。及溫領镇於汴，盛飾舆馬，使人迎母於崇家，王氏皇恐辭避，深藏不之信，謂人曰：\"朱三落拓無行，何處作賊送死，焉能自致富貴汴帥非吾子也。\"使者具陳離乡去里之由、歸國立功之事，王氏方泣而信。是日與崇母併迎歸汴，溫盛禮郊迎，人士改觀。崇以舊恩，位至列卿，為商州刺史。王氏以溫貴封晉國太夫人，仲兄存於賊中為矢石所中而卒。溫致酒於母，歡甚，語及家事，謂母曰：\"朱五經辛苦業儒，不登一命。今有子為節度使，無忝先人矣。\"母不怿，良久，謂溫曰：\"汝致身及此，信謂英特，行義未必如先人。朱二與汝同入賊軍，身死蠻徼，孤男稚女，艱食無告，汝未有恤孤之心，英特即有諸無取也。\"溫垂涕謝罪，即令召諸兄子皆至汴，友寧、友倫皆立軍功，位至方镇。","sortOrder":2},
  {"id":"s_work_bmtn_19_3","chapterId":"ch_work_bmtn_19","text":"梁祖魏國夫人張氏，碭山富室女。父蕤曾為宋州刺史，溫時聞張有姿色，私心傾慕，有麗華之叹。及溫在同州，得張於兵間，因以婦禮納之。溫以其宿款，深加敬異。張賢明有禮，溫雖虎狼其心，亦所景伏，每謀軍國計，必先延訪。或已出師，中途有所不可，張氏一介請旋，如期而至，其信重如此。初收兖鄆，得朱瑾妻，溫告之雲：\"彼既無依，寓於辎車。\"張氏遣人召之，瑾妻再拜，張氏答拜泣下，謂之曰：\"兖鄆與司空同姓之國，崑仲之間，以小故尋幹戈，致吾姒如此。設不幸汴州失守，妾亦似吾姒之今日也。\"又泣下，乃給度為尼，張恒給其費。張既卒，繼寵者非人。乃僭號後，大縱朋淫，骨肉聚麀，帷薄荒秽，以致友珪之禍起於婦人。始能以柔婉之德製豺虎之心如張氏者，不亦賢乎！","sortOrder":3},
  {"id":"s_work_bmtn_19_4","chapterId":"ch_work_bmtn_19","text":"河東李克用，其先回紇部人，世為蕃中大酋，受唐朝官職。太宗於北方沙陀碛立沙陀府以招集降戶。後克用祖朱邪執宜與其父曾依吐蕃，背吐蕃歸朝。德宗於鹽州置陰山府，以執宜為都督，後遷於神武川黃花堆之別野，即今應州是也。執宜生赤心，以讨徐州庞勋功賜國姓併名，號李國昌。懿宗問其先世所出，雲：\"本隴西金城人，依寓吐蕃。\"帝曰：\"我先與汝同乡里。\"敕令編籍鄭王房，始為雲州大同軍節度，次授鄜延、振武、代北三節度。其侄克讓為羽林將軍，其子克用最聞名，以破黃巢功為太原節度使。子存勖平梁蜀，奄有中原，追尊執宜號懿祖、國昌號獻祖、克用號太祖皇帝。太祖在妊十三月，載誕之夕，母後甚危，令族人市藥於雁門，遇神人教以率部人被介持旄，击鉦鼓，躍馬大躁，環所居三周而止。果如所教而生，是日虹光燭室，白氣充庭，井水暴溢。及能言，喜道軍旅。年十二三，能連射双鳥，至於树葉針鋒馬鞭皆能中之。曾於新城北以酒酹毗沙門天王塑像，請與仆交談。天王被甲持矛，隱隱出於壁間。或所居帳內時如火聚，或有龍形，人皆異之。嘗隨獻祖征庞勋，臨陣出没如神，號為飛虎子。眇一目，時號獨眼龍。功業磊落，不可盡述。","sortOrder":4},
  {"id":"s_work_bmtn_19_5","chapterId":"ch_work_bmtn_19","text":"唐乾寧中，鳳翔李茂貞、華州韓建、邠州王行瑜擁兵协君，誅戮宰辅，焚燒宮闕。初，帝西幸鳳翔。昭宗出居石門莎城，太原克用領蕃漢馬步入京，三镇大懼。是年破邠州，斬王行瑜。昭宗嘉奖倚賴，命延王丕、丹王允赍詔賜李公衣服，兼令二親王設拜以兄事之，近古未有也，仍封晉王以寵之。延王才識過人，聰悟辯慧，在晉陽留宴累月，每獻酬樂作，必為晉王起舞，後為韓建所殺。","sortOrder":5},
  {"id":"s_work_bmtn_19_6","chapterId":"ch_work_bmtn_19","text":"太原李克用自渭北班師，次河西縣。王珂於冰上構浮航，公渡浮航，馬足陷桥，李習吉從。馬軼墜河，習吉抱冰，舟人拯之獲免。王珂懼公，謂曰：\"公之於吾非機桥者，何嫌之有李諫議有聞於時，則不吾知也。\"置酒笑樂而罢。習吉，右相林甫之後，應舉不第，黃巢後遊於河東，攝榆次令。李公辟為掌記，箋檄之捷無出其右。梁祖每讀河東書檄，嘉叹其才，顧敬翔曰：\"李公計絕一隅，何幸有此人！如鄙人之智算得習吉之才筆，如虎之傅翼也。\"其見重如此。","sortOrder":6},
  {"id":"s_work_bmtn_19_7","chapterId":"ch_work_bmtn_19","text":"梁祖陷邢州，進軍攻王鎔於常山。趙之賓佐有周式者，性慷慨，有口才，謂王鎔曰：\"事急矣，速决所向，式願為行人。\"即出見之，梁祖曰：\"王公朋附併汾，违盟爽信，弊賦已及於此，期於無舍。\"式曰：\"明公為唐室之桓、文，當以禮義而成霸業。王氏今降心納质，願修舊好。明公乃欲窮兵黷武，殘滅同盟，天下其謂公何\"梁祖笑，引式袂謂之曰：\"與公戲耳。\"鎔即送牛酒幣货數萬犒汴軍，仍令其子入质於汴，因而解围，近代之魯仲連也。","sortOrder":7},
  {"id":"s_work_bmtn_19_8","chapterId":"ch_work_bmtn_19","text":"唐昭宗以宦官怙權，驕恣難製，常有誅翦之意。宰相崔胤嫉忌尤甚。上敕胤，凡有密奏，當進囊封，勿於便殿啟奏，以是宦者不之察。韓全誨等乃訪京城美婦人數十以進，求宮中陰事。天子不之悟。胤謀漸泄。中官以重賂甘言請藩臣以為城社，视崔胤眦裂。時因伏腊燕聚，則相向流涕，辭旨訣別。會汴人寇同、華，知崖胤之謀，於是韓全誨引禁軍陳兵仗逼帝幸鳳翔。它日，崔胤與梁祖葉謀以誅閹宦，未久，禍亦及之，致族絕滅。識者歸罪於崔胤。先是，其季父安潛嘗謂親知曰：\"滅吾族者必緇兒也。\"緇兒即胤小字。河東晉王李克用聞胤所為，謂賓友曰：\"助賊為虐者其崔胤乎！破國亡家必在此人也。\"","sortOrder":8},
  {"id":"s_work_bmtn_19_9","chapterId":"ch_work_bmtn_19","text":"晉王李克用妻劉夫人常隨軍行，至於軍機多所弘益。先是，汴州上源驿之变，晉王憤恨，欲回軍攻之。夫人曰：\"公為國讨賊，而以杯酒私忿必若攻城，即曲在於我，不如回師，自有朝廷可以論列。\"於是班退。天复中，周德威為汴軍所败，三軍潰散。汴軍乘我晉王危懼，與周德威議欲出保雲州，劉夫人曰：\"妾聞王欲弃城而入外藩，誰為此畫\"曰：\"存信辈所言。\"夫人曰：\"存信本北方牧羊兒也，焉顧成败王常笑王行瑜弃城失势，被人屠割，今复欲效之，何也王頃歲避難達靼，幾遭陷害，賴遇朝廷多事方得复歸。今一旦出城便有不测之变，焉能遠及北藩\"晉王止行，居數日，亡散之士复集，軍城安定，夫人之力也。","sortOrder":9},
  {"id":"s_work_bmtn_19_10","chapterId":"ch_work_bmtn_19","text":"王師范之镇青州，以部將劉鄩竊據兖州。先是，汴將葛從周镇於是邦，因出征，劉鄩將圖兖也，诈為茶商，苞苴鎧甲，大起店肆，剖巨木藏兵仗而入。竊發之日得其徒千人，據其府舍，升堂拜從周之母，仍以禮待其妻子，子弟職掌、妻孥供亿如常。俄而，從周攻其城，梯?雲合。鄩以板舆請從周母登城諭從周曰：\"劉將軍待我不異於兒，新婦已下併不失所。\"從周在城下歔欷，即時退舍。及青州兵败，師范納款，梁祖遣使諭鄩，鄩曰：\"臣知王公修好與梁國通盟，但臣本受王公之命，保有州城，一旦見其势窮，擅命不顧，非盡心於所事也。仆俟王公之命俯首非晚。\"至是師范諭之，方以城歸。梁祖多其義，超擢非次，官至方镇，為梁之名將。","sortOrder":10},
  {"id":"s_work_bmtn_19_11","chapterId":"ch_work_bmtn_19","text":"昭宗先謚聖穆景文孝皇帝，廟號昭宗，起居郎蘇楷等驳議，請改為恭靈莊闵皇帝，廟號襄宗。蘇楷者，禮部尚書蘇循之子，乾寧二年應進士。楷人才寢陋，兼無德行。昭宗惡其濫進，率先黜落，由是怨望，专幸邦國之灾。其父循奸邪附會，無譽於時，故希旨苟進。梁祖識其险詖，滋不悅，時為敬翔、李振所鄙。梁祖建號，詔曰：\"蘇楷、高貽休、萧聞禮皆人才寢陋，不可尘污班行，併停見任，放歸田里。蘇循可令致仕。\"河朔人士目蘇楷為衣冠土枭。莊宗年十一，從晉王讨王行瑜，初令入觐獻捷，昭宗一見駭異之，曰：\"此子有奇表。\"乃撫其背曰：\"我兒將來之國棟，勿忘忠孝於吾家。\"乃賜鸂鶒酒巵、翡翠盤。十三讀《春秋》，略知大義，騎射絕倫，其心豁如，采錄善言，聽納容物，殆劉聰之比也。又雲昭宗曰\"此子可亚其父\"，時人號曰\"亚子\"。","sortOrder":11},
  {"id":"s_work_bmtn_19_12","chapterId":"ch_work_bmtn_19","text":"鄴王羅紹威喜文學，好儒士，每命幕客作四方書檄，小不稱旨，坏裂抵弃，自劈箋起草，下筆成文。又癖於七言詩，江東有羅隱，為錢鏐客，紹威申南阮之敬。隱以所著文章詩賦酬寄，紹威大傾慕之，乃目其所為詩集曰《偷江東》，今鄴中人士多有諷誦。","sortOrder":12},
  {"id":"s_work_bmtn_19_13","chapterId":"ch_work_bmtn_19","text":"魏博富雄，列侯专地，唐朝三百年唯姑息之。羅紹威憤衙軍製己，密聞梁祖，表里應接算殺之。楊師厚後入魏城揖出羅周翰，因而代之。師厚卒，梁以贺德倫領镇，分其土宇，創立相貝為節镇，减其力用。三軍作亂，胁持德倫，背梁歸晉。其状詞雲：\"屈原哀郢，本非怨望之人；樂毅辭燕，且異傾邪之行。\"晉王覽状，擁兵親臨，先數張彦胁主虐民罪而斬之，便以張彦親軍五百人帶甲持仗，環馬而行。晉王宽衣缓帶，略無猜間，眾心大服。它日，資魏博兵力稱健，竟平河南也。衙軍自羅紹威殺戮後，又迫胁贺德倫，复擁兵持趙在禮。天成初赴行在，於時又殺三千家，乃世袭凶惡也。","sortOrder":13},
  {"id":"s_work_bmtn_19_14","chapterId":"ch_work_bmtn_19","text":"晉王之入魏博，梁將劉鄩先屯洹水，寂若無人。因令觇之，雲：\"城上有旗幟來往。\"晉王曰：\"劉鄩一步一計，未可輕進。\"更令審探，果縛刍為人，插旗於上，以驢負之，循堞而行，故旗幟婴城不息。問城中贏老者，曰：\"軍去已二日矣。\"果趨黃泽，欲寇太原，以霖潦不克進，其計謀如是。","sortOrder":14},
  {"id":"s_work_bmtn_20_1","chapterId":"ch_work_bmtn_20","text":"●卷十八","sortOrder":1},
  {"id":"s_work_bmtn_20_2","chapterId":"ch_work_bmtn_20","text":"莊宗異母弟存乂，即郭崇韜女婿，伏誅。先是，郭崇韜既誅之後，朝野駭惋，議論紛然。莊宗令閹人察訪外事，言存乂於諸將坐上訴郭氏之無罪，其言怨望，又於妖術人楊千郎家飲酒聚會，攘臂而泣。楊千郎者，魏州賤民，自言得墨子術於婦翁，能役使陰物，帽下召食物果實之類。又蒱博必勝，人有拳握之物，以法必取。又說煉丹乾汞，易人形，破扃鐍，貴要間神奇之。官至尚書郎，賜紫，其妻出入宮禁，承恩用事，皇弟存乂常朋淫於其家，至是與存乂同罹其禍。","sortOrder":2},
  {"id":"s_work_bmtn_20_3","chapterId":"ch_work_bmtn_20","text":"後唐明宗皇帝微時隨蕃將李存信巡邊，宿於雁門逆旅。逆旅媪方娠，帝至，媪慢，不時具食，腹中兒語謂母曰：\"天子至，宜速具食。\"聲聞於外，媪異之，遽起親奉庖爨，敬事尤謹。帝以媪前倨後恭，詰之。曰：\"公貴不可言也。\"問其故，具道娠子腹語事。帝曰：\"老嫗遜言，懼吾辱耳。\"後果如其言。","sortOrder":3},
  {"id":"s_work_bmtn_20_4","chapterId":"ch_work_bmtn_20","text":"明宗始在軍中居常，唯治兵仗，不事生產。雄武謙和，臨财尤廉，家财屢空，處之晏如也。太祖欲试以誠，召於泉府，命恣意取之，所取不過束帛數缗而已。所得賜與必分部下。戰勝凯還，儕類自伐，帝徐言曰：\"人戰以口，我戰以手。\"眾皆心服其能。","sortOrder":4},
  {"id":"s_work_bmtn_20_5","chapterId":"ch_work_bmtn_20","text":"莊宗晏駕，明宗皇帝為將相推舉，霍彦威、孔循上言唐運已衰，請改國號。明宗謂藩邸近侍曰：\"何為改正朔\"左右奏曰：\"先帝以錫氏宗屬為唐雪冤仇，為昭宗皇帝後，國號唐。今朝之舊人不欲殿下稱唐，請更名號耳。\"明宗泣下，曰：\"吾十三事獻祖洎太祖至先帝，冒刃血戰，為唐室雪冤，身編宗屬。武皇功業即吾功業也，先帝天下即吾天下也。兄亡弟紹，於意何嫌運之衰隆，吾當身受。\"於是不改正朔，人服帝之獨見也。","sortOrder":5},
  {"id":"s_work_bmtn_20_6","chapterId":"ch_work_bmtn_20","text":"趙在禮作亂，諸將擁明宗入闕，未到間，從馬直郭從謙攻興教門，帝母弟存渥從上戰。及宮車晏駕，存渥與劉皇後同奔太原。至風穀，為部下所殺，劉皇後欲出家為尼，旋亦殺之。存霸先除北京留守，亦自河中至太原。兵眾請殺存霸以安人心，符彦超不能禁，時存霸已翦發，衣僧衣謁彦超，願為山僧，竟不免也。存紀、存確匿於南山民家，人有以報安重誨。重誨曰：\"主上已下詔尋訪帝之仁德，必不加害，不如密旨殺之。\"果併命於民家。後明宗聞之，切讓重誨，傷惜久之。","sortOrder":6},
  {"id":"s_work_bmtn_20_7","chapterId":"ch_work_bmtn_20","text":"莊宗劉皇後，魏州成安人，家世寒微。太祖攻魏州，取成安得後，時年五六歲。歸晉陽宮，為太後侍者，教吹笙。及笄，姿色絕眾，聲伎亦所長，太後賜莊宗，為韓國夫人侍者。後誕皇子繼岌，寵待日隆。它日，成安人劉叟詣鄴宮見上，稱夫人之父。有內臣劉建丰認之，即昔日黃須丈人，後之父也。劉氏方與嫡夫人爭寵，皆以門族夸尚，劉氏恥為寒家，白莊宗曰：\"妾去乡之時，妾父死於亂兵，是時環尸而哭。妾固無父，是何田舍翁诈伪及此\"乃於宮門笞之。其實後即叟之長女也。莊宗好俳優，宮中暇日，自負蓍囊藥箧，令繼岌破帽相隨，似後父劉叟以医卜為業也。後方晝眠，岌造其臥內，自稱劉衙推訪女，後大恚，笞繼岌。然為太後不禮，复以韓夫人居正，無以發明，大臣希旨請册劉氏為皇後。議者以後出於寒賤，好興利聚财。初在鄴都，令人設法稗販，所鬻樵蘇果茹亦以皇後為名。正位之後，凡貢奉先入後宮，唯寫佛經施尼師，它無所賜。闕下諸軍困乏，以至妻子饿殍，宰相請出內库給，後將出妆具銀盆兩口，皇子滿喜等三人令鬻以贍軍。一旦作亂，亡國滅族，與夫褒姒、妲己無異也先是，莊宗自為俳優，名曰李天下，雜於涂粉優雜之間，時為諸優朴扶摑搭，竟婦恩伶之傾玷，有國者得不以為前鑒劉後以囊盛金合犀帶四欲於太原造寺為尼，沿路复通皇弟存渥，同箦而寢。明宗聞其秽，即令自殺。","sortOrder":7},
  {"id":"s_work_bmtn_20_8","chapterId":"ch_work_bmtn_20","text":"明宗即位之初，誅租庸使孔謙、歸德軍節度使元行钦、邓州節度溫韜、太子少保段凝、汴州曲務辛廷蔚、李繼宣等。孔謙者，魏州孔目吏，莊宗圖霸以供饋兵食，謙有力焉。既為租庸使，曲事嬖幸，奪宰相權，专以聚斂為意，剝削萬端，以犯眾怒，伏誅。元行钦為莊宗愛將，出入宮禁曾無間隔，害明宗之子從璟，以是伏誅。段凝事梁以奸佞進身至節將，末年綰軍權，束手歸朝。溫韜凶惡，發掘西京陵寢，莊宗中興，不寘其罪。厚賂伶官閹人，與段凝皆賜國姓，或擁旄鉞。明宗采眾議而誅之。辛廷蔚，开封尹王瓒之牙將也，朱友貞時廷蔚依瓒势，曲法亂政，汴人惡之。李繼宣，汴將孟審澄之子，亡命歸莊宗，劉皇後蓄為子。時宮掖之間秽聲流聞，此四凶帝在藩邸時惡其為人，故皆誅之。莊宗皇帝為唐雪恥，號為中興，而溫韜毀發諸帝寢陵，宣加大辟，而賜國姓，付節旄，由是知中興之說谬矣。","sortOrder":8},
  {"id":"s_work_bmtn_20_9","chapterId":"ch_work_bmtn_20","text":"莊宗皇帝嫡夫人韓氏後為淑妃，伊氏為德妃。契丹入中原，石氏乞降，宰相冯道尊册契丹主，大張宴席，其國母後妃列坐同宴，王嫱、蔡姬之比也。夫人夏氏最承恩寵，後嫁契丹突欲名李贊華，所謂東丹王，即阿保機長子。先歸朝，後除滑州節度使，性酷毒，侍婢微過即以刀刲火灼。夏氏少長宮掖，不忍其凶，求離婚，歸河陽節度夏魯奇家，今為尼也。","sortOrder":9},
  {"id":"s_work_bmtn_20_10","chapterId":"ch_work_bmtn_20","text":"亂離以來，官爵過濫，封王作辅，狗尾續貂。天成初，桂州節度觀察使馬爾即湖南馬殷之弟，本無功德，品秩已高，製詞雲：\"爾名尊四辅，位冠三師。既非品秩升遷，難以井田增益。\"此要語也。議者以名器假人至此，贾誼所以長叹息也。","sortOrder":10},
  {"id":"s_work_bmtn_20_11","chapterId":"ch_work_bmtn_20","text":"明宗入纂，安重誨用事，取謀於孔循。舊相豆盧革、韦說出官，孔循不欲以河朔人入相，極荐崔协，而任圜力爭之，雲：\"崔协者，少識文字，時人呼為無字碑。有李琪者，學际天人，奕代軒冕，論才校藝可敵時辈百人，讒夫巧沮，忌害其能。必舍李琪而相崔协，如弃蘇合之丸取蛣蜣之轉也。\"重誨笑而止。然以孔循故終相之，帝曰：\"冯書記先帝判官，與物無競，可以相矣。\"由是道與协併命而舍李琪，識者惜之。","sortOrder":11},
  {"id":"s_work_bmtn_20_12","chapterId":"ch_work_bmtn_20","text":"明宗遣皇子從榮出镇鄴都。或一日，上謂安重誨曰：\"從榮左右有诈宣朕令旨不接儒生。儒生多懦，恐钝志相染。朕方知之，頗駭其事。今此皇子方幼，出臨大藩，故選儒雅，賴其裨佐。今聞此奸险，豈朕之所望也\"鞫其言者將戮之。重誨曰：\"若遽行刑，又慮賓從聞後稍難安處，且望嚴戒。\"遂止。","sortOrder":12},
  {"id":"s_work_bmtn_20_13","chapterId":"ch_work_bmtn_20","text":"明宗皇帝尤惡貪货。邓州留後陶己為內乡縣令成歸仁所論稅外科配，貶岚州司馬，掌書記王惟吉奪歷任告敕，配綏州，長流百姓。亳州剌吏李鄴以贓秽賜自盡。面戒汝州刺史萇蕳，為其貪暴。汴州仓吏犯贓，內有史彦珣，舊將之子，又是駙馬石敬瑭親戚，王建立奏之，希免死。上曰：\"王法無私，豈可徇親\"由是皆就戮。","sortOrder":13},
  {"id":"s_work_bmtn_20_14","chapterId":"ch_work_bmtn_20","text":"缑氏縣令裴彦文事母不謹，誅之。襄邑人周威父為人所殺，不雪父冤，有状和解，明宗降敕賜死。","sortOrder":14},
  {"id":"s_work_bmtn_20_15","chapterId":"ch_work_bmtn_20","text":"任圜崑弟五人，曰圜、圓、圖、回、团，雍穆有裕，風采俱異。圜美姿容，有口辨，負筹略，平蜀後除黔南不行。天成初入相，簡拔賢俊，杜絕幸門，忧國如家，切於功名，而安重誨忌之。常會於私第，有妓善歌，重誨求之不得，嫌隙漸深。俄罢三司，除太子太保，歸磁州致仕。因朱守殷作亂，立遣人稱製害之。受命之日，神氣不撓，中外冤痛。清泰中赠右仆射。","sortOrder":15},
  {"id":"s_work_bmtn_21_1","chapterId":"ch_work_bmtn_21","text":"●卷十九","sortOrder":1},
  {"id":"s_work_bmtn_21_2","chapterId":"ch_work_bmtn_21","text":"太傅致仕趙光逢仕唐及梁，薨於天成中，文學德行，風神秀異，號曰\"玉界尺\"。扬歷台省，入翰林御史中丞，梁時同平章事。時以兩登廊廟，四退丘園，百行五常，不欺暗室，縉紳仰之。","sortOrder":2},
  {"id":"s_work_bmtn_21_3","chapterId":"ch_work_bmtn_21","text":"周玄豹，燕人，少為僧，其師有知人之鑒，從遊十年，不憚辛苦，遂傳其秘，還乡歸俗。盧澄為道士，與同志三人謁之，玄豹退謂人曰：\"適二君子，明年花發俱為故人，唯彼道士它年甚貴。\"來歲二人果睹零落，盧果登庸。後歸晉陽，張承業猶重之，言事多中。承業俾明宗易衣列於諸校之下，以它人請之，曰：\"此非也。\"玄豹指明宗於末缀曰：\"骨法非常，此為內衙太保乎？\"或問前程，唯雲\"末後為镇帥\"。明宗夏皇後方事巾櫛，有時忤旨，大犯檟楚。玄豹曰：\"此人有藩侯夫人之相，當生貴子。\"其言果验。凡言吉凶，莫不神中，事多不載。明宗自镇帥入纂，謂侍臣曰：\"周玄豹昔曾言朕事，頗有征，可詔北京津置赴闕。\"趙鳳曰：\"袁許之事，玄豹所長。若詔至輦下，即爭問吉凶，恐近於妖惑。\"乃令就賜金帛，官至光祿卿，年八十而終。","sortOrder":3},
  {"id":"s_work_bmtn_21_4","chapterId":"ch_work_bmtn_21","text":"禮部尚書崔貽孫年過八十，求進不休，囊橐之資素有貯積，性好幹人，喜得小惠。左降之後，二子爭财，甘旨医藥鹹不供侍。書责其子曰：\"生有明君真宰，死有天曹地府。無為老朽，豈放爾邪。\"為縉紳之笑端。","sortOrder":4},
  {"id":"s_work_bmtn_21_5","chapterId":"ch_work_bmtn_21","text":"道士解元龟，本西蜀節將下軍校。明宗入纂，言自西來，對於便殿，進詩歌聖德，自稱太白山正一道士，上表乞西都留守兼三川製置使，要修西京宮闕。上謂侍臣曰：\"此老耄自遠來朝，所期別有異見，乃為身名甚切，堪笑也！\"時號\"知白先生\"，賜紫，斯乃狂妄人也。","sortOrder":5},
  {"id":"s_work_bmtn_21_6","chapterId":"ch_work_bmtn_21","text":"天成中，有僧於西國取經回，得一佛牙舍利十粒，行以呈上。進其牙，大如拳，褐潰皴裂。趙鳳言於執政曰：\"曾聞佛牙錘鍛不坏，請试之。\"隨斧而碎，時宮中已施數千，聞毀碎，方遂擯弃之雲雲。此僧號智明，幽州人，仆嘗識之。","sortOrder":6},
  {"id":"s_work_bmtn_21_7","chapterId":"ch_work_bmtn_21","text":"明宗問宰相冯道：\"盧质近日吃酒否\"對曰：\"质曾到臣居，亦飲數爵。臣勸不令過度，事亦如酒，過即患生。\"崔协強言於坐曰：\"臣聞食医心鏡，酒極好，不假藥餌，足以安心神。\"左右見其膚淺，不覺哂之。","sortOrder":7},
  {"id":"s_work_bmtn_21_8","chapterId":"ch_work_bmtn_21","text":"五台山僧誠慧，其徒號為降龍大師。镇州大水，坏其南城，誠慧曰：\"彼無信心，吾使一小龍警之。\"自言能役使毒龍故也。同光初到闕，權貴皆拜之，唯郭崇韜知其為人，終不設拜。京師旱，迎至洛下祈雨，數旬無征應。或以焚燎為聞，懼而潛去。至寺慚恚而終，建塔號法雨大師，何其谬也！","sortOrder":8},
  {"id":"s_work_bmtn_21_9","chapterId":"ch_work_bmtn_21","text":"泽州僧洪密請舍利塔，洪密以禪宗謎語鼓扇愚俗，自雲身出舍利。曾至太原，豪民迎請，婦人羅拜。洪密既辭，婦人於其所坐之處拾得百粒人验之，皆枯魚之目也。將辭，雲山中要千數番粗氈，半日獲五百番。其惑人如此。","sortOrder":9},
  {"id":"s_work_bmtn_21_10","chapterId":"ch_work_bmtn_21","text":"阆州守御指揮使姚洪梁時經事董璋，璋將書頻誘，洪以大義拒之。城陷被擒，璋责之，洪大骂璋曰：\"老賊孤恩背主，吾於爾何恩而雲相負爾為李七郎奴，扫馬粪得一脔殘炙，感恩無盡。今天子付以茅土，結党反噬，爾本奴才，即無恥。吾忠義之士，不忍為也。\"璋怒令十人持刀割其膚，然镬於前，自取啖食。洪至死大骂不已。明宗聞之泣下，置洪二子於近衛，給賜頗優。於時夏魯奇守遂州，城破自刎而死，併為忠烈也。","sortOrder":10},
  {"id":"s_work_bmtn_21_11","chapterId":"ch_work_bmtn_21","text":"封舜卿梁時知貢舉，後門生鄭致雍同受命入翰林為學士。致雍有俊才，舜卿才思拙涩。及试五題，不勝困弊，因托致雍秉筆。當時議者以為座主辱門生。同光初致仕。","sortOrder":11},
  {"id":"s_work_bmtn_21_12","chapterId":"ch_work_bmtn_21","text":"萧希甫進士及第，有文才口辨，多機數。梁時不得意，弃母妻渡河，易姓名為皇甫教書。莊宗即位於魏州，征希甫知製誥。莊宗平汴洛，希甫奉詔宣慰青齊，方知其母死妻嫁，乃持服於魏州。時議者戲引李陵書雲：\"老母終堂，生妻去室。\"後為諫議大夫，性褊忿，躁於進取，疏宰相豆盧革、韦說至於貶死，又以毀訾宰臣，责授岚州司馬。","sortOrder":12},
  {"id":"s_work_bmtn_21_13","chapterId":"ch_work_bmtn_21","text":"明宗謂侍臣曰：\"冯道純俭，頃在德勝寨，所居一茅庵，與從人同器而食。臥則刍藁一束，其心晏如。及以父忧退歸乡里，自耕耘樵采，與農夫雜處，不以素貴介懷，真士大夫也！\"","sortOrder":13},
  {"id":"s_work_bmtn_21_14","chapterId":"ch_work_bmtn_21","text":"明宗戒秦王從榮曰：\"吾少鐘丧亂，馬上取功名，不暇留心經籍。在藩邸時，見判官論說經義，雖不深達其旨，大約令人开悟。今朝廷有正人端士，可親附之，庶幾有益。吾見先皇在藩時愛自作歌詩，將家子文非素習，未能盡妙，諷於人口，恐被諸儒竊笑。吾老矣，不能勉強於此，唯書義尚欲耳里頻聞。\"時從榮方聚雜進士浮薄之子以歌詩吟詠為事，上道此言規諷之。或一日，秦王進詩，上說於俳優敬新磨，敬新磨贊美而曰：\"勿訝秦王詩好，他阿爺平生愛作詩。\"上大笑。","sortOrder":14},
  {"id":"s_work_bmtn_21_15","chapterId":"ch_work_bmtn_21","text":"宰相冯道形神庸陋，一旦為丞相，士人多竊笑之。劉嶽與任贊偶語，見道行而复顧，贊曰：\"新相回顧，何也\"嶽曰：\"定是忘持《兔園册》來。\"道之乡人在朝者聞之，告道。道因授嶽秘書監、任贊授散騎常侍。北中村墅乡以《兔園册》教童蒙，以是譏之。然《兔園册》乃徐庾文體，非鄙朴之談，但家藏一本，人多賤之也。","sortOrder":15},
  {"id":"s_work_bmtn_21_16","chapterId":"ch_work_bmtn_21","text":"涇原帥李金全累歷藩镇，所在掊斂。非時進馬，上問其為治如何，莫专以進馬為事。雖黾勉受之，聖旨不怿。張虔钊多貪，镇沧州日，因亢旱民飢，發廪赈之。方上聞，帝甚嘉奖。它日秋成，倍斗征斂。常言自覺言行相违，然每見财不能自止朝論鄙之。虔钊好與禪毳謎語，自雲知道，心與口背，唯利是求，只以飯僧，更希福利。議者以渠於佛上希利，愚之甚也。後叛入蜀，取人產業，黷货無厭，蜀民怨之。或說在蜀問一禪僧雲：\"如何是舍利\"對曰：\"垂置僦居即得舍利。\"清河慚笑而已。","sortOrder":16},
  {"id":"s_work_bmtn_21_17","chapterId":"ch_work_bmtn_21","text":"大理少卿康澄長興中上疏，其要雲：\"是知國家有不足懼者五，深可畏者六。\"敕旨褒稱之。議者曰：\"雖孫伏伽、岑文本章疏，而澄可與易地而處矣。\"","sortOrder":17},
  {"id":"s_work_bmtn_21_18","chapterId":"ch_work_bmtn_21","text":"孟鵠自三司勾押官歷許州節度使，上曰：\"鵠掌三司幾年得至方镇？\"枢密使范延光奏對，上曰：\"鵠實幹事人，以此至方镇，爭不勉旃？\"上心知其由径忝冒，故以此諷也。","sortOrder":18},
  {"id":"s_work_bmtn_21_19","chapterId":"ch_work_bmtn_21","text":"供奉官丁延徽巧事權貴，人多擁護。監仓犯贓，合處極法，侍衛使張從賓方便救之。上曰：\"食我厚祿，偷我仓储，期於决死。蘇秦說吾不得，非但卿言。\"竟處死。","sortOrder":19},
  {"id":"s_work_bmtn_22_1","chapterId":"ch_work_bmtn_22","text":"●卷二十","sortOrder":1},
  {"id":"s_work_bmtn_22_2","chapterId":"ch_work_bmtn_22","text":"上問范延光見管馬數，對曰：\"見管馬軍三萬五千。\"上撫髀叹曰：\"朕從戎四十年，太祖在太原時騎軍不過七千，先皇帝與汴軍校戰，自始至終馬數才萬。今有鐵馬三萬五千，不能使九州混一，是吾養卒練士將帥之不至也。老者馬將奈何\"延光以馬數多，國力虛耗為言，上亦然之。","sortOrder":2},
  {"id":"s_work_bmtn_22_3","chapterId":"ch_work_bmtn_22","text":"镇州士人劉方遇家财數十萬，方遇妻田氏蚤卒，田之妹為尼，常出入方遇家，方遇使尼長發為繼室。有田令遵者，方遇之妻弟也，善货殖，方遇以所積财令令遵興殖也。方遇有子年幼，二女皆嫁。方遇疾卒，子幼不能督家業，方遇妻及二女以家财素為令遵興殖，乃聚族合謀，請以令遵姓劉為方遇繼嗣。即令鬻券人安美為親族請嗣。券書既定，乃遣令遵服斬衰居丧。而二女初立令遵時，先邀每月供财二萬，及後求取無厭，而石、李二女夫教二女詣本府論訴，雲\"令遵冒姓奪父家财\"。令遵下獄，石、李二夫族與本府要吏親党，上至府帥、判官、行軍司馬、隨使都押衙，各受方遇二女賂錢數千缗，而以令遵與姊及書券安美同情共盜，俱弃市。人知其冤。府帥李從敏令妻來朝，懼事發，令內地弥縫。侍御史趙都嫉惡論奏，明宗驚怒，下镇州，委副使符蒙按問，果得事實，自親吏高知柔及判官、行軍司馬及通货僧人、婦人皆弃市，惟從敏初欲削官停任，中宮哀祈，竟罰一季俸。議者以受賂曲法殺人，而八議之所不及，失刑也。","sortOrder":3},
  {"id":"s_work_bmtn_22_4","chapterId":"ch_work_bmtn_22","text":"冯道對：\"太子食，有邪蒿，師傅以其名邪，令去之，况人事乎。\"上退，問群臣\"邪蒿\"之義，范延光對：\"無名之役，不急之務，且宜罢之。\"自安重誨伏誅，而宦者孟漢琼連宮掖之势，居中用事，人皆憚之。因宰臣奏對，延光等深言\"邪蒿\"、\"春冰\"、\"虎尾\"之戒，欲驚悟上意也。上聖體乖和，冯道對寢膳之間，動思調衛，因指御前果實曰：\"如食桃不康。翌日見李而思戒可也。\"初上因御李暴得風虛之疾，冯道不敢斥言，因奏事諷悟上意。","sortOrder":4},
  {"id":"s_work_bmtn_22_5","chapterId":"ch_work_bmtn_22","text":"秦王從榮之為元帥，輕佻淺露，狎近浮薄，列坐將帥而與判官論詩，未跻大位而許人禍福。由是中外忌憚，竟及誅败。上聞從榮伏誅，悲駭幾落御榻，氣絕复蘇者再，由是不豫轉增，以至晏駕，自雲：\"我今日自作劉窟頭也。\"","sortOrder":5},
  {"id":"s_work_bmtn_22_6","chapterId":"ch_work_bmtn_22","text":"吳興沈徽，乃溫庭筠諸甥也，嘗言其舅善鼓琴吹笛，亦雲有絃即彈，有孔即吹，不獨柯亭爨桐也。\"製《曲江吟》十調，善雜畫，每理發則思來，辄罢櫛而缀文也。有溫顗者，乃飛卿之孫，憲之子。仕蜀，官至常侍。無它能，唯以隱僻繪事為克紹也。中間出官，旋遊臨邛，欲以此獻於州牧，為謁者拒之。然溫氏之先貌陋，時號鐘馗。顗之子郢，魁形，克肖其祖，亦以奸秽而流之。","sortOrder":6},
  {"id":"s_work_bmtn_22_7","chapterId":"ch_work_bmtn_22","text":"薑志，許昌人，自小亂離，失其父母。爾後仕蜀，至武信軍節度使。先是，廄中圉人薑春者事之多年，頻罹鞭扑，一旦告老於國夫人，請免馬廄之役，而丐食於道路。夫人愍之，詰其乡貫姻親，兼雲\"有一子，隨軍入川，莫知存亡\"，其小字、身上記验一一述之，果志之父也。洎父子相認，悲號殒絕。志乃授父杖，俾笞其背，以偿昔日所誤之事。舉國嗟叹之。此事川蜀皆知。","sortOrder":7},
  {"id":"s_work_bmtn_22_8","chapterId":"ch_work_bmtn_22","text":"唐四方馆主王晉阝尚書自西京亂離，挈家入蜀，沿嘉陵江下，至利州百堂寺前。其弟年七歲，忽雲：\"我曾有經一卷，藏在此寺石龛內。\"因令家人相隨訪獲之，木梳亦存。寺僧曰：\"此我童子也。\"较其所夭之年與王氏之子所生之歲果验也。其前生父母尚存。及長，仕蜀，官至令錄數任，即王鄂。","sortOrder":8},
  {"id":"s_work_bmtn_22_9","chapterId":"ch_work_bmtn_22","text":"舒溥者，萬州人，粗解書記，事前恩州刺史李希玄往廣州謁嗣薛王，歸裝甚丰。於時蜀兵部毛文晏侍郎、宣徽宋光葆开府、前陵州王洪使君皆未宦達，舒子竊資而奉之。爾後三人繼登顯秩，而恃此階緣，多行無禮於恩牧，因笞而遣之。始依陵州王洪，奏授井研令，尋為王公所鄙。次依宋开府，亦以不恭見弃。轉荐於嘉牧顧珣，珣承奉貴近，誤奏為团練判官，賜緋，轉員外郎。未久失意，复疏之，俾其入貢，仍假一表希除畿邑，實要斥遠之。邸吏知意，表竟不行。淹留經年，乃詣堂陳状，只望本分入貢之恩泽。朝廷以其北面因依，莫测本末，優與擬議，轉檢校工部郎。所謂三斥三遇也。愚嘗覽吳武陵為李吉甫相所誤致及第，因類而附之。","sortOrder":9},
  {"id":"s_work_bmtn_22_10","chapterId":"ch_work_bmtn_22","text":"杜何博士，相國駙馬悰之子，仕蜀至五轉無它才俊，止以貴公子享俸祿而已。恥其官卑，詣執政陳啟自述門閥，其末雲：\"昔年入貢，仕在花树韦吏部先德之前；今日通班，在新津冯長官小男之後。\"執政愍而慰之。有高諷者，自雲太尉諸孫，羁旅三川而多忤物，每叹求官不遂，遍告人曰：\"何不還我羅城來\"蓋以掌武所筑，蜀人安之。其疏闊皆如此也。","sortOrder":10},
  {"id":"s_work_bmtn_22_11","chapterId":"ch_work_bmtn_22","text":"韦巽，太尉昭度之子也，尫懦蒙钝，率由婢嫗。仕蜀，先主以其事舊優容之，以至卿監。或為同列所譏雲：\"三公門前出死狗。\"巽曰：\"死狗門前出三公。\"又能酬酢也。周仁矩者，即蜀相庠之子，為駙馬都尉，有才藻而庸劣。國亡後與貧丐者為伍，俾一人先道爵里於市肆酒坊之間，人有哀者，日獲三二百錢，與其徒飲啖而已。成都人皆嗟叹之。","sortOrder":11},
  {"id":"s_work_bmtn_22_12","chapterId":"ch_work_bmtn_22","text":"唐鳳翔李嚴令公收蜀，充饋運使，於蜀城東門外下營。魏王與郭侍中入居蜀宮，玉帛子女它人無复見矣。中令寂寞，無以遣適。潁川陳昭符仕蜀，累剖竹符，蚤在岐山，微有階緣，而得候謁，因求一美人以獻之。有萧夫人者，乃蜀先主之寵愛也，曾賜與鳳翔歸降指揮使王胡，賜名丞弇。王胡乃岐王賜姓，連彦字，卒後萧氏寡而無子。其容態明悟，國人具聞。陳致媒氏誘之而獻，抱衾之夕，中令於窗隙中窥之，叹其妍妙，乃詰所來，左右方以王胡為對。中令止之曰：\"王胡背恩投蜀，誠不可容。然其向來吾之子侄矣，此事不可。\"遽令約回。時有知者皆重中令少年而忍欲复禮，誠貴達人難事。潁川每為愚話之。周彦章本姓王，以軍功為金吾衛使。後主采選宮妓，王有女甚美，因命內人欲選入宮。王乃按劍曰：\"某是先皇令與周氏作義男，本姓王，為眾所聞也，豈有王氏女而事王氏乎？\"因召左右小軍將無婦者以女衣襟結之，便為夫妻。爾後國变，王乃領兵於大安樓前胁後主誅君侧韓昭等，即其事也。","sortOrder":12},
  {"id":"s_work_bmtn_22_13","chapterId":"ch_work_bmtn_22","text":"王蜀時阆州人何奎，不知何術而言事甚效，既非卜相，人號何見鬼，蜀之近貴鹹神之。鬻銀之肆有患白癩者，傳於兩世矣。何見之，謂曰：\"爾所苦，我知之矣。我為嫁娉少環钏釵篦之屬，爾能致之乎即所苦立愈矣。\"白癩者欣然許之。因謂曰：\"爾家必有它人舊功德或供養之具存焉。亡者之魂無依，故遣為此祟。但去之必瘳也。\"患者歸视功德堂內本無它物，忖思久之，老母曰：\"佛前紗窗乃重围時它人之物，曾取而置之，得非此乎？\"遽令撤去，仍修斋忏，其疾遂痊，竟受其鐶钏之赠。何生未遇，不汲汲於官宦。末年祈於大官，自布衣除興元少尹，金紫，兼妻邑號，子亦賜緋。不之任，便歸阆州而卒，預知死期也。雖術數通神，而名器逾分，識者知後主之政悉此類也。","sortOrder":13},
  {"id":"s_work_bmtn_22_14","chapterId":"ch_work_bmtn_22","text":"嘉州夹江縣人孫雄，人號孫卵斋，其言事亦何奎之流。伪蜀主歸命時，內官宋愈昭將軍數員舊與孫相善，亦神其術，將赴洛都，鹹問其將來升沉。孫俯首曰：\"諸官記之，此去無灾無福，但行及野狐泉已來稅駕處曰'孫雄非聖人耶'，此际新舊使頭皆不見矣。\"諸官皆疑之。爾後量其行邁，合在鹹京左右，後主罹伪詔之禍，莊宗遇鄴都之变，所謂新舊使頭皆不得見之验也。愚同席備見說，故記之。","sortOrder":14},
  {"id":"s_work_bmtn_22_15","chapterId":"ch_work_bmtn_22","text":"遂寧有冯見鬼，似有所睹，知人吉凶。潁川陳絢為武信軍留後，而劉令公知俊交替，摭其舊事，叠有奏論。冯生謂潁川曰：\"府主雖號元戎，前無旌節所引，殆不久乎。幸勿忧也。\"未逾歲而彭城伏誅。有官人林泳者，本閩人也，嘗謂僚友曰：\"安有生人而終日見鬼乎無聽其妖。\"冯聞之甚不平。或一日，對眾謂之曰：\"閣下為官多不克終，蓋曾殺一女人為祟，以公祿寿未盡，莫致其便。我能言其姓名，公信之乎？\"於是慚懼言誠於冯生，許為解其冤也。它皆類此。","sortOrder":15},
  {"id":"s_work_bmtn_22_16","chapterId":"ch_work_bmtn_22","text":"沙門貫休，鐘離人也，風骚之外精於筆劄，舉止真率，誠高人也。然不晓時事，往往詆訐朝賢，它亦不知己之是耶非耶。荆州成中令問其筆法非耶，休公曰：\"此事須登壇而授，非草草而言。\"成令衔之，乃遽於黔中因病以鶴詩寄意曰：\"見說氣清邪不入，不知爾病自何來。\"以詩見意也。冯涓大夫有大名於人間，淪落於蜀，自比杜工部，意謂它人無出其右。休公初至蜀，先謁韦書記莊，而長樂公後至，遂與相見，欣然撫掌曰：\"我與你阿叔有分。\"長樂怒而拂袖。它日謁之竟不逢迎，乃曰：\"此阿師似我禮拜也。\"自是頻投刺字，終為閽者所拒。休公謂韦公曰：\"我得得為渠入蜀，何意見怪\"國清寺律僧嘗許具蒿脯，未得間，薑侍中宅有斋，律僧先在焉，休公次至，未揖主人大貌，乃拍手謂律僧曰：\"乃蒿餅子何在\"其它皆此類。通衢徒步，行嚼果子，未嘗跨馬，時人甚重之，異乎廣宣、栖白之流也。","sortOrder":16},
  {"id":"s_work_bmtn_23_1","chapterId":"ch_work_bmtn_23","text":"●逸文卷一","sortOrder":1},
  {"id":"s_work_bmtn_23_2","chapterId":"ch_work_bmtn_23","text":"唐乾寧中，雲安縣漢城宮道士楊雲外常以酒自晦，而行止異常。前進士錢若愚甚敬之，一旦，斋沐詣其山觀，宿於道斋。翌日，虔誠斂衽而白之曰：\"師丈，小子凡鄙，神仙之事雖聆其說，果有之乎？\"楊曰：\"有之，我即其人也。若示以飛空躡虛、履水蹈火，即日有千萬人就我，不亦煩亵乎？\"因騰躍上升，冉冉在空中，良久而下。若愚稽顙，自是信有神仙矣。","sortOrder":2},
  {"id":"s_work_bmtn_23_3","chapterId":"ch_work_bmtn_23","text":"唐天复中，成汭镇江陵，監軍使張特進元隨溫克修司藥库，在坊郭稅舍止焉。張之門人向隱北鄰，隱攻歷算，仍精射覆，無不中也。一日，白張曰：\"特進、副監、小判官已下皆帶灾色，何也\"張曰：\"人之年運不同，豈有一時受灾，吾不信矣。\"於時城中多犬吠，隱謂克修曰：\"司馬元戎某年失守，此地化為邱墟，子其志之。\"他日复謂克修曰：\"此地更变，且無定主，五年後東北上有人，依稀國親，一镇此邦，二十年不動。子志之。\"他日又曰：\"東北來者二十年後更有一人，五行不管，此程更遠。但請記之。\"溫以為凭虛，殊不介意。复謂溫曰：\"子他時婚娶無男，但生一队女也，到老却作医人。\"後果密敕誅北司，張特進與副監、小判官同日就戮，方验其事。成汭鄂渚失律不還，江陵為朗人雷滿所據。襄州舉軍奪之，以趙匡明為留後。大梁伐襄州，匡明弃城出奔，為梁將贺環所據，而威望不著，朗蠻侵凌，不敢出城，自固而已。梁主署武信王高季昌自潁州刺史為荆南兵馬留後，下車日，擁數騎至沙頭，朗軍慑懼，稍稍而退。先是，武信王賜姓朱，後复本姓，果符國親之說。克修失主，流落渚宮，收得名方，仍善修合，賣藥自給，亦便行医。娶婦後唯生數女，盡如向言。唐明宗天成二年丁亥，天軍围江陵，軍府懷忧，溫克修上城白文獻王，具道此。文獻未之全信。溫以前事累验，必不我欺。俄而朝廷抽軍，來年武信薨，凡二十一年。而文獻嗣位亦二十一年，迨至南平王，即\"此程更遠\"，果在茲乎。","sortOrder":3},
  {"id":"s_work_bmtn_23_4","chapterId":"ch_work_bmtn_23","text":"唐鳳州東穀有山人強紳，妙於三戒，尤精雲氣。屬王氏初亻併秦鳳，張黃於通衢，強公指而謂孫光憲曰：\"更十年，天子數員。\"又曰：\"併汾而來悠悠，梁蜀後何為哉！\"於時蜀兵初攻岐山，謂其旦夕屠之。強曰：\"秦王久思妄動，非四海之主。雖然，死於牖下乃其分也。蜀人終不能克秦，而秦川亦成邱墟矣。\"爾後大滷與王鳳翔不羁，秦王令終，王氏絕祚，果葉強生言。有鹿盧蹻術，自雲老夫耄矣，無人可傳，其書藏在深隱處古杉树中。因與孫光憲偕詣，开树皮，發蠟緘，取出一通絹書，選吉辰以授，為強嫗止之，謂\"孫少年也，慮致發狂。俾服膺三年，方議可否。\"","sortOrder":4},
  {"id":"s_work_bmtn_23_5","chapterId":"ch_work_bmtn_23","text":"唐彭濮間有相者彭克明，號彭釘筋，言事多验，人以其必中，是有釘筋之名。九隴村民唐氏子家富穀食，彭謂曰：\"唐郎即世，不掛一縷。\"唐氏曰：\"我家粗有田隴，衣食且丰，可能裸露而終哉？\"後一日，江水泛涨，潭上有一兔在水中央。唐謂必致之，乃脱衣泅水，無何，為迅波漂没而卒，所謂一縷不掛也。其他皆此類，繁而不載。","sortOrder":5},
  {"id":"s_work_bmtn_23_6","chapterId":"ch_work_bmtn_23","text":"伪蜀王先主時，有軍校黃承真就糧於廣漢綿竹縣，遇一叟曰鄭山古，謂黃曰：'此國於五行中少金氣，有剝金之號曰金煬鬼。此年蜀宮大火，至甲申、乙酉則殺人無數。我授汝秘術，詣朝堂陳之。傥行吾教以禳镇，庶幾减於殺伐。救活之功，道家所重延生，试於我而取之。然三陳此術如不允行，則子亦不免，蓋泄於陰機也。子能從我乎？\"黃亦好奇，乃曰：\"苟禀至言，死生以之。\"乃赍秘文詣蜀，三上不達，乃呕血而死。其大火與乙酉亡國殺戮之事果验。孫光憲與承真相識，竊得窥其秘緯，題雲《黃帝陰符》，與今陰符不同，凡五六千言\"黃雲受於鄭叟，一畫一點皆以五行屬配，通畅亹亹，實奇書也。然漢代數賢生於綿竹，妙於讖記之學，所雲鄭叟，豈黃扶之流乎。","sortOrder":6},
  {"id":"s_work_bmtn_23_7","chapterId":"ch_work_bmtn_23","text":"伪王蜀葉逢，少明悟，以詞筆求知，常與孫光憲偕詣術士馬處謙問命通塞。馬曰：\"四十已後方可圖之。未間苟或先得，於寿不永。\"於時州府交辟，以多故參差，不成其事。後充湖南通判官，未除官之前，夢見乘船赴任，江上候吏旁午而至，迎入石窟。覺後話於廣成先生杜光庭。次忽報敕下，授檢校水部員外郎。廣成曰：\"昨宵之夢，豈小川之謂乎。\"自是解維，覆舟於犍為郡青衣滩而死，即處謙之生知、葉逢之凶夢，何真效哉！光憲自蜀沿流，一夕夢葉生雲：\"子於青衣亦不得免。\"覺而異之。洎發嘉州，取陽山路，乘小舟以避青衣之险。無何，篙折，為迅流吸入青衣，幸而獲濟。豈鬼神尚能相戲哉。","sortOrder":7},
  {"id":"s_work_bmtn_23_8","chapterId":"ch_work_bmtn_23","text":"伪王蜀時，巫山高唐觀道士黃萬戶本巴東萬戶村民，學白虎七变術，又雲學六丁法於道士張君。常持一鐵鞭療疾，不以财物介懷。然好與乡人爭訟，州縣不之重也。戎州刺史文思辂亦有戲術，曾翦紙魚投於盆內而活，萬戶投符化獭而食之，其鐵鞭為文思辂收之，歸至涪州亡其鞭，而却歸黃矣。有楊希古，欲傳其術，坐未安，忽雲：\"子家中已有丧秽。\"不果傳。俄得家訃母亡。又蜀先主召入宮，列示諸子，俾認储後。萬戶乃指後主。其術他皆仿此。唯一女為巫山民妻，有男傳授秘訣。將卒戒家人勿殓。經七八日再活，不久却殒也。青城縣舊有馬和尚，宴坐三十五年，道德甚高。萬戶將卒，謂家人曰：\"青城馬和尚來，我遂長逝也。\"是年馬師亦遷化。","sortOrder":8},
  {"id":"s_work_bmtn_23_9","chapterId":"ch_work_bmtn_23","text":"秭歸郡草聖僧懷浚者，不知何處人，唐乾寧初到彼，知來藏往，皆有神验。愛草書，或經或釋或老，至於歌詩鄙琐之言，靡不集其筆端。與之語，即阿唯而已。里人以神聖待之，刺史幹公以其惑眾，系而詰之，乃以詩代通状曰：\"家在閩川西复西，其中歲歲有鶯啼。如今不在鶯啼處，鶯在舊時啼處啼。\"又詰之，复有詩曰：\"家住閩川東复東，其中歲歲有花紅。而今不在花紅處，花在舊時紅處紅。\"郡牧異而釋之。詳其詩意似在海中，得非杯渡之流乎行旅經過，必維舟而禮謁。告其吉凶，唯書三五行，終不明言，事往果验。荆南大校周崇賓謁之，書字遺之曰：\"付皇都勘。\"爾後入貢，因王師南讨，遂縶於南府，竟就戮也。押衙孫道能謁之，書字曰\"付竹林寺。\"其年物故，營葬乃古竹林寺基也。皇甫铉知州，乃畫一人荷校，一女子在旁。後為娶民家女遭訟，錮身入府。波斯穆昭嗣幼好藥術，隨其父謁之，乃畫一道士乘雲把胡盧，書雲\"指揮使高牒衙推\"。穆生後以医藥有效，南平王高從誨與巾裹，攝府衙推。王師伐荆州，師寄南平王詩雲：'馬頭漸入扬州路，親眷應須洗眼看。\"是歲输誠淮海，獲解重围。其他不可殫記。或一日，題庭前芭蕉葉上雲：\"今日還债，幸州縣無更勘窮。\"來日為人所害，尺首宛然。刺史高公為茶毗之。","sortOrder":9},
  {"id":"s_work_bmtn_23_10","chapterId":"ch_work_bmtn_23","text":"湖南帥馬希聲在位多縱率，有贾客沈申者，常來往番禺間，廣主優待之，令如北中求寶帶。申於洛汴間市得玉帶一，乃奇货也。回由湘潭，希聲竊知之，召申詣衙，賜以酒食，抵夜送還店，預戒軍巡以犯夜戮之。湘人俱聞，莫不嗟悯。爾後常見此客為祟，或在屋脊，或據欄槛，不常厥處。未久，希聲暴卒。其弟希范嗣立，以玉帶還廣人。","sortOrder":10},
  {"id":"s_work_bmtn_23_11","chapterId":"ch_work_bmtn_23","text":"韦承皋者，伪蜀時將校也。有待詔僧名行真，居蜀州長平山，嘗於本州龍興寺構木塔，凡十三級，費錢銀萬計，尋為天火所焚，第三次營構方能就。人謂其有黃白之術也。及承皋典眉州，召行真至郡。郡有盧敬芝司馬者，以殖货為業。承皋嘗謂之曰：\"某頃軍中與行真同火幕，遇一韦處士，授以作金術。適來鄙夫老矣，故召行真同修舊藥，藥成當得分惠。謂吾子罢商贾之業可乎？\"盧敬诺。藥垂成，韦牧坐罪貶茂州參軍。臨行，盧送至蟆颐津。韦牧沉藥鼎於江中，謂盧生曰：\"吾罪矣。先是授術韦處士者，吾害之而滅口。今日之事，藥成而禍及，其有神理乎。\"蜀國更变，以拒魏王之師，誅死。","sortOrder":11},
  {"id":"s_work_bmtn_23_12","chapterId":"ch_work_bmtn_23","text":"伪蜀寧江節度使王宗黯生日，部下屬縣皆率醵财货以為贺禮。巫山令裴垣以編戶羁貧，獨無慶獻。宗黯大怒，召裴至，誣以他事，生沉滟澦堆水中，三日尸不流。宗黯遣人命挽而下，經宿逆水复上，卓立波面，正视衙門。宗黯頗不自安，神識煩撓，竟得疾暴卒。","sortOrder":12},
  {"id":"s_work_bmtn_23_13","chapterId":"ch_work_bmtn_23","text":"渚宮有民公乘通者，平生隱慝，人或難知。死後湖南民家生一黑驢駒，白毛作荆南公乘通字。其子孫聞之懷恥，竟不能尋贖。江陵人皆知之。","sortOrder":13},
  {"id":"s_work_bmtn_23_14","chapterId":"ch_work_bmtn_23","text":"湖南武穆王巡邊，回舟至洞庭宜春江口，暴風忽至，波如連山。乃見波中恢诡譎怪，蛟螭出没，雲霧昏蒙，有如武夫執戈戟者，有文吏具襴簡者，有如捧盤盂者，或緋或绿，倏閃睢盱，莫知何物。左右大駭，衣服器皿悉投之。舟人欲以姬妾為請，王不聽。移時風定，仅獲存焉。後數年，武穆王薨於位。","sortOrder":14},
  {"id":"s_work_bmtn_23_15","chapterId":"ch_work_bmtn_23","text":"東州顧彦朗以蔡叔向為副使，感微時之恩，雖為戎倅而嘗加敬。其弟彦暉嗣袭，酷好絜净，嘗嫌人臭，左右薰香而備給使。幕僚皆中朝子弟，亦涉輕薄。韦太尉昭度收复蜀城，以彦暉為招讨副使。在軍中，每旦率幕官同謁掌武，而蜀先主預焉，共輕忽之，雖昭度亦嫌其不恭。彦暉袭兄位，爾後為蜀主所破，手刃一家，郎官溫術等毙焉。先是，蔡叔向職居元僚，乃顧氏之心膂，與所辟朝士優遊尊俎，不相侔矣。小顧既是尊崇，嫌其掣肘，王先主因其隙宣言以間之，且曰：\"拈却蔡中丞，看爾得否。\"由是叔向辭職閒居，王乃舉軍而伐之。在蜀，有術士朱洽者，常謂人曰：\"二顧雖位尊方镇，生無第宅，死無墳墓。\"人莫諭之。或曰二顧自天德軍小將，际會立功，便除東川，弟兄迭據。大顧相薨，遺命焚骸，歸葬丰州，會多事未果。至小顧狼狽之日，送終之禮又闕焉。即朱氏言於斯验矣。","sortOrder":15},
  {"id":"s_work_bmtn_23_16","chapterId":"ch_work_bmtn_23","text":"進士楊鼎夫富於詞學，為時所稱。頃歲會遊青城山，過皂江，同舟者約五十餘人。至於中流，遇暴風漂荡，其船抵巨石傾覆於洪涛間，同濟之流盡沉没底，獨鼎夫似有物扶助。既達岸，亦困頓矣，遽有老人以杖接引且笑雲：\"元是鹽里人，本非水中物。\"鼎夫未及致謝，旋失老人所之，因作詩以記。後歸成都，話與知己，終莫究\"鹽里人\"之義。後為權臣安思謙幕吏，判榷鹽院事，遇疾暴亡。男文則以屬分料鹽百餘斤裹束，將上蜀郊營葬。至是鹽里之詞方验。鼎夫舊記詩曰：\"青城山峭皂江寒，欲度當時作等閒。棹逆狂風趨近岸，舟逢怪石碎前湾。手携弱杖仓皇處，命出洪涛頃刻間。今日深恩無以報，令人羞記雀衔環。\"","sortOrder":16},
  {"id":"s_work_bmtn_23_17","chapterId":"ch_work_bmtn_23","text":"蜀御史中丞牛希濟，文學繁贍，超於時辈，自雲早年未出學院，以詞科可以俯拾。或夢一人介金曰：\"郎君分無科名，四十五已上方有官祿。\"覺而異之。旋遇丧亂，流寓於蜀，依季父也。仍以氣直嗜酒為季父所责，旅寄巴南。旋聆开國，不預勸進，又以時辈所排，十年不調，為先主所知，召封，除起居郎，累加至憲長。是知向者之夢何其神也！伪蜀後主王衍以唐袭宅建上清宮，於老君尊像殿中列唐朝十八帝真容，備法駕謁之。識者以為拜唐乃歸命之先兆也。先是，司天監胡秀林進歷，移閏在丙戌年正月。有向隱者，亦進歷，用宣明法，閏乙酉年十二月。既有異同，彼此紛訴，仍於界上取唐國歷日。近臣曰：\"宜用唐國閏月也。\"因更改閏十二月。街衢賣歷者雲：\"只有一月也。\"其年十二月二十八日國滅。胡秀林是唐朝司天少鹽，仕蜀，別造永昌正象歷，推步之妙天下一人，然移閏之事不爽，歷議常人不可輕知之。","sortOrder":17},
  {"id":"s_work_bmtn_23_18","chapterId":"ch_work_bmtn_23","text":"章孝子名全益，東蜀涪城人。少孤，為兄全啟養育。母疾，全啟割股肉以饋，其疾果瘳也。他日全啟出遊，殂於逆旅。全益感天倫之恩，製斬縗之服。又以全啟割肉啖母，遂以火煉指以申至痛，仍以銀字寫《法華經》一部，日夕諷誦，仍通大義。後於成都府樓巷舍於其間，傍有丹竈，不蓄童仆，塊然一室。鬻丹得錢，數及兩金即刻一像。今華亭禪院即居士高樓之所。人謂有黃白之術，嘗言於道友曰：\"點水銀一兩，止一兩銀价。若丸作三百粒，每粒百錢，乃三十千矣。\"其利溥哉，但所鬻之丹亦神矣。居士到蜀之後，製土偶於丹竈之侧以代執熱之用，護惜不毀殆四十年。大順中物故，年至九十八。寺僧寫真於壁，節度判官、前眉州刺史冯涓撰贊以美之。","sortOrder":18},
  {"id":"s_work_bmtn_23_19","chapterId":"ch_work_bmtn_23","text":"蜀之將帥鮮不好货，有許宗裔者，分符杖鉞，獨守廉隅，嘗典劍州。民有致寇者，燈下認識暴客，待晓告巡。其賊不禁拷捶，遠首其罪，囚而送州。宗裔引慮，缧囚紛訴，且言絲鉤紈乃是家物，與被劫主遞有詞說。宗裔促命兩家缲絲車，又各赍綢紈卷。問胎心复用何物，一雲杏核，一雲瓦子。因令相退下綢線，見杏核，與囚款同，仍以絲鉤安車，量其輕重大小亦是囚家本物，即被劫者有妄認之過，巡捕吏伏拷决之辜。指顧之間，為雪冤枉，乃良吏也。","sortOrder":19},
  {"id":"s_work_bmtn_23_20","chapterId":"ch_work_bmtn_23","text":"陳太師敬瑄雖濫升重位，而頗有伟量。自镇西川日，乃委政事於幕客，委軍旅於護戎，日食蒸犬一頭，酒一壶，一月六設曲宴，即自有平生酒徒五人狎昵，焦菜一碗，破三十千。常有告設吏偷錢，拂其牒而不省。營妓玉兒者，太師賜之卮酒，拒而不飲，乃誤傾泼於太師，污頭面。遽起更衣，左右驚忧，立候玉兒為赍粉。更衣出，却坐，又以酒賜之。玉兒請罪，笑而恕之。其宽裕率皆此類。","sortOrder":20},
  {"id":"s_work_bmtn_24_1","chapterId":"ch_work_bmtn_24","text":"●逸文卷二","sortOrder":1},
  {"id":"s_work_bmtn_24_2","chapterId":"ch_work_bmtn_24","text":"伪蜀先主王建始攻围成都，三年未下。其紀綱之仆有無賴輕生男悍者百辈，人莫敵也。建嘗以美言啖之曰：\"西川號為錦花城。一旦收克，玉帛子女恣我兒辈快活也。\"他日陳敬瑄、田今孜以城降，翌日，赴府預戒驕暴諸子曰：\"我與爾累年戰斗，出死入生，來日便是我一家也。入城之後但管富貴，即不得恣橫。我適來差張勍作斬斫馬步使，责辦於渠。汝辈不得辄犯，若把到我面前，足可矜恕，或被當下斬却，非我能救。\"諸子聞戒，各務戢斂。然張勍胸上打人，堆壘通衢，莫有敢犯。識者以建能戒能惜，不陷人於刑，仁恕之比也。","sortOrder":2},
  {"id":"s_work_bmtn_24_3","chapterId":"ch_work_bmtn_24","text":"邛黎之間有淺蠻焉，世袭王號，曰劉王、楊王、郝王。歲支西川衣賜三千分，俾其侦雲南動靜。雲南亦資其觇成都盈虛，持兩端而求利也。每元戎下車，即率界上酋長詣府庭，號曰參元戎。上聞，自謂威惠所致。其不參間，潛禀於都押衙，且俟可否。或元戎慰撫大將間稍至乖方，即教其紛紜。時帥臣多是文儒，不欲生事，以是都押賴之，亦要姑息。蠻蜑凭陵，若無亭障，抑此之由也。王建始镇蜀，絕其舊賜，斬都押衙山行章以令之，邛峡之南不立一堠，不戍一卒，十年不敢犯境。末年，命大將許存征蠻，為三王泄漏軍機，於是召三王而斬之，時號因斷也。昔日之患三王，非不知也，時不利也，故曰\"有非常之功\"，許公之謂也。先是，唐鹹通中，有天竺三藏僧經過成都，晓五天胡語，通大小乘經律論。以北天竺與雲南接境，欲假途而還，為蜀察事者識之，縶於成都府，具得所記朝廷次第文字，蓋曾入內道場也。是知外國來廷者安知非奸細乎","sortOrder":3},
  {"id":"s_work_bmtn_24_4","chapterId":"ch_work_bmtn_24","text":"唐乾符中，綿竹王俳優者有巨力。每遇府中食軍宴，客先呈百戲，王生腰背一船，船中載十二人，舞《河傳》一曲，略無困乏。","sortOrder":4},
  {"id":"s_work_bmtn_24_5","chapterId":"ch_work_bmtn_24","text":"燕之舊將周歸祐，蘇門更变之际以劍拄心，刃自背出而不死。奔於梁，為騎將之先鋒焉。十五年，夹河百戰，通中之瘡往往遇之。後唐莊宗入洛，為仇者於獵場席地俾坐，滿挽而射，貫腋而出，創愈無恙。仕至郡牧、節度留後，竟死於牖下。","sortOrder":5},
  {"id":"s_work_bmtn_24_6","chapterId":"ch_work_bmtn_24","text":"蜀許寂少年栖四明山，學《易》於晉征君。一旦，有夫婦偕詣山居，携一壶酒。寂詰之雲：\"今日離剡縣。\"寂曰：\"道路甚遙，安得一日及此\"頗亦異之。然夫甚少，而婦容色過之，状貌毅然而寡默。其夕以壶觴命許同酌，此丈夫出一拍板，遍以銅釘釘之，乃抗聲高歌，悉是說劍之意。俄自臂間抽出兩物，展而喝之，即兩口劍，躍起在寂頭上盤旋交击，寂甚驚駭。尋而收匣之。飲畢就寢，迨晓乃空榻也。至日中，复有一頭陀僧來尋此夫婦，寂具道之。僧曰：\"我亦其人也，道士能學之乎？\"寂辭曰：\"少尚玄學，不願為此。\"其僧傲然而笑，乃取寂净水拭腳，徘徊間不見。爾後再於華陰遇之，始知其俠也。杜光庭自京入蜀，宿於梓潼廳。有一僧繼至，縣宰周某與之有舊，乃雲：\"今日自興元來。\"杜異之。明發，僧遂前去。宰謂杜曰：\"此僧乃鹿盧蹻。\"亦俠之類也。詩僧齊己於沩山松下親遇一僧於頭指甲下投抽出兩口劍，跳躍凌空而去。","sortOrder":6},
  {"id":"s_work_bmtn_24_7","chapterId":"ch_work_bmtn_24","text":"朗州道士羅少微頃在茅山紫陽觀寄泊，有丁秀才者亦同寓於觀中，舉動風味無異常人，然不汲汲於仕進。盤桓數年，觀主亦善遇之。冬之夜，霰雪方甚，二三道士围爐，有肥Ｂ美醞之羨。丁曰：\"致之何難。\"時以為戲，俄見开戶奪袂而去，至夜分，蒙雪而回，提一銀酒，熟羊一足，雲浙帥厨中物。由是驚訝歡笑，掷劍而舞，騰躍而去，莫知所往，唯銀存焉。觀主以状聞於縣官，詩僧貫休《俠客》詩雲：\"黃昏風雨黑如磐，別我不知何處去。\"得非江淮間曾聆此事而構思也","sortOrder":7},
  {"id":"s_work_bmtn_24_8","chapterId":"ch_work_bmtn_24","text":"唐韓定辭為镇州王鎔書記，聘燕帥劉仁恭，舍於賓馆，命试幕客馬彧延接。馬有詩赠韓曰：\"燧林芳草綿綿思，盡日相携陟麗谯。別後巏嵍山上望，羨君時复見王乔。\"彧詩雖清秀，然意在征其學問。韓亦於座上酬之曰：\"崇霞台上神仙客，學辨癡龍藝最多。盛德好將銀筆術，麗詞堪與雪兒歌。\"座內諸賓靡不钦訝稱妙句，然亦疑其\"銀筆\"之僻也。他日，彧复持燕帥之命答聘常山，亦命定辭接於公馆。時有妓轉轉者，韓之所眷也，每當酒席，或頻目之。韓曰：\"昔愛晉文公分季隗於趙衰，孫伯符輟小乔於公瑾，蓋以色可奉名人。但慮倡姬不如賢者之顧，願垂一詠，俾得奉之。\"彧援筆，文不停缀，作轉轉之賦，其文甚美。鹹钦其敏妙，遂傳於遠近。彧從容問韓以\"雪兒\"\"銀筆\"之事，韓曰：\"昔梁元帝為湘東王時好學著書，常記錄忠臣義士及文章之美者。筆有三品，或以金銀雕飾，或用斑竹為管。忠孝全者用金管書之，德行清粹者用銀筆書之，文章贍麗者以斑竹書之，故湘東之譽振於江表。雪兒者，李密之愛姬，能歌舞，每見賓僚文章有奇麗入意者，即付雪兒葉音律以歌之。\"又問，\"癡龍\"出自何處，定辭曰：\"洛下有洞穴，曾有人誤墜於衢中，因行數里，漸見明曠，見有宮殿人物凡九處，又見有大羊，羊髯有珠，人取而食之，不知何所。後出以問張華，曰：'此地仙九馆也。大羊者名曰癡龍耳。'\"定辭复問或巏嵍之山當在何處，彧曰：\"此隋君之故事，何謙光而下問。\"由是兩相悅服，結交而去。","sortOrder":8},
  {"id":"s_work_bmtn_24_9","chapterId":"ch_work_bmtn_24","text":"王蜀時有趙雄武者，眾號趙大餅，累典名郡，為一時之富豪。嚴絜奉身，精於钦饌，居常不使膳夫。六局之中各有二婢執役，當厨者十五餘辈，皆著窄袖鮮絜衣裝。事一餐邀一客，必水陆俱備，雖王侯之家不得相仿焉。有能造大餅，每三斗面擀一枚，大於數間屋。或大內宴聚，或豪家有廣筵，多於眾賓內獻一枚，裁剖用之皆有餘矣。雖親密懿分，莫知幹造之法，以此得大餅之號。","sortOrder":9},
  {"id":"s_work_bmtn_24_10","chapterId":"ch_work_bmtn_24","text":"唐光化中，蘇拯與乡人陳涤同處。拯與考功郎中蘇璞初叙宗党。璞，故奉常涤之子也。拯既執贽，尋以啟事溫卷，因令陳涤緘封，涤遂誤書己名。璞得之大怒。拯聞之，仓皇复致書謝過。吳子華聞之，曰：\"此書應誤也。\"","sortOrder":10},
  {"id":"s_work_bmtn_24_11","chapterId":"ch_work_bmtn_24","text":"（此處脱六字）董掌奏記，府主褊急。（此處脱九字）詣梁園，勸梁太祖。（此處脱十字）官入中原授大理。（此處脱七字）季昌怒曰：\"天下皆知四镇令公必作天子，（此處脱三字）偃仰乎？\"詬怒而起，久之，召孔目官王仁厚謂曰：\"我（此處脱四字）書記所見甚長，且廣南、湖南與梁王齊肩，所以（此處脱四字）使。我乃梁王將校，安可辄同兩處差都押衙可（此處脱四字）董且召宴飲，迎而謂曰：\"集性急，請一切勿言。\"仍遺衣段數十匹以安之。董雖禀受，莫知喜怒之由。他日聞說自□□我本無此見，誠出司徒之意。都校充使於禮合儀，所遺衣段乃谬思也。","sortOrder":11},
  {"id":"s_work_bmtn_24_12","chapterId":"ch_work_bmtn_24","text":"扶風馬處謙病瞽，厥父俾其學《易》以求衣食。嘗於安陆鬻筮自給。有一人謁筮，謂馬生曰：\"子之筮未臻其妙，我有秘法，子能從我學之乎？\"馬生乃隨往。郡境有陶仙觀，受星之訣，凡一十七行。因請其爵里，乃雲胡其姓而恬其名，誡之曰：\"子有官祿，終至五十二歲。幸勿道我行止於王侯之門。\"馬生得訣，言事甚验。趙匡明弃荆入蜀，因隨至成都。王先主嘗令杜光庭先生密問享寿幾何，對曰：\"主上受元陽之氣四斤八兩。\"果七十二而崩，四斤八兩即七十二兩也。馬生官至中郎，金紫，亦五十二而殒。","sortOrder":12},
  {"id":"s_work_bmtn_24_13","chapterId":"ch_work_bmtn_24","text":"火燒瘡無出醋泥，甚验。孫光憲嘗家人作煎餅，一婢抱元子擁爐，不覺落火炭之上，遽以醋泥傅之，至晓不痛，亦無瘢痕。是知俗說不厭多聞。","sortOrder":13},
  {"id":"s_work_bmtn_24_14","chapterId":"ch_work_bmtn_24","text":"唐天祐中，太原僧惠照因夢镇州南三十里废相國寺中埋鐵塔，特往訪之。至界上，為元戎王中令鎔所知，延在衙署供養。衙將任友義慮是鄰道諜人或致不测，恳要詰而逐之。元戎始疑，惠具以尋塔為對。遽差於府南三十里訪之，果得相國寺古基，掘其殿砌之前得鐵塔，上刻三千人姓名，悉是見在常山將校親軍，唯任友義一人無名。乃知冥數前定。刻斯塔者何神異哉！","sortOrder":14},
  {"id":"s_work_bmtn_24_15","chapterId":"ch_work_bmtn_24","text":"伪蜀王先主未开國前，西域僧至蜀，蜀人瞻敬如見釋迦，舍於大慈三學院。蜀主复謁坐於廳，傾都士女就院不令止之。婦女列次禮拜，俳優王舍城飄言曰：\"女弟子勤苦禮拜，願後身面孔一切似和尚。\"蜀主大笑。","sortOrder":15},
  {"id":"s_work_bmtn_24_16","chapterId":"ch_work_bmtn_24","text":"伪蜀王先主起自利、阆，號親騎軍，皆拳勇之士，四百人分（此處脱四字）執紫旗。凡戰陣，若前軍將败，麾紫旗以副之，莫不（此處脱三字）靡，霆駭星散，未嘗挫衄。此团將卒多達，或至節將。（此處脱四字）至散員，亦享官祿，以之定霸，皆資福人。於時（此外脱五字）淮南黑雲都，皆紫旗之類也。此從各有名號。時顧（此處脱五字）亦嘗典郡，多雜談謔，曾造武舉，助曰大順（此處脱四字）侍郎李吒吒下進士及第三（此處脱十四字）憨子、薑癩子、張打胸、長小（此處脱十二字）許（此處脱九字）李嗑咀、李破肋、李吉丫、樊忽雷、日遊神、玉蹄馳、郝牛屎、□□貢、陳波斯、羅蠻子，试《亡命山泽賦》《到處不生草》詩，斯亦麥鐵杖、韓擒虎之流也。","sortOrder":16},
  {"id":"s_work_bmtn_24_17","chapterId":"ch_work_bmtn_24","text":"孫光憲在蜀時，曾到資州，見應貞觀李道士話州有姓趙人，閉關却扫，以廊廟自期，都虞侯阎普敬異之，躬自趨謁。阎魁梧丈夫，趙生迎門，愕眙良久，罄折叙寒溫，曰：\"伏惟貔貅，阎乃质於先容者，俾詢之。\"趙生曰：\"若雲熊羆，即須宰相之才方當此語。阎公止於都頭，已來只銷呼為貔貅。\"人聞鹹笑之。又一士自稱張舍人，訴於光憲曰：\"兄長以術惑我心神。\"憲謂曰：\"得非蠱毒厭勝之術耶\"張曰：\"非也。乃用鬼穀子捭阖捭破我心神，至今患心風不禁。\"又江陵顧雲偶收諸葛亮兵書，自言可用十萬軍吞併四海。每至論兵必攘袂叱咤，若對大敵，時人謂之檢譜角觝也。時有行軍王副使，幽燕舊將，聲聞宇內。顏生候謁，稱是同人，自言大志不伸，丧良友也，每恸哭焉。","sortOrder":17},
  {"id":"s_work_bmtn_24_18","chapterId":"ch_work_bmtn_24","text":"有民妻不識鏡，夫市之而歸。妻取照之，驚告其母曰：\"某郎又索一婦歸也。\"其母亦照曰：\"又領親家母來也。\"","sortOrder":18},
  {"id":"s_work_bmtn_25_1","chapterId":"ch_work_bmtn_25","text":"●逸文卷三","sortOrder":1},
  {"id":"s_work_bmtn_25_2","chapterId":"ch_work_bmtn_25","text":"河中判官路德延，相國巖之侄，嶽之子，時謂才俊，擢進士第，西平王朱友謙幕僚，放恣凌傲，主公容之。友謙背梁，乞於晉陽。併使初至，禮遇方謹，路公筵上言語及之，友謙忧憤，因投德延於黃河以纾禍也。先是，紀綱之仆近判官入謁幕次，遂有請易舍之說。蓋義兄弟同處，不欲聞郎官秽談也。路子得非其人耶。","sortOrder":2},
  {"id":"s_work_bmtn_25_3","chapterId":"ch_work_bmtn_25","text":"蜀東、西川之人常互相輕薄。西川人言：\"梓州者乃我東門之草市也，豈得與我為耦哉！\"節度柳仲郢聞之，為幕客曰：\"吾立朝三十年，清華備歷，今日始得與西川作市令。\"聞者皆笑之。故世言東西兩川人多輕薄。","sortOrder":3},
  {"id":"s_work_bmtn_25_4","chapterId":"ch_work_bmtn_25","text":"江陵高季昌唐末為荆州留後時，宰相韦說、鄭珏舅甥姻娅也，朱梁太祖時皆得製方面。高氏以貴公子任行軍司馬，常以歌筵酒饌款待數公，日常宴聚，求取無恒，皆優待之。後莊宗過河，奄有中原，天下震懼，高氏单騎入觐，韦、鄭二公繼登台席。中朝士族子弟多不達時变，复存舊態，薛泽除補闕，韦荆除春秋博士，皆賜緋，鹹有德色，匆匆辦裝，即俟歸朝，视行軍蔑如也。李載仁，韦說之甥，除秘書郎。劉诜，鄭珏之妹夫也，除毛詩博士，賜緋。爾後韦屢督李入京，高氏欲津置之。載仁遷延，自以先德遺戒，不欲依舅氏，但不能顯言，竟不離高氏門馆。劉诜無他才望，性嗜酒，口受新命，殊無行意，日於高氏情敬不衰，然則美醞肥Ｂ之所引也，無何，以疾終。高氏贍給孤遺，頗亦周至。未間，洛下有变，明宗入統，南方強侯，人要姑息。韦、鄭二相皆罢去，韦、薛尚跧荆楚。明年，保勖嗣袭，辟李為掌記。他日，錄其長息為子婿，第三子皆奏官，一門朱紫韡如也。劉诜三子迭加任遇，三孫女適高氏子弟，向三十年享其祿食，亦足稱也。韦荆寂寞而卒，薛泽攝宰而終，豈自掇乎亦命也夫！","sortOrder":4},
  {"id":"s_work_bmtn_25_5","chapterId":"ch_work_bmtn_25","text":"盧程擢進士第，為莊皇帝河東判官，建國後命相。無他才業，唯以氏族傲物。任圜常以公事入謁，程乌紗隱幾，謂圜曰：\"公是虫豸，辄來唐突。\"圜慚愕，骤告莊宗，大怒，俾殺之，為盧质救解獲免。自是出中書，時人切齒焉。江陵在唐世號衣冠藪泽，人言琵琶多於飯甑，措大多於鯽魚。有邑宰盧生，每於枝江縣差船入府，舟子常苦之。一旦，王仙芝兵火，盧生為船人挑其筋系於船舷，放流而死。大凡無藝子弟率以門閥輕薄，廣明之亂遭罹甚多，鹹自致也。","sortOrder":5},
  {"id":"s_work_bmtn_25_6","chapterId":"ch_work_bmtn_25","text":"韦昭度招讨陳敬瑄時，蜀帥顧彦暉為副，王先生為都指揮使。三府各署幕僚，皆是朝達子弟，视王先主蔑如也。先主侍從髡發行■參，黥面札腕，如一部鬼神。其辈以先主兢肅，顧公詳缓，一時失笑而散。先主歸管，左右以此為言，亦自大笑。他日克郪城，輕薄幕僚皆害之。","sortOrder":6},
  {"id":"s_work_bmtn_25_7","chapterId":"ch_work_bmtn_25","text":"荆南節度使高保融有疾，幕吏孫光憲夢在渚宮池與同僚偶坐，而保融在西廳獨處，唯姬妾侍焉。俄而高公弟保勖見召上桥，授以筆砚，令光憲指撝發軍，仍遣廳頭二三子障蔽光憲，不欲保融遙見。逡巡有具櫜鞬將校列行俟命，次見掌節吏嚴光楚鞹而前趨，手捧兩黑物，其一則如黑漆鞾而光，其一即尋常鞾也，謂光憲曰：\"某曾失墨兩挺，蒙王黜责，今果尋獲也。\"良久夢覺。翌日說於同僚。逾月而保融卒，節院將嚴光楚具帖子取處分倒節。光憲請行軍司馬王甲判之：墨者，陰黑之物，節而且黑，近於凶象，即向之所夢倒双節之謂也。","sortOrder":7},
  {"id":"s_work_bmtn_25_8","chapterId":"ch_work_bmtn_25","text":"湘湖有大校周藹者，居常與同門生姻好最厚，每以時人不能理命，致不肖子爭财紛詬，列於訟庭。慨此為鑒，乃相約曰：\"吾徒他年勿遵其轍，傥有不讳，先須區分，俾其不露丑惡，貽责後人也。\"他日同門生奉職襄邸，一夕，周校夢見揮涕告訴曰：\"姨夫姨夫，某前言已乖，今為異物矣。昨在通衢，急風所中，已至不救，但念家事，今且歸來，略要處理。\"周校忽然驚覺，通夕不寐，遲明抵其家說之，家人亦夢。不旬日，凶問至矣。自是傳靈語，均财產，戒子辭妻，言善意勤，殆一月而去不复再來。","sortOrder":8},
  {"id":"s_work_bmtn_25_9","chapterId":"ch_work_bmtn_25","text":"進士鄭起謁荆州節度高從誨，馆於空宅，其夕夢一人告訴曰：\"孔目官嚴光楚無禮。\"意甚不平。比夕又夢，起異其事，召嚴而說之。嚴命巫祝祈謝，靡所不至，莫知其由。明年，鄭生隨計，嚴光楚愛其宅有少竹径，多方而致之。才遷居，不日以罪笞而停職，竟不知其故。","sortOrder":9},
  {"id":"s_work_bmtn_25_10","chapterId":"ch_work_bmtn_25","text":"遂州巡屬村民姓於號世尊者，與一女皆逆知人之吉凶，數州敬奉，舍财山積，鏨凿崖壁列為佛像，所費莫知紀極。節度許公存以其袄妄召至府衙，俾其射覆，不中，乃械而殺之，一無神变。於其所居得五色文麻絙，以牛載仅百馱，錢帛即可知也。每夜會，自作阿弥陀佛，宮殿池沼一如西方，男女俱集，念佛而已。斯亦下愚之流，豈術神邪將有物凭之邪","sortOrder":10},
  {"id":"s_work_bmtn_25_11","chapterId":"ch_work_bmtn_25","text":"高燕公镇蜀日，大慈寺僧申報堂佛光見，燕公判曰：\"付馬步使捉佛光過。\"所司密察之，誘其童子，具雲\"僧辈以鏡承隙日中影閃於佛上\"，由此乖露，擒而罪之。","sortOrder":11},
  {"id":"s_work_bmtn_25_12","chapterId":"ch_work_bmtn_25","text":"釋教五部持念中有大輪咒術，以之救病亦不甚效，然其攝人精魂，率皆狂走，或登屋梁，或嚙瓷碗。闾阎敬奉，殆似神聖。此辈由是廣獲金帛。陵州貴平縣牛鞞村民有周達者，販鬻此術，一旦沸油煎其陰以充供養，觀者如堵，或驚或笑。初自忘痛，尋以致殂也。中間僧昭浦說朗州有僧號周大悲者，行此咒術，一旦煉陰而毙，與愚所見何姓氏恰同，而其事無殊也。蓋小人用道欺天，殘形自罰。以其事同，因而錄之。","sortOrder":12},
  {"id":"s_work_bmtn_25_13","chapterId":"ch_work_bmtn_25","text":"庐山書生張璟乾寧中以所業之桂州，至衡州犬嗥滩，損船上岸，寢於江廟，為神所貴。璟以素業對之，神為改容延坐，從容雲：\"有巫立仁者，罪合族，廟神為理之於嶽神，無人作奏。\"璟為草之。既奏，嶽神許之。廟神喜，以白金十鉼為赠。劉山甫與校書郎廖骘親見璟，說其事甚詳。","sortOrder":13},
  {"id":"s_work_bmtn_25_14","chapterId":"ch_work_bmtn_25","text":"福建崔從事，忘其名，正直檢身，幕府所重。奉使湖湘，复命，在道遇賊，同行皆死，惟崔仓皇中忽有人引路獲免。中途复痁疾，求藥無所，途次延平津廟，夢為廟神賜藥三丸，服之驚覺，頓愈。彭城劉山甫自雲外祖李敬彝為郎中，宅在東都毓材坊，土地最靈。家人張行周事之有應，未大水前，預夢告張求飲食。至其日，率其類遏水頭，併不冲圮李宅。","sortOrder":14},
  {"id":"s_work_bmtn_25_15","chapterId":"ch_work_bmtn_25","text":"青城縣岷江暴涨，漂墊民居。縣民關承湍妻計氏有孩提子在懷抱，乃上木櫃，為駭浪推漾大江，唯見赤帻佩刀者洎朱衣秉簡者安存之，令洎縣溉。櫃乃隨流泛泛，至縣溉為舟子迎拯而出，子母無恙。","sortOrder":15},
  {"id":"s_work_bmtn_25_16","chapterId":"ch_work_bmtn_25","text":"湖南馬希聲嗣父位，連年亢旱，祈祷不應，乃封閉南嶽司天王廟及境內神祠，竟亦不雨。其兄希振入諫之，飲酒至中夜而退，聞堂前喧噪，連召希振，复入，見希聲倒立於階下，衣裳不披，其首已碎。令親信舆上，以帛蒙首。翌日發丧，以弟希范嗣位。先是，大將周達自南嶽回，見江上雲霧中擁執希聲而去，秘不敢言，夕有物如黑幕突入空堂，即時而卒。","sortOrder":16},
  {"id":"s_work_bmtn_25_17","chapterId":"ch_work_bmtn_25","text":"唐清泰主乃晉高祖之婦兄也。明宗始為太原將帥，二主軍職未高，因击鞠入趙襄子廟，俱見土偶避位而立，甚訝之，潛亦自負。及明宗功高，常危懼，二主曰：\"趙襄子終能致神邪\"爾後二主迭享大位。","sortOrder":17},
  {"id":"s_work_bmtn_25_18","chapterId":"ch_work_bmtn_25","text":"合州有壁山神，乡人祭必以太牢，不爾致禍。州里懼之，每歲烹宰不知紀極。蜀僧善晓早為州縣官，苦於調選，乃剃削為沙門，堅持戒律，雲水參禮。行經此廟，乃曰：\"天地郊社，荐享有儀。斯鬼何得僭於天地！牛者稼穡之資，爾淫其祀，無乃過乎？\"乃命斧击碎土偶數軀，殘一偶，而僧亦力困，稍蘇其氣，方次击之，廟祝祈僧曰：\"此一神從來蔬食。\"由是存之。軍州驚愕，申聞本道，而僧端然無恙。斯以正理责之，神亦不敢加禍也。","sortOrder":18},
  {"id":"s_work_bmtn_25_19","chapterId":"ch_work_bmtn_25","text":"江河邊多伥鬼，往往呼人姓名，應之者必溺，乃死魂者誘之也。李載仁嘗維舟於枝江縣曲浦中，月色皎然，忽見一嫗一男子出水面四顧，失聲雲：\"此有生人。\"遽馳水面，若履平地，登岸而去。當陽令蘇汭居江陵，嘗夜歸，月明中見一美人，被發，所著裙裾殆似水濕。汭戲雲：\"非江伥耶\"婦人怒曰：\"唤我作鬼！\"奔而逐之，汭走，遇更巡方止，見婦却返所來之路。","sortOrder":19},
  {"id":"s_work_bmtn_25_20","chapterId":"ch_work_bmtn_25","text":"漢江北邓州界地名穴口，本無镇戍，有小河南流入於漢，久為沙壅，水道甚隘。前江陵令劉璪丙子歲往彼州訪親知，至穴口，宿舊知韓氏家。家人曰：\"鄰村張家新婦卒來三日，適來却活。主人暫往省之。\"至夜韓家人歸，雲：\"張婦為侧近廟神召去，見其中外親眷亡者鹹在焉，為廟神造軍頓，無人作餅，故令召來。見廳上門外將士列坐，言开穴口江水，士卒踣沙，手皆血流。供頓畢，乃放回。\"乡里未之信，不久，沙壖相次摧墊，江路乃通。","sortOrder":20},
  {"id":"s_work_bmtn_25_21","chapterId":"ch_work_bmtn_25","text":"成汭镇荆州，有墊江縣令催□與主簿李矩不协，鄰於水火。一旦，群賊劫縣，殺崔令。賊過後，矩入宅檢校，有一廳子方避賊，見矩，以為與賊通。明日言镇將，眾鹹知矩與崔失歡，頗疑之，執送忠州，推問不伏，遂解送江陵，禁右厢獄。厢吏速於具獄，推吏常某言於判官范某曰：\"李矩詆谰，須栲究之。\"范固不許，常竟鍛煉以成之。矩臨刑，戒家人多燒紙筆，訟於地下。才一月，常某暴亡。後李矩主簿見身，范見矩至曰：\"某受判官深恩，非敢造次。但冥府只要為證耳。\"及妻子以誠祈之，乞容旬月區分家事。雖無痛苦，飲食如常，但困憊。逾月而卒。","sortOrder":21},
  {"id":"s_work_bmtn_25_22","chapterId":"ch_work_bmtn_25","text":"蜀將陶福少年無賴，偷狗屠牛。後立功，至郡守，屯戍興元府之西縣，暴得疾，急命從人朱軍將詣府迎医李令藹。令藹與朱軍將連騎馳往，至夜抵西縣近郭諸葛亮廟前，見秉炬三對前导，擁一人步行荷校縶縛，眾人相從，後有陶親叟抱衣裘而隨之。令藹先未識陶福，朱軍將指謂令藹曰：\"此是我家太尉，胡為如此？\"逡巡恐悚，亦疑是鬼。晓至其營，已聞家人哭聲。向來執錄乃福之魂也。","sortOrder":22},
  {"id":"s_work_bmtn_25_23","chapterId":"ch_work_bmtn_25","text":"草書僧文英大師彦翛始在洛都，明宗世子秦王從榮复厚遇之。後有故，南居江陵西湖曾口寺，一日恍惚忽見秦王擁二十騎詣寺訪彦翛，彦翛問：\"大王何以此來\"恰未對，倏而不見。彦翛方訪於人，不旬日，秦王遇害。","sortOrder":23},
  {"id":"s_work_bmtn_25_24","chapterId":"ch_work_bmtn_25","text":"唐僖宗皇帝播遷漢中，蜀先主建為禁軍都頭，與其儕於僧院掷骰子，六只次第相重，自幺至六，人共駭之。他日霸蜀，因幸興元，訪當時僧院，其僧尚在。問以舊事，此僧具以骰子為對。先主大悅，厚賜之。","sortOrder":24},
  {"id":"s_work_bmtn_25_25","chapterId":"ch_work_bmtn_25","text":"青城寶園山僧彦先嘗有隱慝，離山往蜀州，宿於中路天王院，暴卒，被人追攝，詣一官曹，未領見王，先見判官，詰其所犯，彦先抵讳之。判官乃取一猪腳與彦先，彦先推辭不及，僶俯受之，乃是一鏡。照之見自身在鏡中，從前愆過猥亵一切歷然。彦先慚懼，莫知所措。判官安存，戒而遣之。洎再生，遍與人說，然不言所犯隱秽之事。","sortOrder":25},
  {"id":"s_work_bmtn_25_26","chapterId":"ch_work_bmtn_25","text":"邛州臨漢縣內有湫，往往人見牝豕出入，號曰母猪龍湫。唐天复四年，蜀城大旱，使俾守宰躬往靈跡求雨。於時邑長具牢醴，命邑宰偕往祭之。三奠迨終，乃張筵於湫上，以神胙客，坐於烈日，鋪席以湫為上。每酒巡至，湫上黑氣如雲，氛氲直上，狂電燁然，玄雲陡暗，雨雹立至。令長與僚吏鼓舞去蓋，蒙濕而歸。翌日，此一境雨足，他邑依然赤地。夫人之至誠，龍畜亦能感動，享德濟旱，勿謂不智。","sortOrder":26},
  {"id":"s_work_bmtn_25_27","chapterId":"ch_work_bmtn_25","text":"巴蜀間於高山顶或絜地建天公壇祈水旱，蓋开元中上帝所降儀法以示人也。其壇或羊牛所犯，及預斋者飲酒食肉多為震死。新繁人王尧因往別業，村民烹豚待之。有一自天公斋回，乃即席食肉，王謂曰：\"爾不懼雷霆耶\"曰：\"我與雷為兄弟，何懼之有\"王異之，乃詰其所謂，曰：\"我受雷公籙，與雷同職。\"因取其籙验之，果如其說，仍有數卷。或畫壮夫以拳扠地為井，號\"拳扠井\"；或畫一士負薪枿，號\"一穀柴\"；或以七手撮山簸之，號\"七山簸\"。江陵東村李道士舍亦有此籙，或雲三洞法籙外有一百二法，為天師子嗣師所禁，唯許救物。苟邪用，必上帝考责陰誅也。","sortOrder":27},
  {"id":"s_work_bmtn_26_1","chapterId":"ch_work_bmtn_26","text":"●逸文卷四","sortOrder":1},
  {"id":"s_work_bmtn_26_2","chapterId":"ch_work_bmtn_26","text":"伪蜀王氏彭王傅陳絢嘗為邛州臨溪令，縣署編竹為藩而涂之。署久泥忽多落，唯露其竹。侍婢秉炬而照，一物蟠於竹節中，文彩烂然，小蛇也。俄而雷聲隱隱，絢疑其乖龍，懼罹震厄，乃易衣炷香，抗聲祈於雷曰：\"苟取龍，幸無急遽。\"雖狂電若晝，自初夜迨四更隱隱不發，既發一聲，俄然开霁，向物已失，人無震驚，有若雷神佑乎恳祷。","sortOrder":2},
  {"id":"s_work_bmtn_26_3","chapterId":"ch_work_bmtn_26","text":"伪蜀王氏梁州天旱，祈祷無验。僧子朗詣州雲：\"能致雨。\"乃具十石瓮貯水，僧坐其中，水滅於顶者，凡三日，雨足。州將王宗儔異禮之，檀越雲集，後莫知所適。僧令藹他日於興州見之，因問其術，曰：\"此閉氣耳，習之一月就。本法於湫潭中作觀，與龍相系。龍為定力所製，必致驚動，因而致雨。然不如瓮中為之，保無他害。\"","sortOrder":3},
  {"id":"s_work_bmtn_26_4","chapterId":"ch_work_bmtn_26","text":"巴巫間民多積黃金，每有聚會，即於席上羅列三品以夸尚之。雲安民有李仁表者，施泽金台盤，以此相高。亂離之後，州將皆武人，競以貪虐。蜀將張彦典忠州，暴惡尤甚，將校苦之，因而作叛，連及党與數千家。張攫其金銀，莫知紀極，後於蜀中私第別構一室以貯其金。忽一旦，屋外有火煙頻起，駭入验之，乃無延爇之處，由是疑焉。及开箧视之，悉已空矣，即向時火煙乃金化矣。","sortOrder":4},
  {"id":"s_work_bmtn_26_5","chapterId":"ch_work_bmtn_26","text":"伪蜀主當僭位，諸勋貴功臣競起甲第，獨伪中令趙廷隱起南宅北宅、千梁萬拱，其諸奢麗莫之與儔。後枕江渎，池中有二島屿，遂甃石循池，四岸皆种垂楊，或間雜木芙蓉。池中种藕，每至秋夏，花开魚躍。柳陰之下有士子執卷者、垂纶者，執如意者、執尘尾者、谭詩論道者。一旦，岸之隈有莲一茎，上分兩岐，开二朵。其時謂之太平無事之秋，士女拖香肆艳看者甚眾。趙廷隱畫圖以進，蜀主叹賞，其時歌者詠者不少。無何，禁苑中有莲一茎，岐分三朵。蜀主开筵宴召群臣賞之，是時詞臣已下皆貢詩，當時有好事者圖以繪事，至今傳之。","sortOrder":5},
  {"id":"s_work_bmtn_26_6","chapterId":"ch_work_bmtn_26","text":"江夏漢陽縣出毒菌，號茹闾，非茅蒐也。每歲供進，縣司常令人於田野間候之，苟有此菌即立表示人，不敢從下風而過，避其氣也。采之日，以竹竿芟倒，遽舍竿於地，毒氣入竹，一時爆裂，直候毒歇，仍以榉柳皮蒙手以取，用氈包之，亦榉柳皮重裹，縣宰封印而進。其赍致役夫倍給其直，為其道路多為毒薰以致頭痛也。張康隨侍其父宰漢陽，備言之。人有為野菌所毒而笑者，煎魚椹汁服之即愈。僧光遠說也。","sortOrder":6},
  {"id":"s_work_bmtn_26_7","chapterId":"ch_work_bmtn_26","text":"大江之南，芦荻之間往往燒起龍。唐天夏中，澧州葉源村民邓氏子燒，柴草積於天井，火势既盛，龍突出，騰在半空，萦帶為火所燎，風力益壮，狂焰弥炽，摆之不落，竟以仆地而毙，長且數百步，村民徙居而避之。朱梁末，辰州民向氏因燒起一龍，四面風雷急雨不能扑滅，尋為煨燼而角不化，瑩白如玉。向氏寶而藏之，湖南行軍高鬱酬其价而強取。於時術士曰：\"高司馬其禍乎，安用不祥之物以速之\"俄而被誅。","sortOrder":7},
  {"id":"s_work_bmtn_26_8","chapterId":"ch_work_bmtn_26","text":"李宣宰陽縣，縣左有潭，傳有龍居而鱗物尤美。李之子惰學，愛釣術，日往潭上。一旦，龍見，滿潭水發如舒錦被。李子褫魄委竿而走。蓋釣術多以煎燕為餌，果發龍之嗜欲也。","sortOrder":8},
  {"id":"s_work_bmtn_26_9","chapterId":"ch_work_bmtn_26","text":"彭州濛陽縣界地名清流，有一湫，乡俗雲此湫龍與西山慈母池龍為昏，每歲一會。新繁人王睿乃博物者，多所辨正，嘗鄙之。秋雨後經過此湫，乃遇西邊雷雨冥晦，狂風拔树。王睿縶馬障树而避，須臾雷電之势止於湫上，倏然而霁，天無纖雲。詰彼居人，正符前說也。雲安縣西有小湯溪，土俗雲此溪龍與雲安溪龍為親。此乃不經之談也。或一日，風雷自小湯溪循蜀江中而下，至雲安縣，雲物回薄入溪中，疾電狂霆，誠可畏。有柳毅洞庭之事與此相符，小湯之事自目睹。","sortOrder":9},
  {"id":"s_work_bmtn_26_10","chapterId":"ch_work_bmtn_26","text":"王蜀時夔州大昌鹽井，水中往往有龍，或白或黃，鱗鬣光明，搅之不動，唯沮沫而已。彼人不以為異。近者秭歸永濟井滷槽亦有龍蟠，與大昌者無異，識者曰：\"龍之為靈瑞也，負圖以升天，今乃見於滷中，豈能雲行雨施乎？\"雲安縣漢成宮絕顶有天池，深七八丈，其中有物如蜥蜴，長咫尺，五色備具，躍於水面，象小龍也。有高遇者為刺史，詣宮設醮，忽浮出。或問監官李德符曰：\"是何祥也\"符曰：\"某自生長於此，且未常見漢成池中之物。\"高既無善政，諂佛佞神，亦已至矣，安可定其是非也夷陵清江有狼山潭，其中有龍。土豪李務求祷而事之，往見錦衾覆水，或浮出大木，橫塞水面，號為龍巢。遂州高棟溪潭，每歲龍見，一如狼山之事。","sortOrder":10},
  {"id":"s_work_bmtn_26_11","chapterId":"ch_work_bmtn_26","text":"王蜀時梓州有張溫者，好捕魚，曾作客馆镇將。夏中，携賓觀魚，偶遊近龍潭之下，熱甚，志不快，自入水舉網，獲一魚，長尺許，鬐鱗如金，拨剌不已，俯岸人皆異之。逡巡晦暝，風雨骤作。溫惶駭，奔走數里，依然烈景。或曰：\"所獲金魚即潭龍也。\"是知龍為魚服，自貽其患。苟無風雨之变，亦難逃鼎俎矣。龍潭取魚亦宜戒慎。","sortOrder":11},
  {"id":"s_work_bmtn_26_12","chapterId":"ch_work_bmtn_26","text":"世言乖龍苦於行雨而多竄匿，為雷神捕之，或在古木及楹柱之內。若曠野之無處逃匿，即入牛角或牧童之身，往往為此物所累而震死也。蜀邸有軍將郭彦郎者，行舟峡江，至羅雲溉，方食而臥，心神恍惚如夢，見一黃衣人曰\"莫错\"，而於口中探得一物而去。覺來但覺咽喉中痛，於時篙工辈但見船上雷電晦暝，震聲甚厲，斯則乖龍入口也。南山宣律師，乖龍入中指節，又非虛說。所以孔聖之言\"迅雷風烈必变\"，可不敬之乎","sortOrder":12},
  {"id":"s_work_bmtn_26_13","chapterId":"ch_work_bmtn_26","text":"後唐同光中，沧州民有子母苦於科徭，流移近界封店，路逢白蛇。其子以繩系蛇項，約而行，無何，摆其頭落。須臾，一片白雲起，雷電暴作，撮將此子上天，空中為雷火燒殺墜地，而背有大書，人莫之識。忽有一人雲：\"何不以青物蒙之，即識其字。\"遂以青裙被之，有識字讀之曰：\"此人殺害安天龍，為天神所誅。\"葆光子曰：\"龍，神物也，况有安天之號，必能变化無方。豈有一竖子繩系而殒之，遽致天神之罰，斯又何哉\"","sortOrder":13},
  {"id":"s_work_bmtn_26_14","chapterId":"ch_work_bmtn_26","text":"石晉時常山帥安重榮將謀幹紀，其管界與邢台連接，斗殺一龍。乡豪有曹宽者見之，取其双角，前有一物，如帘文，如亂錦，人莫知之。曹宽經年為寇所殺。壬寅年讨镇州，誅安重榮也。葆光子讀《北史》，見陆法和在梁時將兵拒侯景將任約於江上，曰：\"彼龍睡不動，吾軍之龍甚自踴躍。\"遂击之，大败而擒任約。是則軍陣之上龍必先斗，常山龍死，得非王師大捷、重榮授首乎黃巢败於陳州、李克用脱梁王之難，皆大雨震雷之助。","sortOrder":14},
  {"id":"s_work_bmtn_26_15","chapterId":"ch_work_bmtn_26","text":"王蜀先主時修斜穀閣道，鳳州衙將白掌其事焉。至武休潭，見一婦人浮水而來，意其溺者，命仆夫鉤至岸濱，忽化為大蛇，没於潭中。白公以為不祥，因而致疾，愚為誦岑參《招北客賦》雲：\"瞿塘之東，下有千歲老蛟，化為婦人，炫服靓妆，遊於水濱。\"白公聞之方悟蛟也，厥疾尋瘳。又內官宋愈昭自言於柳州江岸為二三女人所招，里民叫而止之，亦蛟也。岑賦所言，斯足為證。","sortOrder":15},
  {"id":"s_work_bmtn_26_16","chapterId":"ch_work_bmtn_26","text":"《月令》：\"季秋伐蛟取鼍。\"以明蛟可伐而龍不可觸也。蛟之為物，不識其形状，非有鱗鬣四足乎？或曰虬蜧蛟蝹，状如蛇也。南僧說蛟之形如馬蟥，即水蛭也，涎沫腥粘，掉尾纏人而噬其血，蜀人號為馬绊蛇，頭如猫鼠，有一點白。漢州古城潭內馬绊蛇往往害人，乡里募勇者伐之，身涂藥，遊泳於潭底，蛟乃躍於沙汭，蟠蜿力困，里人歡噪以助，竟毙之。","sortOrder":16},
  {"id":"s_work_bmtn_26_17","chapterId":"ch_work_bmtn_26","text":"唐大順、景福已後，蜀路劍、利之間白衛嶺、石筒溪虎暴尤甚，號稅人場。商旅結伴而行，軍人帶甲列队而過，亦遭攫搏。時遞鋪卒有周雄者，膂力心胆有異於常，日夜行役，不肯規避，仍持托杈利劍，前後於稅人場連毙數虎，行旅賴之。西川書記韦莊作長語以賞之，蜀帥補軍職以壮之。凡死於虎、溺於水之鬼號為伥，須得一人代之，雖聞泛言，往往而有。先是，西川監軍使魚全特進自京搬家，憩於漢源驿，其孀嫂方稅駕，遂嚴妆倚驿門而看，為虎攫去，雖驅奪得之，已傷鉤爪也。仆嘗行次白衛嶺，時屬炎蒸，夜涼而進，一馬二仆，與他人三五辈偕行，或前或後，而民家豚犬交橫道路，山林依然，居人如昔，虎豹之屬又复何之景福乾寧之時，三川兵革，虎豹晝行，任土貢输梗於前邁，西川奏章多取巫峡。大虫作暴，得非系國家之盛衰乎","sortOrder":17},
  {"id":"s_work_bmtn_26_18","chapterId":"ch_work_bmtn_26","text":"江陵松滋枝江村射鹿者率以淘河乌胫骨為管，以鹿心上脂膜作簧，吹作鹿聲，有大號小號呦呦之異，或麀鹿聲，則ば鹿畢集，蓋為牝聲所誘。人得彀矢而註之。南中多鹿，每一牡管牝百頭，至春羸瘦，蓋遊牝多也。及夏則唯食菖蒲一味，却肥。當角解之時，其茸甚痛，獵人逢之，其鹿不敢逸走，伏而不動，獵者以繩系其茸，截而取之，先以其血來啖，然後毙鹿，何其苦也欤！夫狨麝孔雀以有用贾害，良可愍之！","sortOrder":18},
  {"id":"s_work_bmtn_26_19","chapterId":"ch_work_bmtn_26","text":"猕猴見僧即必围繞，状如供養。戎瀘夷獠亦啖此物，但於野外石上跏趺而坐，以物蒙首，有如坐禪，則必相悅而來馴扰之，逡巡眾去，唯留一个伴假僧偶坐。僧以斧击，將歸充食。他日更要，亦如前法击之。然眾竟不之覺，又被人以其害稼，乃致酒糟盆盛措於野径，仍削木棒可長一二尺者三五十條於侧邊。其猴啖糟醉後，拈棒相击，腳手損折，由此併獲。是知嗜酒者得不鑒斯獸之贾害乎","sortOrder":19},
  {"id":"s_work_bmtn_26_20","chapterId":"ch_work_bmtn_26","text":"江南無野狐，江北無鹧鸪，舊說也。晉天福甲辰歲，公安縣沧渚村民辛家犬逐一婦人，登木而墜，為犬嚙死，乃老狐也，尾長七八尺。則正首之妖，江南不謂無也，但稀有耳。蜀中彭漢邛蜀絕無，唯山郡往往而有，里人號為野犬，更有黃腰，尾長頭黑，腰間焦黃，或於村落鳴，則有不祥事。","sortOrder":20},
  {"id":"s_work_bmtn_26_21","chapterId":"ch_work_bmtn_26","text":"梓潼縣張蝁子神乃五丁拔蛇之所也，或雲嶲州張生所養之蛇，因而祠，時人謂為張蝁子，甚神甚靈。伪蜀王建世子名元膺，聰明博達，騎射絕倫，牙齒常露，多以袖掩口，左右不敢仰视。蛇眼而黑色，凶惡鄙亵，通夜不寐，竟以作逆伏誅。就誅之夕，梓潼廟祝亟為蝁子所责，言：\"我久在川，今始方歸，何以致廟宇荒秽如是耶\"由是蜀人乃知元膺為廟蛇之精矣。","sortOrder":21},
  {"id":"s_work_bmtn_26_22","chapterId":"ch_work_bmtn_26","text":"孫光憲曾行次叙穀，宿於神山，見嶺上板屋中以木根為巨虺，前列香燈，因詰店叟：\"彼何神也\"叟曰：\"光化中，楊守亮镇褒日，有一蛇橫此嶺路，高七八尺，莫知其首尾，四面小蛇翼之無數。每一拖身，即林木摧折，殆旬半方過盡，阻絕行旅。因聚草焚燎路隅，慮其遺毒，然後方行。明年，楊伏誅。\"","sortOrder":22},
  {"id":"s_work_bmtn_26_23","chapterId":"ch_work_bmtn_26","text":"太原屬邑有清水池，本府祈祷雨泽及投龍之所也。後唐莊宗未過河南時，就郡捕獵，就池卓帳為憩宿之所。忽見巨蛇數頭自洞穴中出，皆入池中。良久，有一蛇，紅白色，遙見可围四尺以來，其長稱是。獵卒齊彀弩連發，射之而毙，四山火光，池中魚鱉鹹死，浮在水上。獵夫辈共刲剝食之，其肉甚美。莊宗尋知之，於時諂事者以為克梁之兆，有五台僧曰：\"吾王宜速過河决戰，將來梁祚其能久乎此亦斷白蛇之類也。\"","sortOrder":23},
  {"id":"s_work_bmtn_26_24","chapterId":"ch_work_bmtn_26","text":"恒州井陉縣丰隆山西北長穀中有毒蛇據之，能傷人，里民莫敢至其所。采藥人靳四翁入北山，忽聞風雨聲，乃上一孤石望之，見一條白蛇從東而來，可長三丈，急上一树，蟠在西南枝上，垂頭而歇。須臾，有一物如盤許大，似虾蟆，色如煙熏，褐土色，四足而跳，至蛇蟠树下仰视，蛇垂頭而死。自是蛇妖不作。前澧州有鵾鵊鶵，為蛇所吞。有物如虾蟆，吐白氣直冲，墜而致死，得非靳老所見之物乎。凡毒物必有能製者，殆天意也。","sortOrder":24},
  {"id":"s_work_bmtn_26_25","chapterId":"ch_work_bmtn_26","text":"南方有鸛，食蛇，每遇巨石，知其下有蛇，即於石前如道士禹步，其石阞然而轉，因得而啖。里人學其法者，伺其養鶵，緣树以篾絙縛其巢。鸛必作法而解之，乃鋪沙树底，俾足跡所印而仿學之。","sortOrder":25},
  {"id":"s_work_bmtn_26_26","chapterId":"ch_work_bmtn_26","text":"南人采龟溺，以其性妒而與蛇交。或雌蛇至，有相趁斗噬，力小致毙者。采時取雄龟置瓷碗及小盤中，於龟後以鏡照之。既見鏡中龟，即淫發而失溺。又以紙炷火上辦熱點其尻亦致失溺，然不及鏡照也。得於道士陳钊。又海上人雲龍生三卵，一為吉弔也。其吉弔上岸與鹿交，或於水邊遺精，流槎遇之，粘裹木枝，如蒲桃焉，色微青黃，复似灰色，號紫稍花，益陽道，別有方說。","sortOrder":26},
  {"id":"s_work_bmtn_26_27","chapterId":"ch_work_bmtn_26","text":"陳藏器《本草》雲：\"砂俘，又雲倒行拘子，蜀人號曰俘鬱。旋乾土為孔，常睡不動，取致枕中，令夫妻相悅。\"愚有親表曾得此物，未嘗试验。愚始遊成都。止於逆旅，與賣草藥李山人相熟，見蜀城少年往往欣然而訪，李生仍以善价酬。因詰之，曰\"媚藥\"。征其所用，乃砂俘，與陳氏所說信不虛語。李生亦秘其所傳之法，人不可得也。武陵山出媚草，無賴者以銀換之，有因其術而男女發狂，罹禍非細也。","sortOrder":27},
  {"id":"s_work_bmtn_26_28","chapterId":"ch_work_bmtn_26","text":"後唐莊宗過河，荆渚高季昌謂其門客梁震曰：\"某事梁祖仅獲自免，龍德已來止求安活。我今入觐，亦要嘗之。彼若經營四方，必不縻我。若移入他镇，可為子孫之福。此行决矣。\"既自闕回，謂震曰：\"新主百戰方得河南，對勋臣夸手鈔《春秋》，又竖指雲：'我於指頭上得天下。'則功在一人，臣佐何有且遊獵旬日不回，中外情何以堪吾高枕無忧。\"乃筑西面羅城拒敵之具。不三年，莊宗不守。英雄之料頃刻不差，宜乎貽厥子孫！","sortOrder":28},
  {"id":"s_work_bmtn_26_29","chapterId":"ch_work_bmtn_26","text":"王蜀黔南節度使王保義有女適荆南高從誨之子保節，未行前，暫寄羽服。性聰敏，善彈琵琶。因夢異人，頻授樂曲。所授之人，其形或道或俗，其衣或紫或黃。有一夕而傳數曲，有一聽而便記者。其聲清越，與常異，類於仙家紫雲之亚也。乃曰：\"此曲譜請元崑製序，刊石於甲寅之方。\"其兄即荆南推官王少監貞范也，為製序刊石。所傳曲有道調宮、玉宸宮、夷則宮、神林宮、蕤賓宮、無射宮、玄宗宮、黃鐘宮、散水宮、仲呂宮。商調獨指泛清商、好仙商、侧商、紅绡商、鳳抹商、玉仙商。角調双調角、醉吟角、大呂角、南呂角、中呂角、高大殖角、蕤賓角。羽調鳳吟羽、背風香、背南羽、背平羽、應聖羽、玉宮羽、玉宸羽、風香調、大呂調。其曲名一同人世，有《涼州》、《伊州》、《胡渭州》、《甘州》、《緣腰》、《草靼》、《項盆樂》、《安公子》、《水牯子》、《阿濫泛》之屬，凡二百以上曲。所異者，徵調中有湘妃怨、哭顏回。常時胡琴不彈徵調也。王適高氏，數年而亡。得非謫墜之人乎。孫光憲子婦即王氏之侄也，記得一兩曲，嘗聞彈之。亦異事也。","sortOrder":29},
  {"id":"s_work_bmtn_27_1","chapterId":"ch_work_bmtn_27","text":"●再補","sortOrder":1},
  {"id":"s_work_bmtn_27_2","chapterId":"ch_work_bmtn_27","text":"○五髭須","sortOrder":2},
  {"id":"s_work_bmtn_27_3","chapterId":"ch_work_bmtn_27","text":"江陵有村民，事伍子胥神，誤呼\"五髭須。\"乃畫五丈夫，皆胡腮，祝呼之，祭雲：\"一髭須，二髭須，五髭須。\"","sortOrder":3},
  {"id":"s_work_bmtn_27_4","chapterId":"ch_work_bmtn_27","text":"○射鹿","sortOrder":4},
  {"id":"s_work_bmtn_27_5","chapterId":"ch_work_bmtn_27","text":"唐州有民獵深山，射中一鹿，视之，乃人也。呼獵者曰：\"我隋初隱此山，今日合死於子之手，但置我石室間。\"獵者诺之，逡巡而絕。獵人旬日再往，即亡其尸矣。","sortOrder":5},
  {"id":"s_work_bmtn_27_6","chapterId":"ch_work_bmtn_27","text":"○六甲行厨","sortOrder":6},
  {"id":"s_work_bmtn_27_7","chapterId":"ch_work_bmtn_27","text":"修道功深者，享六甲行厨，凡有所須，舉意即至。","sortOrder":7},
  {"id":"s_work_bmtn_27_8","chapterId":"ch_work_bmtn_27","text":"○五彩纏梯","sortOrder":8},
  {"id":"s_work_bmtn_27_9","chapterId":"ch_work_bmtn_27","text":"冯涓失意蹭蹬，有詩雲：\"取水郎中何日了，破柴員外幾時休。\"年八十五，以五彩纏梯，穿屋，直冠帶，立梯一級而終。","sortOrder":9},
  {"id":"s_work_bmtn_27_10","chapterId":"ch_work_bmtn_27","text":"○點點師","sortOrder":10},
  {"id":"s_work_bmtn_27_11","chapterId":"ch_work_bmtn_27","text":"蜀州靈鷲山有僧，臥一室，常用手點胸，時號點點師。","sortOrder":11},
  {"id":"s_work_bmtn_27_12","chapterId":"ch_work_bmtn_27","text":"○煎餅招鬼","sortOrder":12},
  {"id":"s_work_bmtn_27_13","chapterId":"ch_work_bmtn_27","text":"夜作煎餅，多招鬼神。有儒生出通衢，有雲：昨夜崇福院僧作煎餅、肉羹，被我番其鼎器，其肉羹和灰埋花欄中。又一鬼於人家不得煎餅，推其小婢落火。复一鬼至，雲：\"我能医火燒瘡，爾但與我煎餅。\"因教之。有姬夜作煎餅，窗中忽露一青手，遺餅而没。","sortOrder":13},
  {"id":"s_work_bmtn_27_14","chapterId":"ch_work_bmtn_27","text":"○衣冠土枭","sortOrder":14},
  {"id":"s_work_bmtn_27_15","chapterId":"ch_work_bmtn_27","text":"起居郎蘇楷寢陋無行，人目為衣冠土枭。","sortOrder":15},
  {"id":"s_work_bmtn_27_16","chapterId":"ch_work_bmtn_27","text":"○白牡丹老嫗","sortOrder":16},
  {"id":"s_work_bmtn_27_17","chapterId":"ch_work_bmtn_27","text":"人之家道，切要防閒。嫠婦少、婢仆處子，不正之偶，往往有焉。有嫗號白牡丹，蓄下胎藥，臨終見婴兒無數，聚啖其腦。","sortOrder":17},
  {"id":"s_work_bmtn_27_18","chapterId":"ch_work_bmtn_27","text":"○誦天蓬咒","sortOrder":18},
  {"id":"s_work_bmtn_27_19","chapterId":"ch_work_bmtn_27","text":"曹肅西莊多為跨白鶴書生所魇。有魏處士夜見跨驢者所逐，誦《天蓬咒》，無恙。又夢鬼追之甚急，空中有人授大斧，一揮，人驢俱毙。","sortOrder":19},
  {"id":"s_work_bmtn_27_20","chapterId":"ch_work_bmtn_27","text":"○偷驢賊","sortOrder":20},
  {"id":"s_work_bmtn_27_21","chapterId":"ch_work_bmtn_27","text":"王先主微時，偷驢遭刑。攻東川，為守陴卒日夜叫\"偷驢賊。\"先主謂俳優王舍城曰：\"為我骂之。\"優戟手指城上人，且令靜聽，曰：\"我偷你屋里驢耶\"城上皆笑。一旦，袒背示舍城無瘡痕，舍城曰：\"大好，大好！何處得此膏藥\"","sortOrder":21},
  {"id":"s_work_bmtn_27_22","chapterId":"ch_work_bmtn_27","text":"○蜀主詩詞","sortOrder":22},
  {"id":"s_work_bmtn_27_23","chapterId":"ch_work_bmtn_27","text":"蜀後主荒於酒色，月夜每言\"惆怅惆怅\"，又雲：\"切道斷人生幾何，有分者任作傀儡。\"俘系入秦，至劍州，悅江水之美，詩雲：\"不緣朝帝闕，好此結茅庐。\"時人笑之。至鹹陽，撰曲子雲：\"盡是一場傀儡。\"與夫無愁入井者，所校無多也。","sortOrder":23},
  {"id":"s_work_bmtn_27_24","chapterId":"ch_work_bmtn_27","text":"○回避一抄夏供","sortOrder":24},
  {"id":"s_work_bmtn_27_25","chapterId":"ch_work_bmtn_27","text":"貫休戒行精嚴，求化養眾。徐簡夫曰：\"所在長老，有似蜣良，見爇粪盡，即然而飛。眾僧依長老相聚而食，僧亡，即索然而去。\"休怒，拂袖而出。簡夫曰：\"又回避得一抄夏供也。\"","sortOrder":25},
  {"id":"s_work_bmtn_27_26","chapterId":"ch_work_bmtn_27","text":"○替代","sortOrder":26},
  {"id":"s_work_bmtn_27_27","chapterId":"ch_work_bmtn_27","text":"荆南都頭李遇疾困，攝至陰府，逢一人先物故者曰：\"常侍安得此來\"复有一人雲：\"已追到李遇。\"遂蘇，見妻子泣，其身下臥一畫，人號替代。","sortOrder":27},
  {"id":"s_work_bmtn_27_28","chapterId":"ch_work_bmtn_27","text":"○識字亂情","sortOrder":28},
  {"id":"s_work_bmtn_27_29","chapterId":"ch_work_bmtn_27","text":"李義山《雜纂》雲：\"婦人識字即亂情，尤不可作詩，詩思不出二百里。\"","sortOrder":29},
  {"id":"s_work_bmtn_27_30","chapterId":"ch_work_bmtn_27","text":"○龍巢翻","sortOrder":30},
  {"id":"s_work_bmtn_27_31","chapterId":"ch_work_bmtn_27","text":"夷陵江或浮大木，蔽塞水面上，人謂之\"龍巢翻。\"","sortOrder":31},
  {"id":"s_work_bmtn_27_32","chapterId":"ch_work_bmtn_27","text":"○乞食歌姬院","sortOrder":32},
  {"id":"s_work_bmtn_27_33","chapterId":"ch_work_bmtn_27","text":"裴休披毳衲，於歌姬院持鉢乞食，曰：\"不為俗情所染，可以說法為人。\"","sortOrder":33},
  {"id":"s_work_bmtn_27_34","chapterId":"ch_work_bmtn_27","text":"○檢譜角觝","sortOrder":34},
  {"id":"s_work_bmtn_27_35","chapterId":"ch_work_bmtn_27","text":"顏王雲論兵，必攘袂叱咤，若對大敵，人號檢譜角觝。","sortOrder":35},
  {"id":"s_work_bmtn_27_36","chapterId":"ch_work_bmtn_27","text":"○僧鸞詩","sortOrder":36},
  {"id":"s_work_bmtn_27_37","chapterId":"ch_work_bmtn_27","text":"蜀沙門僧鸞，慕李白歌，鄙贾島蹇涩，乃自諷其詞雲：\"鯨目光燒半海紅，鰲頭浪蹙掀天白。\"而雲：\"我不能致思於藩篱蹄涔之間。\"人鹹服之。仍精於《周易》、佛經，為歌行掩之。贾島嘗為僧，洛陽令不許僧午後出寺，贾有詩雲：\"不如牛與羊，猶得自暮歸。\"詩思遲涩，杼軸方得。如\"鳥從井口出，人自嶽陽來。\"乃經年方遂偶句。","sortOrder":37},
  {"id":"s_work_bmtn_27_38","chapterId":"ch_work_bmtn_27","text":"○唐求劉郇伯","sortOrder":38},
  {"id":"s_work_bmtn_27_39","chapterId":"ch_work_bmtn_27","text":"唐求、劉郇伯有詩句。唐求《臨池洗砚》詩雲：\"恰似有龍深處臥，被人驚起黑雲生。\"又：\"漸寒沙上路，欲暝水邊村。\"《早行》雲：\"沙上鳥猶睡，渡頭人已行。\"詩思不出二百里間。劉郇伯為范鄭郎中詩友，范得句雲\"歲盡天涯雨\"，久而難對，以問於劉郇伯，曰：\"何不道'人生分外愁'。\"范賞之。然老於新津之東渡，非隱非吏。二子亦可凌厲名場，而死丘樊，所謂蜀人無志懷土，正此也。","sortOrder":39},
  {"id":"s_work_bmtn_27_40","chapterId":"ch_work_bmtn_27","text":"○这邊走那邊走","sortOrder":40},
  {"id":"s_work_bmtn_27_41","chapterId":"ch_work_bmtn_27","text":"蜀後主自裹小巾，其尖如錐，卿士皆同之。宮妓多衣道服，簪莲花冠，每侍燕酣醉，則容其同辈免冠，髽然其髻，別為一家之美。因施胭脂，粉頰莲額，號曰醉妆。國人效之。又作歌詞雲：\"这邊走，那邊走，只是尋花柳。那邊走，这邊走，莫厭金樽酒。\"又嬖佞韓昭、顧珣、潘迎等為狎客，競扠手搖頭令。唐師入境，遏其報而遊幸，師至利州方知。將士紛然曰：\"且打扠手搖頭。\"念周宣帝作歌曰：\"自知身命促，把燭夜行遊。\"令宮女連臂踏腳而歌，亦前歌之類。","sortOrder":41},
  {"id":"s_work_bmtn_27_42","chapterId":"ch_work_bmtn_27","text":"○僧中寤","sortOrder":42},
  {"id":"s_work_bmtn_27_43","chapterId":"ch_work_bmtn_27","text":"唐儀鳳中清城縣橫源翠围山下有民王仙柯，服道士所遺靈丹，拔宅上升，已具《仙傳拾遺》。蜀州僧中寤釋學道播於方州，偶於龍池山逢人精神爽朗，異於常叟，即王仙柯也。寤公曰：\"聞仙名已久，何幸相逢！飛升之後，胡為來此\"仙柯曰：\"吾等有靈藥，止能飛步。今全家隱於後山，更修道法，遐舉之事，吾何望焉。但長寿而已。\"寤公以詩赠之曰：\"瞻思不及望仙兄，早晚遐飛入太清。手种一株松未老，爐燒九轉藥新成。心中已得《黃庭》術，頭上應無白發生。異日却歸華表語，待教凡俗普聞名。\"自後不复遇。葆光子聞於真人曰：\"世人學道資一丹一藥，聊固其命，何以修道，未得證就，避忌尤多。三官巡邏，攝入鬼錄，所以頻改姓名，先用尸解。然後栖止靈嶽，進取上法，或五嶽授事，效職仙曹，優遊人間，或至千歲，功德升聞，即朝玉皇。海嶽之間往往遐舉者，世人無由知也。今之初得道者，止於仙隱。有騰空者，服金丹也。遐舉之事，未可希望。\"","sortOrder":43},
];

